def _grn_save_audit_ctx() -> str:
    try:
        return ' '.join([
            'user=%r' % (session.get('user') or ''),
            'tenant=%r' % (session.get('tenant_id') or ''),
            'loc_code=%s' % (session.get('location_code') if session.get('location_code') is not None else ''),
            'loc_name=%r' % str(session.get('location_name') or '')[:120],
        ])
    except Exception:
        return 'ctx=?'

def _grn_save_audit(fmt: str, *args: Any) -> None:
    try:
        _LOG_GRN_SAVE.info(fmt, *args)
    except Exception:
        pass

def _format_grn_integrity_error(ex: Exception) -> str:
    """Turn ORA-00001 into a specific message (not every unique violation is RECEIPTHDR)."""
    msg = str(ex or '')
    _grn_save_audit('SAVE integrity_violation %r | %s', msg[:800], _grn_save_audit_ctx())
    if 'ORA-00001' not in msg:
        return msg
    upper = msg.upper()
    if 'PK_RECEIPTHDR' in upper:
        return (
            'Receipt number is already in use (PK_RECEIPTHDR). '
            'Open the GRN list to find the existing receipt, or reload the form to use the next free number.'
        )
    if 'ITEMJOURNAL_PK' in upper or ('ITEMJOURNEL_PK' in upper):
        return (
            'Stock journal could not be posted: legacy unique index ITEMJOURNAL_PK still blocks '
            'RECEIPTNO+LINENO across document types (e.g. POS bill #1 and GRN #1). '
            'Restart the app after updating — the app will drop that index or use a separate '
            'RECEIPTNO namespace per SOURCE_DOC (GRN, BILL, POS, etc.).'
        )
    import re
    m = re.search(r'unique constraint \([\w.]+\.(\w+)\)', msg, re.I)
    cname = m.group(1) if m else ''
    if cname:
        return f'Receipt could not be saved: duplicate key on {cname}. {msg[:280]}'
    return f'Receipt could not be saved: duplicate key. {msg[:280]}'

