_AUDIT_HEADER_LABELS: Dict[str, str] = {
    'receipt_date': 'Receipt date',
    'return_date': 'Return date',
    'lpo_date': 'PO date',
    'supplier_code': 'Supplier',
    'invoice_no': 'Invoice no',
    'invoice_date': 'Invoice date',
    'invoice_amount': 'GRN amount',
    'return_amount': 'Return amount',
    'amount': 'Amount',
    'receipt_no': 'Receipt no',
    'discount': 'Discount',
    'other_charge': 'Other charge',
    'lpo_no': 'PO no',
    'warehouse_id': 'Warehouse',
    'remarks': 'Remarks',
}

_AUDIT_LINE_LABELS: Dict[str, str] = {
    'qty': 'Qty',
    'rate': 'Rate',
    'amount': 'Amount',
    'discount': 'Discount',
    'store': 'Store',
    'lot_id': 'Lot',
    'uom': 'UOM',
}

def _audit_compute_changes(before: Optional[Dict[str, Any]], after: Optional[Dict[str, Any]]) -> List[Dict[str, Any]]:
    changes: List[Dict[str, Any]] = []
    bh = (before or {}).get('header') or {}
    ah = (after or {}).get('header') or {}
    keys = sorted(set(bh.keys()) | set(ah.keys()))
    for key in keys:
        bv = bh.get(key)
        av = ah.get(key)
        if bv == av:
            continue
        changes.append({
            'scope': 'header',
            'field': key,
            'label': _AUDIT_HEADER_LABELS.get(key, key.replace('_', ' ').title()),
            'before': bv,
            'after': av,
        })
    b_lines = {( _audit_line_key(ln)): ln for ln in ((before or {}).get('lines') or [])}
    a_lines = {( _audit_line_key(ln)): ln for ln in ((after or {}).get('lines') or [])}
    all_keys = sorted(set(b_lines.keys()) | set(a_lines.keys()))
    for lk in all_keys:
        bl = b_lines.get(lk)
        al = a_lines.get(lk)
        if bl and not al:
            item = bl.get('item')
            changes.append({
                'scope': 'line',
                'field': 'line_removed',
                'label': f'Item {item} {bl.get("uom") or ""}'.strip(),
                'before': bl,
                'after': None,
            })
            continue
        if al and not bl:
            item = al.get('item')
            changes.append({
                'scope': 'line',
                'field': 'line_added',
                'label': f'Item {item} {al.get("uom") or ""}'.strip(),
                'before': None,
                'after': al,
            })
            continue
        if not bl or not al:
            continue
        item = bl.get('item') or al.get('item')
        base_label = f'Item {item} {bl.get("uom") or al.get("uom") or ""}'.strip()
        for fld in ('qty', 'rate', 'amount', 'discount', 'store', 'lot_id', 'uom'):
            if bl.get(fld) == al.get(fld):
                continue
            changes.append({
                'scope': 'line',
                'field': fld,
                'label': base_label,
                'before': bl.get(fld),
                'after': al.get(fld),
            })
    return changes

def _audit_build_meta(
    meta: Optional[Dict[str, Any]] = None,
    *,
    before: Optional[Dict[str, Any]] = None,
    after: Optional[Dict[str, Any]] = None,
    action: str = '',
) -> Dict[str, Any]:
    out: Dict[str, Any] = dict(meta or {})
    if before is not None:
        out['before'] = before
    if after is not None:
        out['after'] = after
    if before is not None and after is not None:
        out['changes'] = _audit_compute_changes(before, after)
    elif before is not None and str(action or '').upper() in ('DELETE', 'CANCEL'):
        out['changes'] = [{
            'scope': 'document',
            'field': 'status',
            'label': 'Document',
            'before': 'saved',
            'after': 'removed' if str(action).upper() == 'DELETE' else 'canceled',
        }]
    if before and isinstance(before.get('header'), dict):
        hdr = before['header']
        if hdr.get('supplier_code') is not None:
            out.setdefault('supplier_code', hdr.get('supplier_code'))
        if hdr.get('invoice_no'):
            out.setdefault('invoice_no', hdr.get('invoice_no'))
        if hdr.get('invoice_amount') is not None:
            out.setdefault('invoice_amount', hdr.get('invoice_amount'))
        if hdr.get('return_amount') is not None:
            out.setdefault('return_amount', hdr.get('return_amount'))
        if hdr.get('amount') is not None:
            out.setdefault('amount', hdr.get('amount'))
    if before and before.get('line_count') is not None:
        out.setdefault('line_count', before.get('line_count'))
    return out

def _log_purchase_change(
    doc_type: str,
    doc_no: Any,
    action: str,
    remarks: str = '',
    meta: Optional[Dict[str, Any]] = None,
    *,
    before: Optional[Dict[str, Any]] = None,
    after: Optional[Dict[str, Any]] = None,
) -> None:
    """Record EDIT / DELETE / CANCEL on purchase docs; never raises to caller."""
    try:
        loc_code = _resolve_location_code()
        user = (session.get('user') or 'web')[:100]
        dtype = (doc_type or '').strip().upper()[:30]
        act = (action or '').strip().upper()[:20]
        doc_bind = purchase_log_doc_no_bind(dtype, doc_no)
        if not dtype or not purchase_log_doc_no_is_valid(dtype, doc_no) or not act:
            return
        remarks_val = (remarks or '')[:500]
        full_meta = _audit_build_meta(meta, before=before, after=after, action=act)
        summary_meta = {k: v for k, v in full_meta.items() if k not in ('before', 'after')}
        meta_json = ''
        meta_detail = ''
        try:
            meta_json = json.dumps(summary_meta, ensure_ascii=False)[:4000]
        except Exception:
            meta_json = ''
        try:
            meta_detail = json.dumps(full_meta, ensure_ascii=False)
        except Exception:
            meta_detail = meta_json
        with _get_connection() as conn:
            _ensure_purchase_change_log_table(conn)
            with conn.cursor() as cur:
                cur.execute("\n                    INSERT INTO PURCHASE_CHANGE_LOG\n                        (LOG_ID, DOC_TYPE, DOC_NO, LOCATIONCODE, ACTION, ACTION_BY, REMARKS, META_JSON, META_DETAIL, ACTION_AT)\n                    VALUES\n                        (PURCHASE_CHANGE_LOG_SEQ.NEXTVAL, :dtype, :docno, :loc, :action, :usr, :remarks, :meta, :detail, SYSDATE)\n                    ", {
                    'dtype': dtype,
                    'docno': doc_bind,
                    'loc': loc_code,
                    'action': act,
                    'usr': user,
                    'remarks': remarks_val,
                    'meta': meta_json or None,
                    'detail': meta_detail or None,
                })
            conn.commit()
    except Exception:
        try:
            with _get_connection() as conn:
                _ensure_purchase_change_log_table(conn)
                with conn.cursor() as cur:
                    cur.execute("\n                        INSERT INTO PURCHASE_CHANGE_LOG\n                            (LOG_ID, DOC_TYPE, DOC_NO, LOCATIONCODE, ACTION, ACTION_BY, REMARKS, META_JSON, ACTION_AT)\n                        VALUES\n                            (PURCHASE_CHANGE_LOG_SEQ.NEXTVAL, :dtype, :docno, :loc, :action, :usr, :remarks, :meta, SYSDATE)\n                        ", {
                        'dtype': dtype,
                        'docno': doc_bind,
                        'loc': loc_code,
                        'action': act,
                        'usr': user,
                        'remarks': remarks_val,
                        'meta': meta_json or None,
                    })
                conn.commit()
        except Exception:
            pass

def _format_purchase_change_log_datetime(val: Any) -> str:
    if val is None:
        return ''
    if hasattr(val, 'strftime'):
        try:
            return val.strftime('%Y-%m-%d %H:%M')
        except Exception:
            pass
    s = str(val).strip()
    if len(s) >= 16:
        return s[:16].replace('T', ' ')
    return s[:19] if s else ''

def _list_purchase_change_log_rows(
    *,
    action_filter: str = 'all',
    doc_type_filter: str = 'all',
    date_from: Optional[str] = None,
    date_to: Optional[str] = None,
    search: Optional[str] = None,
    limit: int = 200,
    offset: int = 0,
) -> Dict[str, Any]:
    loc_code = _resolve_location_code()
    act_f = (action_filter or 'all').strip().lower()
    dtype_f = (doc_type_filter or 'all').strip().upper()
    lim = max(20, min(int(limit or 200), 500))
    off = max(0, int(offset or 0))
    where = ['LOCATIONCODE = :loc']
    params: Dict[str, Any] = {'loc': loc_code, 'lim': lim, 'off': off}
    if act_f == 'edit':
        where.append("ACTION IN ('EDIT', 'POST_INVENTORY')")
    elif act_f in ('delete', 'deleted'):
        where.append("ACTION IN ('DELETE', 'CANCEL')")
    if dtype_f not in ('', 'ALL'):
        where.append('DOC_TYPE = :dtype')
        params['dtype'] = dtype_f[:30]
    if date_from:
        try:
            df = datetime.strptime(date_from[:10], '%Y-%m-%d').strftime('%d-%b-%Y').upper()
            where.append('ACTION_AT >= TO_DATE(:df, \'DD-MON-YYYY\')')
            params['df'] = df
        except Exception:
            pass
    if date_to:
        try:
            dt = datetime.strptime(date_to[:10], '%Y-%m-%d').strftime('%d-%b-%Y').upper()
            where.append('ACTION_AT < TO_DATE(:dt, \'DD-MON-YYYY\') + 1')
            params['dt'] = dt
        except Exception:
            pass
    if search and str(search).strip():
        params['s'] = f'%{str(search).strip()}%'
        search_parts = [
            'TO_CHAR(DOC_NO) LIKE :s',
            'UPPER(ACTION_BY) LIKE UPPER(:s)',
            'UPPER(REMARKS) LIKE UPPER(:s)',
            'UPPER(META_JSON) LIKE UPPER(:s)',
        ]
        where.append('(' + ' OR '.join(search_parts) + ')')
    where_sql = ' AND '.join(where)
    rows_out: List[Dict[str, Any]] = []
    total = 0
    meta_detail_col = ''
    try:
        with _get_connection() as conn:
            _ensure_purchase_change_log_table(conn)
            with conn.cursor() as cur:
                cur.execute("SELECT COUNT(*) FROM user_tab_columns WHERE table_name = 'PURCHASE_CHANGE_LOG' AND column_name = 'META_DETAIL'")
                if int(cur.fetchone()[0] or 0) > 0:
                    meta_detail_col = ', META_DETAIL AS meta_detail'
                    if search and str(search).strip():
                        where[-1] = where[-1][:-1] + ' OR UPPER(META_DETAIL) LIKE UPPER(:s))'
    except Exception:
        meta_detail_col = ''
    where_sql = ' AND '.join(where)
    try:
        with _get_connection() as conn:
            _ensure_purchase_change_log_table(conn)
        cnt_q = f'SELECT COUNT(*) AS cnt FROM PURCHASE_CHANGE_LOG WHERE {where_sql}'
        _, cnt_rows = _fetch_rows(cnt_q, params)
        total = int((cnt_rows[0] or {}).get('cnt') or 0) if cnt_rows else 0
        q = f"\n            SELECT LOG_ID AS log_id, DOC_TYPE AS doc_type, DOC_NO AS doc_no,\n                   ACTION AS action, ACTION_BY AS action_by, REMARKS AS remarks,\n                   META_JSON AS meta_json{meta_detail_col}, ACTION_AT AS action_at\n            FROM PURCHASE_CHANGE_LOG\n            WHERE {where_sql}\n            ORDER BY ACTION_AT DESC, LOG_ID DESC\n            OFFSET :off ROWS FETCH NEXT :lim ROWS ONLY\n            "
        _, rows = _fetch_rows(q, params)
        for r in rows:
            meta_obj: Dict[str, Any] = {}
            raw_detail = r.get('meta_detail')
            raw_meta = r.get('meta_json')
            if raw_detail:
                try:
                    meta_obj = json.loads(str(raw_detail))
                except Exception:
                    meta_obj = {}
            if not meta_obj and raw_meta:
                try:
                    meta_obj = json.loads(str(raw_meta))
                except Exception:
                    meta_obj = {}
            rows_out.append({
                'log_id': int(r.get('log_id') or 0),
                'doc_type': str(r.get('doc_type') or '').upper(),
                'doc_no': int(r.get('doc_no') or 0),
                'action': str(r.get('action') or '').upper(),
                'action_by': str(r.get('action_by') or ''),
                'remarks': str(r.get('remarks') or ''),
                'action_at': _format_purchase_change_log_datetime(r.get('action_at')),
                'meta': meta_obj,
            })
    except Exception:
        rows_out = []
        total = 0
    return {'rows': rows_out, 'total': total, 'limit': lim, 'offset': off}

def _get_po_approval_status(lpo_no: Any) -> str:
    ensure_purchase_approval_docno_varchar()
    loc_code = _resolve_location_code()
    docno = _lpo_approval_doc_no(lpo_no)
    try:
        return _fetch_po_approval_status_row(docno, loc_code)
    except Exception as ex:
        if 'ORA-01722' in str(ex) and not isinstance(docno, int):
            n = billno_numeric_part(lpo_no)
            if n > 0:
                return _fetch_po_approval_status_row(int(n), loc_code)
        raise


def _fetch_po_approval_status_row(docno: Any, loc_code: int) -> str:
    with _get_connection() as conn:
        _ensure_purchase_approval_tables(conn)
        with conn.cursor() as cur:
            cur.execute("\n                SELECT STATUS\n                FROM PURCHASE_APPROVAL_TXN\n                WHERE DOC_TYPE = 'LPO' AND DOC_NO = :docno AND LOCATIONCODE = :loc\n                ", {'docno': docno, 'loc': loc_code})
            row = cur.fetchone()
    if row and row[0]:
        return str(row[0]).upper()
    return 'DRAFT'


def _set_po_approval_status(lpo_no: Any, status: str, action: str, remarks: str='') -> None:
    ensure_purchase_approval_docno_varchar()
    loc_code = _resolve_location_code()
    docno = _lpo_approval_doc_no(lpo_no)
    try:
        _write_po_approval_status_row(docno, loc_code, status, action, remarks)
    except Exception as ex:
        if 'ORA-01722' in str(ex) and not isinstance(docno, int):
            n = billno_numeric_part(lpo_no)
            if n > 0:
                _write_po_approval_status_row(int(n), loc_code, status, action, remarks)
                return
        raise


def _write_po_approval_status_row(docno: Any, loc_code: int, status: str, action: str, remarks: str='') -> None:
    user = (session.get('user') or 'web')[:100]
    status_val = (status or 'DRAFT').strip().upper()[:20]
    action_val = (action or status_val).strip().upper()[:20]
    remarks_val = (remarks or '')[:500]
    with _get_connection() as conn:
        _ensure_purchase_approval_tables(conn)
        with conn.cursor() as cur:
            cur.execute("\n                MERGE INTO PURCHASE_APPROVAL_TXN t\n                USING (SELECT :dtype AS DOC_TYPE, :docno AS DOC_NO, :loc AS LOCATIONCODE FROM dual) s\n                ON (t.DOC_TYPE = s.DOC_TYPE AND t.DOC_NO = s.DOC_NO AND t.LOCATIONCODE = s.LOCATIONCODE)\n                WHEN MATCHED THEN UPDATE SET\n                    t.STATUS = :status,\n                    t.UPDATED_AT = SYSDATE,\n                    t.REMARKS = :remarks,\n                    t.SUBMITTED_BY = CASE WHEN :status = 'SUBMITTED' THEN :usr WHEN :status IN ('DRAFT', 'CANCELLED') THEN NULL ELSE t.SUBMITTED_BY END,\n                    t.FINAL_APPROVED_BY = CASE WHEN :status = 'APPROVED' THEN :usr WHEN :status IN ('DRAFT', 'CANCELLED') THEN NULL ELSE t.FINAL_APPROVED_BY END,\n                    t.REJECTED_BY = CASE WHEN :status = 'REJECTED' THEN :usr WHEN :status IN ('DRAFT', 'CANCELLED') THEN NULL ELSE t.REJECTED_BY END\n                WHEN NOT MATCHED THEN INSERT\n                    (DOC_TYPE, DOC_NO, LOCATIONCODE, STATUS, CURRENT_LEVEL, CREATED_BY, SUBMITTED_BY, FINAL_APPROVED_BY, REJECTED_BY, REMARKS, UPDATED_AT)\n                VALUES\n                    (:dtype, :docno, :loc, :status, 1, :usr,\n                     CASE WHEN :status = 'SUBMITTED' THEN :usr ELSE NULL END,\n                     CASE WHEN :status = 'APPROVED' THEN :usr ELSE NULL END,\n                     CASE WHEN :status = 'REJECTED' THEN :usr ELSE NULL END,\n                     :remarks, SYSDATE)\n                ", {'dtype': 'LPO', 'docno': docno, 'loc': loc_code, 'status': status_val, 'usr': user, 'remarks': remarks_val})
            cur.execute("\n                INSERT INTO PURCHASE_APPROVAL_LOG\n                    (LOG_ID, DOC_TYPE, DOC_NO, LOCATIONCODE, LEVEL_NO, ACTION, ACTION_BY, REMARKS, ACTION_AT)\n                VALUES\n                    (PURCHASE_APPROVAL_LOG_SEQ.NEXTVAL, 'LPO', :docno, :loc, 1, :action, :usr, :remarks, SYSDATE)\n                ", {'docno': docno, 'loc': loc_code, 'action': action_val, 'usr': user, 'remarks': remarks_val})
        conn.commit()


def _get_po_status_map(lpo_nos: List[int]) -> Dict[int, str]:
    nos = sorted({int(x) for x in lpo_nos if int(x or 0) > 0})
    if not nos:
        return {}
    loc_code = _resolve_location_code()
    with _get_connection() as conn:
        _ensure_purchase_approval_tables(conn)
    in_list = ', '.join((str(n) for n in nos))
    q = f"SELECT DOC_NO AS docno, STATUS AS status FROM PURCHASE_APPROVAL_TXN WHERE DOC_TYPE = 'LPO' AND LOCATIONCODE = :loc AND DOC_NO IN ({in_list})"
    try:
        _, rows = _fetch_rows(q, {'loc': loc_code})
        out: Dict[int, str] = {}
        for r in rows:
            out[int(r.get('docno') or 0)] = str(r.get('status') or 'DRAFT').upper()
        return out
    except Exception:
        return {}


