def _write_purchase_doc_approval_status_row(
    dtype: str, docno: Any, loc_code: int, status: str, action: str, remarks: str = '',
) -> None:
    user = (session.get('user') or 'web')[:100]
    status_val = (status or 'DRAFT').strip().upper()[:20]
    action_val = (action or status_val).strip().upper()[:20]
    remarks_val = (remarks or '')[:500]
    with _get_connection() as conn:
        _ensure_purchase_approval_tables(conn)
        with conn.cursor() as cur:
            cur.execute("\n                MERGE INTO PURCHASE_APPROVAL_TXN t\n                USING (SELECT :dtype AS DOC_TYPE, :docno AS DOC_NO, :loc AS LOCATIONCODE FROM dual) s\n                ON (t.DOC_TYPE = s.DOC_TYPE AND t.DOC_NO = s.DOC_NO AND t.LOCATIONCODE = s.LOCATIONCODE)\n                WHEN MATCHED THEN UPDATE SET\n                    t.STATUS = :status,\n                    t.UPDATED_AT = SYSDATE,\n                    t.REMARKS = :remarks,\n                    t.SUBMITTED_BY = CASE WHEN :status = 'SUBMITTED' THEN :usr WHEN :status IN ('DRAFT', 'CANCELLED') THEN NULL ELSE t.SUBMITTED_BY END,\n                    t.FINAL_APPROVED_BY = CASE WHEN :status = 'APPROVED' THEN :usr WHEN :status IN ('DRAFT', 'CANCELLED') THEN NULL ELSE t.FINAL_APPROVED_BY END,\n                    t.REJECTED_BY = CASE WHEN :status = 'REJECTED' THEN :usr WHEN :status IN ('DRAFT', 'CANCELLED') THEN NULL ELSE t.REJECTED_BY END\n                WHEN NOT MATCHED THEN INSERT\n                    (DOC_TYPE, DOC_NO, LOCATIONCODE, STATUS, CURRENT_LEVEL, CREATED_BY, SUBMITTED_BY, FINAL_APPROVED_BY, REJECTED_BY, REMARKS, UPDATED_AT)\n                VALUES\n                    (:dtype, :docno, :loc, :status, 1, :usr,\n                     CASE WHEN :status = 'SUBMITTED' THEN :usr ELSE NULL END,\n                     CASE WHEN :status = 'APPROVED' THEN :usr ELSE NULL END,\n                     CASE WHEN :status = 'REJECTED' THEN :usr ELSE NULL END,\n                     :remarks, SYSDATE)\n                ", {'dtype': dtype, 'docno': docno, 'loc': loc_code, 'status': status_val, 'usr': user, 'remarks': remarks_val})
            cur.execute("\n                INSERT INTO PURCHASE_APPROVAL_LOG\n                    (LOG_ID, DOC_TYPE, DOC_NO, LOCATIONCODE, LEVEL_NO, ACTION, ACTION_BY, REMARKS, ACTION_AT)\n                VALUES\n                    (PURCHASE_APPROVAL_LOG_SEQ.NEXTVAL, :dtype, :docno, :loc, 1, :action, :usr, :remarks, SYSDATE)\n                ", {'dtype': dtype, 'docno': docno, 'loc': loc_code, 'action': action_val, 'usr': user, 'remarks': remarks_val})
        conn.commit()

def _set_purchase_doc_approval_status(doc_type: str, doc_no: Any, status: str, action: str, remarks: str='') -> None:
    ensure_purchase_approval_docno_varchar()
    loc_code = _resolve_location_code()
    dtype = (doc_type or '').strip().upper()[:30]
    docno = _purchase_approval_doc_no(dtype, doc_no)
    try:
        _write_purchase_doc_approval_status_row(dtype, docno, loc_code, status, action, remarks)
    except Exception as ex:
        if 'ORA-01722' in str(ex) and not isinstance(docno, int):
            n = billno_numeric_part(doc_no)
            if n > 0:
                _write_purchase_doc_approval_status_row(dtype, int(n), loc_code, status, action, remarks)
                return
        raise

def _get_return_request_approval_status(goods_return_no: int) -> str:
    return _get_purchase_doc_approval_status('PRR', goods_return_no)

def _get_return_request_status_map(goods_return_nos: List[int]) -> Dict[int, str]:
    return _get_purchase_doc_status_map('PRR', goods_return_nos)

def _set_return_request_approval_status(goods_return_no: int, status: str, action: str, remarks: str='') -> None:
    _set_purchase_doc_approval_status('PRR', goods_return_no, status, action, remarks)

def _warehouse_code_cached(warehouse_id: int, cache: Dict[int, str]) -> str:
    if warehouse_id in cache:
        return cache[warehouse_id]
    code = str(warehouse_id)
    try:
        wh = get_warehouse_master_by_id(int(warehouse_id))
        if wh:
            code = str(wh.get('warehouse_code') or '').strip() or str(warehouse_id)
    except Exception:
        pass
    cache[int(warehouse_id)] = code
    return code

def _uom_factor_from_uoms_list(uoms: List[Dict[str, Any]], uom_str: str) -> float:
    u = (uom_str or '').strip().upper()
    if not u:
        return 1.0
    for row in uoms or []:
        if (row.get('uom') or '').strip().upper() == u:
            try:
                f = float(row.get('factor') or 1)
                return f if f > 0 else 1.0
            except (TypeError, ValueError):
                return 1.0
    return 1.0

def _apply_item_uom_extras_from_cache(row: Dict[str, Any], item_uom_cache: Dict[int, List[Dict[str, Any]]]) -> None:
    try:
        ic = int(row.get('itemcode') or 0)
    except (TypeError, ValueError):
        ic = 0
    uom = (row.get('uom') or '').strip()
    if ic > 0 and ic not in item_uom_cache:
        item_uom_cache[ic] = _get_item_uoms_with_cost(ic)
    uoms = item_uom_cache.get(ic) or []
    factor = _uom_factor_from_uoms_list(uoms, uom)
    if factor == 1.0 and uom and ic > 0:
        factor = _get_uom_factor_for_item(ic, uom)
    row['uomfactor'] = factor
    uom_u = uom.upper()
    for u in uoms:
        if (u.get('uom') or '').strip().upper() == uom_u:
            row['avgcost'] = float(u.get('cost') or 0)
            bc = (u.get('barcode') or '').strip()
            if bc:
                row['barcode'] = bc
            break

def _enrich_po_detail_rows_for_grn(rows: List[Dict[str, Any]], lpo_no: Any, loc_code: int) -> None:
    """Fast path for GRN load-from-PO: cache UOM/cost per item; skip per-line receive-location queries."""
    if not rows:
        return
    po_wh_code: Optional[str] = None
    po_wid: Optional[int] = None
    try:
        if is_location_warehouse_enabled(int(loc_code)):
            po_wh_code = get_lpo_header_warehouse_code(lpo_no, location_code=int(loc_code), reset_no=RESET_NO)
            wid = get_lpo_header_warehouse_id(lpo_no, location_code=int(loc_code), reset_no=RESET_NO)
            if wid:
                po_wid = int(wid)
    except Exception:
        po_wh_code = None
        po_wid = None
    item_uom_cache: Dict[int, List[Dict[str, Any]]] = {}
    wh_code_cache: Dict[int, str] = {}
    for row in rows:
        v = row.get('foc')
        row['foc'] = v in (1, '1', 'Y', 'y', True, 'TRUE', 'True')
        _apply_item_uom_extras_from_cache(row, item_uom_cache)
        qty_val = float(row.get('quantity') or 0)
        bonus_val = float(row.get('bonus') or 0)
        factor = float(row.get('uomfactor') or 1)
        base_raw = row.get('baseqty')
        if base_raw is None or str(base_raw).strip() == '':
            row['baseqty'] = round(qty_val * factor + bonus_val, 3)
        else:
            try:
                row['baseqty'] = float(base_raw or 0)
            except Exception:
                row['baseqty'] = round(qty_val * factor + bonus_val, 3)
        recv_code: Optional[str] = None
        line_wid: Optional[int] = None
        line_wh_raw = row.get('warehouse_id')
        if line_wh_raw not in (None, ''):
            try:
                line_wid = int(line_wh_raw)
                if line_wid > 0:
                    recv_code = _warehouse_code_cached(line_wid, wh_code_cache)
            except (TypeError, ValueError):
                line_wid = None
        if not recv_code and row.get('warehouse_code'):
            recv_code = str(row.get('warehouse_code') or '').strip() or None
        if not recv_code and po_wh_code:
            recv_code = po_wh_code
            if po_wid:
                row['warehouse_id'] = po_wid
        if recv_code:
            row['warehouse_code'] = recv_code
            row['location'] = recv_code
            row['inventorylocation'] = recv_code
            row['locations'] = [{'code': recv_code, 'stock': 0}]
            row['from_itemstore'] = False
            if line_wid and line_wid > 0:
                row['warehouse_id'] = line_wid
            continue
        row['locations'] = []
        row['from_itemstore'] = False
        row['inventorylocation'] = None

def _enrich_receipt_detail_rows(rows: List[Dict[str, Any]]) -> None:
    """Batch UOM factor / landing cost enrichment for GRN query mode (avoid N+1 queries)."""
    if not rows:
        return
    item_uom_cache: Dict[int, List[Dict[str, Any]]] = {}
    for row in rows:
        row['foc'] = row.get('foc') in (1, '1', 'Y', 'y', True, 'TRUE', 'True')
        try:
            ic = int(row.get('itemcode') or 0)
        except (TypeError, ValueError):
            ic = 0
        uom = (row.get('uom') or '').strip()
        if ic > 0 and ic not in item_uom_cache:
            item_uom_cache[ic] = _get_item_uoms_with_cost(ic)
        factor = _uom_factor_from_uoms_list(item_uom_cache.get(ic) or [], uom)
        if factor == 1.0 and uom and ic > 0:
            factor = _get_uom_factor_for_item(ic, uom)
        row['uomfactor'] = factor
        qty_val = float(row.get('quantity') or 0)
        bonus = float(row.get('bonus') or 0)
        rcv_val = abs(float(row.get('receivedqty') or qty_val or 0))
        base_raw = row.get('baseqty')
        if base_raw is None or str(base_raw).strip() == '':
            ordered_b = qty_val * factor + bonus
            if qty_val > 1e-09 and rcv_val > 1e-12:
                row['baseqty'] = round(ordered_b * (rcv_val / qty_val), 3)
            else:
                row['baseqty'] = round((rcv_val if rcv_val > 1e-12 else qty_val) * factor + bonus, 3)
        else:
            try:
                row['baseqty'] = float(base_raw or 0)
            except Exception:
                ordered_b = qty_val * factor + bonus
                if qty_val > 1e-09 and rcv_val > 1e-12:
                    row['baseqty'] = round(ordered_b * (rcv_val / qty_val), 3)
                else:
                    row['baseqty'] = round((rcv_val if rcv_val > 1e-12 else qty_val) * factor + bonus, 3)
        try:
            land_raw = row.get('landingcost')
            land_f = float(land_raw) if land_raw not in (None, '') else 0.0
        except (TypeError, ValueError):
            land_f = 0.0
        if land_f <= 0:
            bq = float(row.get('baseqty') or 0)
            amt = float(row.get('amount') or 0)
            och = float(row.get('othercharge') or 0)
            if bq > 1e-09:
                land_f = (amt + och) / bq
        row['landingcost'] = round(land_f, 3)
        try:
            avg_raw = row.get('averagecost')
            avg_f = float(avg_raw) if avg_raw not in (None, '') else 0.0
        except (TypeError, ValueError):
            avg_f = 0.0
        if avg_f <= 0:
            avg_f = land_f if land_f > 0 else float(row.get('rate') or 0) / max(factor, 1.0)
        row['averagecost'] = round(avg_f, 3)
        row['avgcost'] = row['averagecost']
        wc = str(row.get('warehouse_code') or row.get('location') or '').strip()
        if wc:
            row['warehouse_code'] = wc
            row['location'] = wc
            row['inventorylocation'] = wc

def _get_lpo_details(lpo_no: Any) -> List[Dict[str, Any]]:
    dtl = _detect_table(['LPODTL', 'lpodtl'])
    if not dtl:
        return []
    ensure_lpodtl_warehouse_columns(dtl)
    lpo_col = _detect_column(dtl, ['LPONO', 'LPO_NO', 'lpono'])
    item_col = _detect_column(dtl, ['ITEMCODE', 'ITEM_CODE', 'itemcode'])
    qty_col = _detect_column(dtl, ['QUANTITY', 'quantity'])
    rate_col = _detect_column(dtl, ['RATE', 'rate'])
    uom_col = _detect_column(dtl, ['UNITOFMEASUREMENT', 'UNIT_OF_MEASUREMENT', 'unitofmeasurement'])
    loc_col = _detect_column(dtl, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    reset_col = _detect_column(dtl, ['RESETNO', 'RESET_NO', 'resetno'])
    if not lpo_col or not item_col:
        return []
    loc_code = _resolve_location_code()
    im_tbl = _detect_table(['ITEMMASTER', 'itemmaster', 'ITEM_MASTER'])
    im_code = _detect_column(im_tbl, ['ITEMCODE', 'ITEM_CODE', 'itemcode']) if im_tbl else None
    im_name = _detect_column(im_tbl, ['ITEMNAME', 'ITEM_NAME', 'itemname']) if im_tbl else None
    im_loc = _detect_column(im_tbl, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode']) if im_tbl else None
    d_disc = _detect_column(dtl, ['DISCOUNT', 'discount'])
    d_bonus = _detect_column(dtl, ['BONUS', 'bonus'])
    d_foc = _detect_column(dtl, ['FOC', 'foc'])
    d_other = _detect_column(dtl, ['OTHERCHARGE', 'OTHER_CHARGE', 'othercharge'])
    d_landing = _detect_column(dtl, ['LANDINGCOST', 'LANDING_COST', 'landingcost'])
    d_barcode = _detect_column(dtl, list(LPODTL_BARCODE_COLUMN_DETECT))
    d_wh = _detect_column(dtl, ['WAREHOUSE_ID', 'warehouse_id'])
    d_wh_code = lpodtl_warehouse_code_column(dtl)
    d_base = _detect_column(dtl, ['BASEQTY', 'BASE_QTY', 'baseqty'])
    inq_col = _detect_column(dtl, ['INQUANTITY', 'IN_QUANTITY', 'inquantity', 'INQUANTTITY', 'IN_QUANTTITY', 'inquanttity', 'INQTY', 'IN_QTY', 'inqty'])
    if im_tbl and im_code and im_name:
        cols = [f'{dtl}.{item_col} AS itemcode', f'{dtl}.{d_barcode} AS barcode' if d_barcode else 'NULL AS barcode', f'{im_tbl}.{im_name} AS itemname', f'{dtl}.{qty_col} AS quantity' if qty_col else '0 AS quantity', f'{dtl}.{inq_col} AS inquantity' if inq_col else 'NULL AS inquantity', f'{dtl}.{rate_col} AS rate' if rate_col else '0 AS rate', f'{dtl}.{d_bonus} AS bonus' if d_bonus else '0 AS bonus', f'{dtl}.{d_disc} AS discount' if d_disc else '0 AS discount', f'{dtl}.{d_foc} AS foc' if d_foc else '0 AS foc', f'{dtl}.{d_other} AS othercharge' if d_other else '0 AS othercharge', f'{dtl}.{d_landing} AS landingcost' if d_landing else 'NULL AS landingcost', f'{dtl}.{d_base} AS baseqty' if d_base else 'NULL AS baseqty', f'{dtl}.{uom_col} AS uom' if uom_col else 'NULL AS uom', f'{dtl}.{d_wh_code} AS warehouse_code' if d_wh_code else 'NULL AS warehouse_code', f'{dtl}.{d_wh} AS warehouse_id' if d_wh else 'NULL AS warehouse_id']
        where = f' {dtl}.{lpo_col} = :lpo '
        params = {'lpo': coerce_lpono(lpo_no)}
        if loc_col:
            where += f' AND {dtl}.{loc_col} = :loc'
            params['loc'] = loc_code
        if reset_col:
            where += f' AND {dtl}.{reset_col} = :rn'
            params['rn'] = RESET_NO
        join_on = f'{dtl}.{item_col} = {im_tbl}.{im_code}'
        if loc_col and im_loc:
            join_on += f' AND {dtl}.{loc_col} = {im_tbl}.{im_loc}'
        q = f"SELECT {', '.join(cols)} FROM {dtl} LEFT JOIN {im_tbl} ON {join_on} WHERE {where} ORDER BY {dtl}.{item_col}"
    else:
        cols = [f'{item_col} AS itemcode', f'{d_barcode} AS barcode' if d_barcode else 'NULL AS barcode', 'NULL AS itemname', f'{qty_col} AS quantity' if qty_col else '0 AS quantity', f'{inq_col} AS inquantity' if inq_col else 'NULL AS inquantity', f'{rate_col} AS rate' if rate_col else '0 AS rate', f'{d_bonus} AS bonus' if d_bonus else '0 AS bonus', f'{d_disc} AS discount' if d_disc else '0 AS discount', f'{d_foc} AS foc' if d_foc else '0 AS foc', f'{d_other} AS othercharge' if d_other else '0 AS othercharge', f'{d_landing} AS landingcost' if d_landing else 'NULL AS landingcost', f'{d_base} AS baseqty' if d_base else 'NULL AS baseqty', f'{uom_col} AS uom' if uom_col else 'NULL AS uom', f'{d_wh_code} AS warehouse_code' if d_wh_code else 'NULL AS warehouse_code', f'{d_wh} AS warehouse_id' if d_wh else 'NULL AS warehouse_id']
        where = f' {lpo_col} = :lpo '
        params = {'lpo': coerce_lpono(lpo_no)}
        if loc_col:
            where += f' AND {loc_col} = :loc'
            params['loc'] = loc_code
        if reset_col:
            where += f' AND {reset_col} = :rn'
            params['rn'] = RESET_NO
        q = f"SELECT {', '.join(cols)} FROM {dtl} WHERE {where} ORDER BY {item_col}"
    try:
        _, rows = _fetch_rows(q, params)
        _enrich_po_detail_rows_for_grn(rows, lpo_no, loc_code)
        return rows
    except Exception:
        return []

def _save_lpo(lpo_no: Any, lpo_date: str, supplier_code: int, discount: float, other_charge: float, remarks: str, lines: List[Dict[str, Any]], warehouse_id: Optional[int]=None) -> Optional[str]:
    hdr = _detect_table(['LPOHDR', 'lpohdr'])
    dtl = _detect_table(['LPODTL', 'lpodtl'])
    if not hdr or not dtl:
        return 'LPO tables not found'
    ensure_lpodtl_warehouse_columns(dtl)
    _ensure_lpo_hdr_extension_columns()
    loc_code = _resolve_location_code()
    loc_col = _detect_column(hdr, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    reset_col = _detect_column(hdr, ['RESETNO', 'RESET_NO', 'resetno'])
    no_col = _detect_column(hdr, ['LPONO', 'LPO_NO', 'lpono'])
    date_col = _detect_column(hdr, ['LPODATE', 'LPO_DATE', 'lpodate'])
    sup_col = _detect_column(hdr, ['SUPPLIERCODE', 'SUPPLIER_CODE', 'suppliercode'])
    amt_col = _detect_column(hdr, ['LPOAMOUNT', 'LPO_AMOUNT', 'lpoamount'])
    rem_col = _detect_column(hdr, ['REMARKS', 'remarks'])
    wh_col = _detect_column(hdr, ['WAREHOUSE_ID', 'warehouse_id'])
    disc_col = _detect_column(hdr, ['DISCOUNT', 'discount'])
    other_col = _detect_column(hdr, ['OTHERCHARGE', 'OTHER_CHARGE', 'othercharge'])
    total_amt_col = _detect_column(hdr, ['TOTALAMOUNT', 'TOTAL_AMOUNT', 'totalamount'])
    net_col = _detect_column(hdr, ['NETAMOUNT', 'netamount'])
    del_col = _detect_column(hdr, ['DELFLAG', 'DEL_FLAG', 'delflag'])
    lrflag_col = _detect_column(hdr, ['LRFLAG', 'lrflag', 'LR_FLAG', 'lr_flag'])
    created_col = _detect_column(hdr, ['CREATEDBY', 'CREATED_BY', 'createdby'])
    created_date_col = _detect_column(hdr, ['CREATEDDATE', 'CREATED_DATE', 'createddate'])
    modified_col = _detect_column(hdr, ['MODIFIEDBY', 'MODIFIED_BY', 'modifiedby'])
    modified_date_col = _detect_column(hdr, ['MODIFIEDDATE', 'MODIFIED_DATE', 'modifieddate'])
    if not all([loc_col, no_col, date_col, sup_col]):
        return 'LPO header columns not found'
    prev_created_by, prev_created_date = _lpo_fetch_existing_audit(hdr, coerce_lpono(lpo_no), int(loc_code), reset_col)
    user = (session.get('user') or 'web')[:50].replace("'", "''")
    wh_val: Optional[int] = None
    if warehouse_id not in (None, ''):
        try:
            wh_val = int(warehouse_id)
            if wh_val <= 0:
                wh_val = None
        except (TypeError, ValueError):
            wh_val = None
    try:
        date_fmt = datetime.strptime(lpo_date[:10], '%Y-%m-%d').strftime('%d-%b-%Y').upper()
    except Exception:
        date_fmt = lpo_date[:10]
    total = sum((float(l.get('amount') or l.get('rate', 0) * float(l.get('quantity') or 0)) for l in lines))
    total -= float(discount or 0)
    total += float(other_charge or 0)
    d_loc = _detect_column(dtl, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    d_reset = _detect_column(dtl, ['RESETNO', 'RESET_NO', 'resetno'])
    d_lpo = _detect_column(dtl, ['LPONO', 'LPO_NO', 'lpono'])
    with _get_connection() as conn:
        try:
            with conn.cursor() as cur:
                if d_lpo:
                    dw_parts = [f'{d_lpo} = :lpo']
                    dp: Dict[str, Any] = {'lpo': coerce_lpono(lpo_no)}
                    if d_loc:
                        dw_parts.append(f'{d_loc} = :loc')
                        dp['loc'] = loc_code
                    if d_reset:
                        dw_parts.append(f'{d_reset} = :rn')
                        dp['rn'] = RESET_NO
                    cur.execute(f"DELETE FROM {dtl} WHERE {' AND '.join(dw_parts)}", dp)
                hw_parts = [f'{no_col} = :lpo']
                hp: Dict[str, Any] = {'lpo': coerce_lpono(lpo_no)}
                if loc_col:
                    hw_parts.append(f'{loc_col} = :loc')
                    hp['loc'] = loc_code
                if reset_col:
                    hw_parts.append(f'{reset_col} = :rn')
                    hp['rn'] = RESET_NO
                cur.execute(f"DELETE FROM {hdr} WHERE {' AND '.join(hw_parts)}", hp)
                ins_cols = [loc_col, reset_col or '1', no_col, date_col, sup_col]
                ins_vals = [str(loc_code), str(RESET_NO), _lpo_sql_literal(lpo_no), f"TO_DATE('{date_fmt}', 'DD-MON-YYYY')", str(supplier_code)]
                if del_col:
                    ins_cols.append(del_col)
                    ins_vals.append("'N'")
                if lrflag_col:
                    ins_cols.append(lrflag_col)
                    ins_vals.append("'N'")
                if created_col:
                    ins_cols.append(created_col)
                    cby = (str(prev_created_by or '').strip()[:50] or user).replace("'", "''")
                    ins_vals.append(f"'{cby}'")
                if created_date_col:
                    ins_cols.append(created_date_col)
                    ins_vals.append(_lpo_oracle_date_literal(prev_created_date) if prev_created_date else 'SYSDATE')
                if modified_col:
                    ins_cols.append(modified_col)
                    ins_vals.append(f"'{user}'")
                if modified_date_col:
                    ins_cols.append(modified_date_col)
                    ins_vals.append('SYSDATE')
                if amt_col:
                    ins_cols.append(amt_col)
                    ins_vals.append(str(total))
                if total_amt_col and (not amt_col or total_amt_col.upper() != amt_col.upper()):
                    ins_cols.append(total_amt_col)
                    ins_vals.append(str(total))
                if net_col:
                    ins_cols.append(net_col)
                    ins_vals.append(str(round(total, 3)))
                if disc_col:
                    ins_cols.append(disc_col)
                    ins_vals.append(str(discount or 0))
                if other_col:
                    ins_cols.append(other_col)
                    ins_vals.append(str(other_charge or 0))
                if rem_col:
                    ins_cols.append(rem_col)
                    ins_vals.append(f"'{str(remarks or '')[:500].replace(chr(39), chr(39) + chr(39))}'")
                if wh_col and wh_val is not None:
                    ins_cols.append(wh_col)
                    ins_vals.append(str(wh_val))
                cur.execute(f"INSERT INTO {hdr} ({', '.join(ins_cols)}) VALUES ({', '.join(ins_vals)})")
                d_lineno = _detect_column(dtl, ['LINENO', 'LINE_NO', 'lineno'])
                d_item = _detect_column(dtl, ['ITEMCODE', 'ITEM_CODE', 'itemcode'])
                d_barcode = _detect_column(dtl, list(LPODTL_BARCODE_COLUMN_DETECT))
                d_qty = _detect_column(dtl, ['QUANTITY', 'quantity'])
                d_rate = _detect_column(dtl, ['RATE', 'rate'])
                d_bonus = _detect_column(dtl, ['BONUS', 'bonus'])
                d_disc = _detect_column(dtl, ['DISCOUNT', 'discount'])
                d_amt = _detect_column(dtl, ['AMOUNT', 'amount'])
                d_foc = _detect_column(dtl, ['FOC', 'foc'])
                d_other = _detect_column(dtl, ['OTHERCHARGE', 'OTHER_CHARGE', 'othercharge'])
                d_landing = _detect_column(dtl, ['LANDINGCOST', 'LANDING_COST', 'landingcost'])
                d_uom = _detect_column(dtl, ['UNITOFMEASUREMENT', 'UNIT_OF_MEASUREMENT', 'unitofmeasurement'])
                d_base = _detect_column(dtl, ['BASEQTY', 'BASE_QTY', 'baseqty'])
                d_wh = _detect_column(dtl, ['WAREHOUSE_ID', 'warehouse_id'])
                d_wh_code = lpodtl_warehouse_code_column(dtl)
                for idx, line in enumerate(lines, 1):
                    item_raw = line.get('itemcode') or line.get('item_code')
                    if item_raw is None or str(item_raw).strip() == '':
                        continue
                    try:
                        item = int(float(str(item_raw).strip()))
                    except (TypeError, ValueError):
                        raise ValueError(f'Line {idx}: invalid item code ({item_raw!r}). Use your warehouse numeric item code — fix rows in red after invoice import before saving.')
                    if item <= 0:
                        continue
                    line_barcode = (line.get('barcode') or '')[:50].replace("'", "''")
                    qty = float(line.get('quantity') or 0)
                    rate = float(line.get('rate') or 0)
                    line_bonus = float(line.get('bonus') or 0)
                    line_disc = float(line.get('discount') or 0)
                    line_other = float(line.get('othercharge') or 0)
                    line_foc = line.get('foc') in (True, 1, '1', 'Y', 'y')
                    line_amt = 0.0 if line_foc else float(line.get('amount') or qty * rate - line_disc)
                    uom = (line.get('uom') or 'NOS')[:20].replace("'", "''")
                    try:
                        base_qty = float(line.get('baseqty') or 0)
                    except Exception:
                        base_qty = 0.0
                    if base_qty <= 0:
                        base_qty = qty * _get_uom_factor_for_item(item, uom) + line_bonus
                    try:
                        line_landing = float(line.get('landingcost') or 0)
                    except Exception:
                        line_landing = 0.0
                    if line_landing <= 0:
                        line_landing = (line_amt + line_other) / base_qty if base_qty > 0 else 0.0
                    d_cols = [d_loc, d_reset or '1', d_lpo, d_item, d_qty, d_rate]
                    d_vals = [str(loc_code), str(RESET_NO), _lpo_sql_literal(lpo_no), str(item), str(qty), str(rate)]
                    if d_barcode:
                        d_cols.append(d_barcode)
                        d_vals.append(f"'{line_barcode}'")
                    if d_bonus:
                        d_cols.append(d_bonus)
                        d_vals.append(str(line_bonus))
                    if d_disc:
                        d_cols.append(d_disc)
                        d_vals.append(str(line_disc))
                    if d_foc:
                        d_cols.append(d_foc)
                        d_vals.append('1' if line_foc else '0')
                    if d_other:
                        d_cols.append(d_other)
                        d_vals.append(str(line_other))
                    if d_amt:
                        d_cols.append(d_amt)
                        d_vals.append(str(line_amt))
                    if d_landing:
                        d_cols.append(d_landing)
                        d_vals.append(str(round(line_landing, 3)))
                    if d_lineno:
                        d_cols.append(d_lineno)
                        d_vals.append(str(idx))
                    if d_uom:
                        d_cols.append(d_uom)
                        d_vals.append(f"'{uom}'")
                    if d_base:
                        d_cols.append(d_base)
                        d_vals.append(str(base_qty))
                    line_wh_val: Optional[int] = None
                    line_wh_raw = line.get('warehouse_id')
                    if line_wh_raw not in (None, ''):
                        try:
                            line_wh_val = int(line_wh_raw)
                            if line_wh_val <= 0:
                                line_wh_val = None
                        except (TypeError, ValueError):
                            line_wh_val = None
                    if line_wh_val is None:
                        line_wh_val = wh_val
                    if d_wh and line_wh_val is not None:
                        d_cols.append(d_wh)
                        d_vals.append(str(line_wh_val))
                    line_wh_code_save = _line_warehouse_code_from_payload(line, line_wh_val or wh_val)
                    if d_wh_code and line_wh_code_save:
                        esc_wc = line_wh_code_save.replace(chr(39), chr(39) + chr(39))
                        d_cols.append(d_wh_code)
                        d_vals.append(f"'{esc_wc}'")
                    cur.execute(f"INSERT INTO {dtl} ({', '.join(d_cols)}) VALUES ({', '.join(d_vals)})")
            conn.commit()
            return None
        except ValueError as ve:
            try:
                conn.rollback()
            except Exception:
                pass
            return str(ve)
        except Exception:
            try:
                conn.rollback()
            except Exception:
                pass
            raise

def _build_lpo_pdf_bytes(lpo_no: Any) -> tuple:
    if not REPORTLAB_AVAILABLE:
        return (None, 'PDF library (reportlab) is not available.')
    header = _get_lpo_header(lpo_no)
    if not header:
        return (None, 'LPO not found.')
    lines = _get_lpo_details(lpo_no)
    supplier_code = str(header.get('suppliercode') or '').strip()
    supplier = _get_supplier_profile(supplier_code)
    company = _get_company_profile()
    supplier_name = str(supplier.get('name') or '')
    supplier_address = str(supplier.get('address') or '')
    supplier_gstin = str(supplier.get('gstin') or '')
    supplier_phone = str(supplier.get('phone') or '')
    supplier_email = str(supplier.get('email') or '')
    supplier_contact = str(supplier.get('contact') or '')
    company_name = str(company.get('name') or session.get('location_name') or '')
    company_address = str(company.get('address') or '')
    company_gstin = str(company.get('gstin') or '')
    company_phone = str(company.get('phone') or '')
    company_email = str(company.get('email') or '')
    company_contact = str(company.get('contact') or '')
    discount = float(header.get('discount') or 0)
    other_charge = float(header.get('othercharge') or 0)
    lpo_date = str(header.get('lpodate') or '')
    lpo_dt = None
    try:
        lpo_dt = datetime.strptime(lpo_date[:10], '%Y-%m-%d')
    except Exception:
        lpo_dt = None
    po_date_display = lpo_dt.strftime('%d-%m-%Y') if lpo_dt else lpo_date
    po_expiry = '7 days'
    payment_date_label = f'Payment Date: {po_expiry} from date of delivery'
    payment_terms_label = 'Payment Terms: 100% against invoice'
    username = str(session.get('user') or '')
    status_text = str(header.get('approval_status') or 'DRAFT')
    item_meta = _get_item_meta_map([str(ln.get('itemcode') or '') for ln in lines or []])
    subtotal = 0.0
    table_rows = [['S.No', 'Product Code', 'Product Name', 'Barcode', 'Quantity', 'Units', 'Rate', 'Tax', 'Amount']]
    for idx, ln in enumerate(lines or [], 1):
        code = str(ln.get('itemcode') or '')
        qty = float(ln.get('quantity') or 0)
        rate = float(ln.get('rate') or 0)
        disc = float(ln.get('discount') or 0)
        oth = float(ln.get('othercharge') or 0)
        is_foc = ln.get('foc') in (True, 1, '1', 'Y', 'y')
        amt = 0.0 if is_foc else float(ln.get('amount') or max(0.0, qty * rate - disc + oth))
        subtotal += amt
        barcode = str(ln.get('barcode') or '')
        tax_raw = (item_meta.get(code) or {}).get('tax')
        try:
            tax_txt = f'{float(tax_raw):.0f}%'
        except Exception:
            tax_txt = ''
        amt_display = 'FOC' if is_foc else f'{amt:.2f}'
        table_rows.append([str(idx), code, str(ln.get('itemname') or ''), barcode, f'{qty:.2f}', str(ln.get('uom') or 'nos').lower(), f'{rate:.3f}', tax_txt, amt_display])
    lpo_total = float(header.get('lpoamount') or subtotal - discount + other_charge)
    remarks = str(header.get('remarks') or '')
    tenant_logo_abs = ''
    branch_logo_abs = ''
    try:
        tid = str(session.get('tenant_id') or '').strip()
        if tid:
            t = get_tenant_by_id(tid) or {}
            logo_rel = str(t.get('logo_path') or '').strip()
            if logo_rel:
                candidate = os.path.abspath(os.path.join(bp.root_path, '..', 'static', logo_rel))
                if os.path.exists(candidate):
                    tenant_logo_abs = candidate
    except Exception:
        tenant_logo_abs = ''
    try:
        loc_row = get_location_master_row(_resolve_location_code())
        if loc_row:
            logo_rel = str(loc_row.get('logo_path') or loc_row.get('LOGO_PATH') or '').strip()
            if logo_rel:
                candidate = os.path.abspath(os.path.join(bp.root_path, '..', 'static', logo_rel))
                if os.path.exists(candidate):
                    branch_logo_abs = candidate
    except Exception:
        branch_logo_abs = ''
    pdf_logo_abs = branch_logo_abs or tenant_logo_abs
    styles = getSampleStyleSheet()
    BLUE = colors.HexColor('#1a56a4')
    BLUE_LIGHT = colors.HexColor('#e8f0fb')
    BORDER = colors.HexColor('#b0b8c4')
    GRAY_ROW = colors.HexColor('#f7f8fa')
    TEXT = colors.HexColor('#1a1a1a')
    PAD = 5

    def _s(name, **kw):
        base = kw.pop('parent', styles['Normal'])
        kw.setdefault('textColor', TEXT)
        return ParagraphStyle(name, parent=base, **kw)
    N8 = _s('n8', fontSize=8, leading=11)
    N9 = _s('n9', fontSize=9, leading=12)
    N9R = _s('n9r', fontSize=9, leading=12, alignment=TA_RIGHT)
    N9C = _s('n9c', fontSize=9, leading=12, alignment=TA_CENTER)
    N10 = _s('n10', fontSize=10, leading=13)
    LBL = _s('lbl', fontSize=8, leading=11, textColor=colors.HexColor('#555f6b'))
    HDR = _s('hdr', fontSize=14, leading=17, alignment=TA_CENTER, textColor=BLUE, parent=styles['Normal'])
    SUB = _s('sub', fontSize=9, leading=12, alignment=TA_CENTER, textColor=colors.HexColor('#555f6b'))
    WHT = _s('wht', fontSize=9, leading=12, alignment=TA_CENTER, textColor=colors.white)
    FOOT = _s('ft', fontSize=7.5, leading=10, textColor=colors.HexColor('#888'))
    W = 10.89 * inch
    LEFT_W = W * 0.57
    RIGHT_W = W - LEFT_W
    buffer = io.BytesIO()
    doc = SimpleDocTemplate(buffer, pagesize=landscape(A4), topMargin=0.45 * inch, bottomMargin=0.35 * inch, leftMargin=0.4 * inch, rightMargin=0.4 * inch)
    elements = []
    logo_cell: Any = ''
    if pdf_logo_abs:
        try:
            logo = RLImage(pdf_logo_abs)
            max_h = 0.75 * inch
            if getattr(logo, 'drawHeight', 0) and getattr(logo, 'drawWidth', 0):
                scale = min(max_h / float(logo.drawHeight), 2.0)
                logo.drawHeight = float(logo.drawHeight) * scale
                logo.drawWidth = float(logo.drawWidth) * scale
            logo.hAlign = 'LEFT'
            logo_cell = logo
        except Exception:
            logo_cell = ''
    company_lines = [Paragraph(f'<b>{company_name}</b>', _s('cn', fontSize=11, leading=14, alignment=TA_CENTER, textColor=BLUE))]
    if company_address:
        company_lines.append(Paragraph(company_address, SUB))
    company_lines.append(Paragraph('<b>PURCHASE ORDER</b>', _s('pot', fontSize=14, leading=18, alignment=TA_CENTER, textColor=BLUE)))
    if company_phone or company_contact:
        company_lines.append(Paragraph(f'Tel: {company_phone or company_contact}', SUB))
    if company_email:
        company_lines.append(Paragraph(f'Email: {company_email}', SUB))
    po_ref_lines = [Paragraph(f'<b>PO No:</b>  {lpo_no}', _s('r9', fontSize=9, leading=13, alignment=TA_RIGHT)), Paragraph(f'<b>Date:</b>  {po_date_display}', _s('r9b', fontSize=9, leading=13, alignment=TA_RIGHT)), Paragraph(f'<b>Status:</b>  {status_text}', _s('r9c', fontSize=9, leading=13, alignment=TA_RIGHT)), Paragraph(f'<b>Prepared by:</b>  {username}', _s('r9d', fontSize=9, leading=13, alignment=TA_RIGHT))]
    logo_col_w = 1.6 * inch
    title_tbl = Table([[logo_cell, company_lines, po_ref_lines]], colWidths=[logo_col_w, W - logo_col_w - 2.5 * inch, 2.5 * inch], hAlign='LEFT')
    title_tbl.setStyle(TableStyle([('VALIGN', (0, 0), (-1, -1), 'MIDDLE'), ('ALIGN', (0, 0), (0, 0), 'LEFT'), ('ALIGN', (1, 0), (1, 0), 'CENTER'), ('ALIGN', (2, 0), (2, 0), 'RIGHT'), ('TOPPADDING', (0, 0), (-1, -1), PAD), ('BOTTOMPADDING', (0, 0), (-1, -1), PAD), ('LEFTPADDING', (0, 0), (-1, -1), PAD), ('RIGHTPADDING', (0, 0), (-1, -1), PAD)]))
    elements.append(title_tbl)
    elements.append(Spacer(1, 4))
    rule_tbl = Table([['']], colWidths=[W], rowHeights=[2], hAlign='LEFT')
    rule_tbl.setStyle(TableStyle([('BACKGROUND', (0, 0), (-1, -1), BLUE)]))
    elements.append(rule_tbl)
    elements.append(Spacer(1, 6))

    def _info_row(label, value):
        return [Paragraph(label, LBL), Paragraph(str(value or ''), N9)]
    _lpo_attach_warehouse_display(header)
    warehouse_display = str(header.get('warehouse_display') or '').strip()
    if not warehouse_display and header.get('warehouse_id') not in (None, ''):
        warehouse_display = str(header.get('warehouse_id')).strip()
    sup_rows = [_info_row('Supplier Code', supplier_code), _info_row('Supplier Name', supplier_name), _info_row('Address', supplier_address), _info_row('GSTIN / Tax No', supplier_gstin), _info_row('Contact', supplier_phone or supplier_contact), _info_row('Email', supplier_email)]
    po_rows = [_info_row('Payment Terms', '100% against invoice'), _info_row('Delivery Period', po_expiry + ' from PO date'), _info_row('Location', str(header.get('locationname') or session.get('location_name') or ''))]
    if _po_warehouse_enabled() or warehouse_display:
        po_rows.append(_info_row('Warehouse', warehouse_display or '—'))
    po_rows.extend([_info_row('Currency', ''), _info_row('Remarks', remarks)])
    LBL_W = 1.1 * inch
    VAL_W = LEFT_W - LBL_W - 0.1 * inch
    LBL_W2 = 1.1 * inch
    VAL_W2 = RIGHT_W - LBL_W2 - 0.1 * inch
    sup_tbl = Table(sup_rows, colWidths=[LBL_W, VAL_W])
    sup_tbl.setStyle(TableStyle([('FONTSIZE', (0, 0), (-1, -1), 8.5), ('VALIGN', (0, 0), (-1, -1), 'TOP'), ('LINEBELOW', (0, 0), (-1, -2), 0.3, colors.HexColor('#dde3ea')), ('TOPPADDING', (0, 0), (-1, -1), PAD), ('BOTTOMPADDING', (0, 0), (-1, -1), PAD), ('LEFTPADDING', (0, 0), (-1, -1), PAD), ('RIGHTPADDING', (0, 0), (-1, -1), PAD)]))
    po_meta_tbl = Table(po_rows, colWidths=[LBL_W2, VAL_W2])
    po_meta_tbl.setStyle(TableStyle([('FONTSIZE', (0, 0), (-1, -1), 8.5), ('VALIGN', (0, 0), (-1, -1), 'TOP'), ('LINEBELOW', (0, 0), (-1, -2), 0.3, colors.HexColor('#dde3ea')), ('TOPPADDING', (0, 0), (-1, -1), PAD), ('BOTTOMPADDING', (0, 0), (-1, -1), PAD), ('LEFTPADDING', (0, 0), (-1, -1), PAD), ('RIGHTPADDING', (0, 0), (-1, -1), PAD)]))
    info_outer = Table([[sup_tbl, po_meta_tbl]], colWidths=[LEFT_W, RIGHT_W], hAlign='LEFT')
    info_outer.setStyle(TableStyle([('BOX', (0, 0), (-1, -1), 0.5, BORDER), ('LINEBEFORE', (1, 0), (1, 0), 0.5, BORDER), ('BACKGROUND', (0, 0), (-1, -1), BLUE_LIGHT), ('VALIGN', (0, 0), (-1, -1), 'TOP'), ('LEFTPADDING', (0, 0), (-1, -1), PAD), ('RIGHTPADDING', (0, 0), (-1, -1), PAD), ('TOPPADDING', (0, 0), (-1, -1), PAD), ('BOTTOMPADDING', (0, 0), (-1, -1), PAD)]))
    elements.append(info_outer)
    elements.append(Spacer(1, 8))
    tbl_header = table_rows[0]
    tbl_body = table_rows[1:]

    def _hcell(txt):
        return Paragraph(f'<b>{txt}</b>', WHT)

    def _dcell(txt, align='LEFT'):
        st = N9R if align == 'RIGHT' else N9C if align == 'CENTER' else N9
        return Paragraph(str(txt), st)
    pt_rows = [[_hcell(c) for c in tbl_header]]
    for row in tbl_body:
        pt_rows.append([_dcell(row[0], 'CENTER'), _dcell(row[1], 'CENTER'), _dcell(row[2]), _dcell(row[3], 'CENTER'), _dcell(row[4], 'RIGHT'), _dcell(row[5], 'CENTER'), _dcell(row[6], 'RIGHT'), _dcell(row[7], 'CENTER'), _dcell(row[8], 'RIGHT')])
    pt = Table(pt_rows, repeatRows=1, colWidths=[0.45 * inch, 1.1 * inch, 3.5 * inch, 1.3 * inch, 0.8 * inch, 0.65 * inch, 1.0 * inch, 0.65 * inch, 1.44 * inch], hAlign='LEFT')
    pt.setStyle(TableStyle([('BACKGROUND', (0, 0), (-1, 0), BLUE), ('TEXTCOLOR', (0, 0), (-1, 0), colors.white), ('FONTSIZE', (0, 0), (-1, -1), 8.5), ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'), ('GRID', (0, 0), (-1, -1), 0.4, BORDER), ('ROWBACKGROUNDS', (0, 1), (-1, -1), [colors.white, GRAY_ROW]), ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'), ('TOPPADDING', (0, 0), (-1, -1), PAD), ('BOTTOMPADDING', (0, 0), (-1, -1), PAD), ('LEFTPADDING', (0, 0), (-1, -1), PAD), ('RIGHTPADDING', (0, 0), (-1, -1), PAD)]))
    elements.append(pt)
    elements.append(Spacer(1, 8))
    SL = _s('sl', fontSize=9, leading=12, alignment=TA_RIGHT, textColor=colors.HexColor('#333'))
    SR = _s('sr', fontSize=9, leading=12, alignment=TA_RIGHT)
    sum_rows = [[Paragraph('Sub Total', SL), Paragraph(f'{subtotal:.2f}', SR)], [Paragraph('Discount  (–)', SL), Paragraph(f'{discount:.2f}', SR)]]
    if other_charge:
        sum_rows.append([Paragraph('Other Charges  (+)', SL), Paragraph(f'{other_charge:.2f}', SR)])
    sum_rows.append([Paragraph('<b>Grand Total</b>', SL), Paragraph(f'<b>{lpo_total:.2f}</b>', SR)])
    total_row_idx = len(sum_rows) - 1
    sum_tbl = Table(sum_rows, colWidths=[W - 1.6 * inch, 1.6 * inch], hAlign='LEFT')
    sum_style = [('BOX', (0, 0), (-1, -1), 0.5, BORDER), ('LINEBELOW', (0, 0), (-1, -2), 0.3, colors.HexColor('#dde3ea')), ('BACKGROUND', (0, total_row_idx), (-1, total_row_idx), BLUE_LIGHT), ('FONTSIZE', (0, 0), (-1, -1), 9), ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'), ('TOPPADDING', (0, 0), (-1, -1), PAD), ('BOTTOMPADDING', (0, 0), (-1, -1), PAD), ('LEFTPADDING', (0, 0), (-1, -1), PAD), ('RIGHTPADDING', (0, 0), (-1, -1), PAD)]
    sum_tbl.setStyle(TableStyle(sum_style))
    elements.append(sum_tbl)
    elements.append(Spacer(1, 10))
    tc_lines = ['<b>Terms &amp; Conditions:</b>', '1. We reserve the right to cancel this PO before shipment.', '2. Invoice must quote the PO number and date.', '3. Adherence to agreed product specifications is mandatory.', '4. Packing and shipping charges are borne by supplier unless agreed otherwise.', '5. Delivery must be within the agreed timeline.']
    if remarks:
        tc_lines.append(f'Remarks: {remarks}')
    terms_para = Paragraph('<br/>'.join(tc_lines), _s('tc', fontSize=8, leading=11.5))
    sign_box = Table([[''], [Paragraph('Authorised Signatory', _s('sf', fontSize=8.5, leading=11, alignment=TA_CENTER, textColor=colors.HexColor('#555')))]], colWidths=[2.5 * inch], rowHeights=[0.65 * inch, 0.22 * inch])
    sign_box.setStyle(TableStyle([('BOX', (0, 0), (-1, -1), 0.5, BORDER), ('LINEABOVE', (0, 1), (0, 1), 0.5, BORDER), ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'), ('ALIGN', (0, 0), (-1, -1), 'CENTER')]))
    btm_tbl = Table([[terms_para, sign_box]], colWidths=[W - 2.7 * inch, 2.7 * inch], hAlign='LEFT')
    btm_tbl.setStyle(TableStyle([('BOX', (0, 0), (-1, -1), 0.5, BORDER), ('LINEBEFORE', (1, 0), (1, 0), 0.5, BORDER), ('BACKGROUND', (0, 0), (0, 0), BLUE_LIGHT), ('VALIGN', (0, 0), (-1, -1), 'TOP'), ('TOPPADDING', (0, 0), (-1, -1), PAD), ('BOTTOMPADDING', (0, 0), (-1, -1), PAD), ('LEFTPADDING', (0, 0), (-1, -1), PAD), ('RIGHTPADDING', (0, 0), (-1, -1), PAD), ('ALIGN', (1, 0), (1, 0), 'CENTER')]))
    elements.append(btm_tbl)
    elements.append(Spacer(1, 6))
    elements.append(Paragraph('This is a computer-generated document. No signature is required.', FOOT))
    doc.build(elements)
    return (buffer.getvalue(), None)

def _grn_pdf_bin_label_for_line(line: Dict[str, Any]) -> str:
    """Human-readable bin/staging label for GRN PDF (matches Item Journal naming)."""
    if not line:
        return ''
    sid = line.get('storage_id')
    if sid is None or str(sid).strip() == '':
        return ''
    try:
        lk = resolve_warehouse_loc_key_for_location_code(int(_resolve_location_code()))
        if not lk:
            return str(sid).strip()
        ik = int(sid)
        for row_type in ('BIN', 'STAGING'):
            for wr in get_warehouse_storage_rows(lk, row_type) or []:
                if wr.get('storage_id') is None:
                    continue
                try:
                    if int(wr['storage_id']) != ik:
                        continue
                except (TypeError, ValueError):
                    continue
                code = str(wr.get('code') or '').strip()
                nm = str(wr.get('name') or '').strip()
                return code + (f' — {nm}' if nm else '')
    except Exception:
        pass
    return str(sid).strip()

def _build_grn_pdf_bytes(receipt_no: int) -> tuple:
    if not REPORTLAB_AVAILABLE:
        return (None, 'PDF library (reportlab) is not available.')
    header = _get_receipt_header_for_posting(receipt_no)
    if not header:
        return (None, 'GRN not found.')
    lines = _get_receipt_details(receipt_no)
    supplier_code = str(header.get('suppliercode') or '').strip()
    supplier = _get_supplier_profile(supplier_code)
    company = _get_company_profile()
    supplier_name = str(supplier.get('name') or '')
    supplier_address = str(supplier.get('address') or '')
    supplier_gstin = str(supplier.get('gstin') or '')
    supplier_phone = str(supplier.get('phone') or '')
    supplier_email = str(supplier.get('email') or '')
    supplier_contact = str(supplier.get('contact') or '')
    company_name = str(company.get('name') or session.get('location_name') or '')
    company_address = str(company.get('address') or '')
    company_phone = str(company.get('phone') or '')
    company_email = str(company.get('email') or '')
    username = str(session.get('user') or '')
    created_by = str(header.get('createdby') or '').strip()
    status_text = _get_grn_approval_status(receipt_no)
    receipt_date = str(header.get('receiptdate') or '')
    invoice_no = str(header.get('invoiceno') or '')
    invoice_date = str(header.get('invoicedate') or '')
    discount = float(header.get('discount') or 0)
    remarks = str(header.get('remarks') or '')
    lpo_no = str(header.get('lpono') or '')
    receipt_dt = None
    try:
        receipt_dt = datetime.strptime(receipt_date[:10], '%Y-%m-%d')
    except Exception:
        receipt_dt = None
    receipt_date_display = receipt_dt.strftime('%d-%m-%Y') if receipt_dt else receipt_date
    invoice_date_display = invoice_date
    try:
        if invoice_date:
            invoice_date_display = datetime.strptime(invoice_date[:10], '%Y-%m-%d').strftime('%d-%m-%Y')
    except Exception:
        invoice_date_display = invoice_date
    subtotal = 0.0
    line_discount_total = 0.0
    gross_before_line_disc = 0.0
    table_rows = [['S.No', 'Item Code', 'Item Name', 'UOM', 'Qty', 'T.qty', 'Rate', 'Disc.', 'Inv. Loc', 'Amount']]
    for idx, ln in enumerate(lines or [], 1):
        code = str(ln.get('itemcode') or '')
        qty_line = float(ln.get('quantity') or 0)
        if qty_line <= 1e-9:
            qty_line = float(ln.get('receivedqty') or 0)
        base_v = float(ln.get('baseqty') or 0)
        rate = float(ln.get('rate') or 0)
        line_disc = float(ln.get('discount') or 0)
        is_foc = ln.get('foc') in (True, 1, '1', 'Y', 'y')
        if is_foc:
            amt = 0.0
            disc_display = 'FOC'
        else:
            amt = float(ln.get('amount') or max(0.0, qty_line * rate - line_disc))
            gross_before_line_disc += qty_line * rate
            line_discount_total += line_disc
            disc_display = f'{line_disc:.2f}'
        subtotal += amt
        inv_loc = str(ln.get('location') or '')
        amt_display = 'FOC' if is_foc else f'{amt:.2f}'
        table_rows.append([str(idx), code, str(ln.get('itemname') or ''), str(ln.get('uom') or 'NOS').upper(), f'{qty_line:.2f}', f'{base_v:.3f}', f'{rate:.3f}', disc_display, inv_loc, amt_display])
    inv_amt_hdr = float(header.get('invoiceamount') or 0)
    if inv_amt_hdr > 0.001 and abs(inv_amt_hdr - subtotal) <= 0.02:
        net_total = subtotal
    elif discount > 0.001 and subtotal > discount + 0.001:
        net_total = max(0.0, subtotal - discount)
    else:
        net_total = subtotal
    tenant_logo_abs = ''
    try:
        tid = str(session.get('tenant_id') or '').strip()
        if tid:
            t = get_tenant_by_id(tid) or {}
            logo_rel = str(t.get('logo_path') or '').strip()
            if logo_rel:
                candidate = os.path.abspath(os.path.join(bp.root_path, '..', 'static', logo_rel))
                if os.path.exists(candidate):
                    tenant_logo_abs = candidate
    except Exception:
        tenant_logo_abs = ''
    styles = getSampleStyleSheet()
    BLUE = colors.HexColor('#1a56a4')
    BLUE_LIGHT = colors.HexColor('#e8f0fb')
    BORDER = colors.HexColor('#b0b8c4')
    GRAY_ROW = colors.HexColor('#f7f8fa')
    TEXT = colors.HexColor('#1a1a1a')
    PAD = 5

    def _s(name, **kw):
        base = kw.pop('parent', styles['Normal'])
        kw.setdefault('textColor', TEXT)
        return ParagraphStyle(name, parent=base, **kw)
    N9 = _s('g9', fontSize=9, leading=12)
    N9R = _s('g9r', fontSize=9, leading=12, alignment=TA_RIGHT)
    N9C = _s('g9c', fontSize=9, leading=12, alignment=TA_CENTER)
    # Body/totals: avoid vertical wrap on decimals (e.g. "5." + "00" on two lines)
    N9R_NB = _s('g9r_nb', fontSize=9, leading=12, alignment=TA_RIGHT, splitLongWords=False)
    N9C_NB = _s('g9c_nb', fontSize=9, leading=12, alignment=TA_CENTER, splitLongWords=False)
    LBL = _s('glbl', fontSize=8, leading=11, textColor=colors.HexColor('#555f6b'))
    SUB = _s('gsub', fontSize=9, leading=12, alignment=TA_CENTER, textColor=colors.HexColor('#555f6b'))
    WHT = _s('gwht', fontSize=9, leading=12, alignment=TA_CENTER, textColor=colors.white)
    # Narrow GRN grid header: ReportLab splits "T." / "qty" unless splitLongWords=False; smaller font stays one line
    WHT_TQTY = _s('gwht_tqty', fontSize=8, leading=10, alignment=TA_CENTER, textColor=colors.white, fontName='Helvetica-Bold', splitLongWords=False)
    FOOT = _s('gft', fontSize=7.5, leading=10, textColor=colors.HexColor('#888'))
    W = 7.47 * inch
    LEFT_W = W * 0.57
    RIGHT_W = W - LEFT_W
    buffer = io.BytesIO()
    doc = SimpleDocTemplate(buffer, pagesize=A4, topMargin=0.45 * inch, bottomMargin=0.35 * inch, leftMargin=0.4 * inch, rightMargin=0.4 * inch)
    elements = []
    logo_cell: Any = ''
    if tenant_logo_abs:
        try:
            logo = RLImage(tenant_logo_abs)
            max_h = 0.75 * inch
            if getattr(logo, 'drawHeight', 0) and getattr(logo, 'drawWidth', 0):
                scale = min(max_h / float(logo.drawHeight), 2.0)
                logo.drawHeight = float(logo.drawHeight) * scale
                logo.drawWidth = float(logo.drawWidth) * scale
            logo.hAlign = 'CENTER'
            logo_cell = logo
        except Exception:
            logo_cell = ''
    company_lines = [Paragraph(f'<b>{company_name}</b>', _s('gcn', fontSize=14, leading=18, alignment=TA_CENTER, textColor=BLUE))]
    if company_address:
        company_lines.append(Paragraph(company_address, SUB))
    if company_phone or supplier_contact:
        company_lines.append(Paragraph(f'Tel: {company_phone or supplier_contact}', SUB))
    if company_email:
        company_lines.append(Paragraph(f'Email: {company_email}', SUB))
    hdr_rows = []
    if logo_cell:
        lg = logo_cell
        lg.hAlign = 'CENTER'
        hdr_rows.append([lg])
    hdr_rows.extend([[p] for p in company_lines])
    hdr_rows.append([Paragraph('<b>GOODS RECEIPT NOTE</b>', _s('gt1', fontSize=12, leading=15, alignment=TA_CENTER, textColor=BLUE))])
    rule_tbl = Table([['']], colWidths=[W], rowHeights=[2])
    rule_tbl.setStyle(TableStyle([('BACKGROUND', (0, 0), (-1, -1), BLUE)]))
    hdr_rows.append([rule_tbl])
    title_tbl = Table(hdr_rows, colWidths=[W], hAlign='CENTER')
    title_tbl.setStyle(TableStyle([('VALIGN', (0, 0), (-1, -1), 'MIDDLE'), ('ALIGN', (0, 0), (-1, -1), 'CENTER'), ('TOPPADDING', (0, 0), (-1, -1), PAD), ('BOTTOMPADDING', (0, 0), (-1, -1), PAD), ('LEFTPADDING', (0, 0), (-1, -1), PAD), ('RIGHTPADDING', (0, 0), (-1, -1), PAD)]))
    elements.append(title_tbl)
    elements.append(Spacer(1, 6))

    def _info_row(label, value):
        return [Paragraph(label, LBL), Paragraph(str(value or ''), N9)]
    sup_rows = [_info_row('Supplier Code', supplier_code), _info_row('Supplier Name', supplier_name), _info_row('LPO No', lpo_no), _info_row('Invoice Date', invoice_date_display), _info_row('Invoice No', invoice_no)]
    grn_rows = [_info_row('GRN No', receipt_no), _info_row('Date', receipt_date_display), _info_row('Created By', created_by), _info_row('Prepared By', username), _info_row('Remarks', remarks)]
    LBL_W = 1.1 * inch
    VAL_W = LEFT_W - LBL_W - 0.1 * inch
    LBL_W2 = 1.1 * inch
    VAL_W2 = RIGHT_W - LBL_W2 - 0.1 * inch
    sup_tbl = Table(sup_rows, colWidths=[LBL_W, VAL_W])
    sup_tbl.setStyle(TableStyle([('FONTSIZE', (0, 0), (-1, -1), 8.5), ('VALIGN', (0, 0), (-1, -1), 'TOP'), ('LINEBELOW', (0, 0), (-1, -2), 0.3, colors.HexColor('#dde3ea')), ('TOPPADDING', (0, 0), (-1, -1), PAD), ('BOTTOMPADDING', (0, 0), (-1, -1), PAD), ('LEFTPADDING', (0, 0), (-1, -1), PAD), ('RIGHTPADDING', (0, 0), (-1, -1), PAD)]))
    grn_meta_tbl = Table(grn_rows, colWidths=[LBL_W2, VAL_W2])
    grn_meta_tbl.setStyle(TableStyle([('FONTSIZE', (0, 0), (-1, -1), 8.5), ('VALIGN', (0, 0), (-1, -1), 'TOP'), ('LINEBELOW', (0, 0), (-1, -2), 0.3, colors.HexColor('#dde3ea')), ('TOPPADDING', (0, 0), (-1, -1), PAD), ('BOTTOMPADDING', (0, 0), (-1, -1), PAD), ('LEFTPADDING', (0, 0), (-1, -1), PAD), ('RIGHTPADDING', (0, 0), (-1, -1), PAD)]))
    info_outer = Table([[sup_tbl, grn_meta_tbl]], colWidths=[LEFT_W, RIGHT_W], hAlign='LEFT')
    info_outer.setStyle(TableStyle([('BOX', (0, 0), (-1, -1), 0.5, BORDER), ('LINEBEFORE', (1, 0), (1, 0), 0.5, BORDER), ('BACKGROUND', (0, 0), (-1, -1), BLUE_LIGHT), ('VALIGN', (0, 0), (-1, -1), 'TOP'), ('LEFTPADDING', (0, 0), (-1, -1), PAD), ('RIGHTPADDING', (0, 0), (-1, -1), PAD), ('TOPPADDING', (0, 0), (-1, -1), PAD), ('BOTTOMPADDING', (0, 0), (-1, -1), PAD)]))
    elements.append(info_outer)
    elements.append(Spacer(1, 8))

    def _hcell(txt):
        return Paragraph(f'<b>{txt}</b>', WHT)

    def _dcell(txt, align='LEFT', nowrap=False):
        if nowrap:
            if align == 'RIGHT':
                st = N9R_NB
            elif align == 'CENTER':
                st = N9C_NB
            else:
                st = _s('g9nw', fontSize=9, leading=12, splitLongWords=False)
        else:
            st = N9R if align == 'RIGHT' else N9C if align == 'CENTER' else N9
        return Paragraph(str(txt), st)
    header_row = table_rows[0]
    body_rows = table_rows[1:]
    hdr_cells = [_hcell(c) for c in header_row]
    tqty_idx = header_row.index('T.qty')
    hdr_cells[tqty_idx] = Paragraph('T.qty', WHT_TQTY)
    pt_rows = [hdr_cells]
    lines_list = lines or []
    for i, row in enumerate(body_rows):
        ln = lines_list[i] if i < len(lines_list) else {}
        bin_lbl = _grn_pdf_bin_label_for_line(ln)
        name_plain = str(row[2] or '')
        barcode_plain = str(ln.get('barcode') or ln.get('manufacturerid') or '').strip()
        name_bits = [escape(name_plain)] if name_plain else []
        if barcode_plain:
            name_bits.append(f'<font size="7.5" color="#333333">{escape(barcode_plain)}</font>')
        if bin_lbl:
            name_bits.append(f'<font size="7" color="#64748b">Bin: {escape(bin_lbl)}</font>')
        if name_bits:
            item_cell = Paragraph('<br/>'.join(name_bits), N9)
        else:
            item_cell = _dcell(row[2])
        pt_rows.append([
            _dcell(row[0], 'CENTER', True),
            _dcell(row[1], 'CENTER', True),
            item_cell,
            _dcell(row[3], 'CENTER', True),
            _dcell(row[4], 'RIGHT', True),
            _dcell(row[5], 'RIGHT', True),
            _dcell(row[6], 'RIGHT', True),
            _dcell(row[7], 'RIGHT', True),
            _dcell(row[8], 'CENTER', True),
            _dcell(row[9], 'RIGHT', True),
        ])
    # Match item-grid width to header/info box (W). Extra space goes to Item Name + Amount.
    item_col_w = [
        0.36 * inch,  # S.No
        0.72 * inch,  # Item Code
        2.20 * inch,  # Item Name
        0.48 * inch,  # UOM
        0.62 * inch,  # Qty
        0.54 * inch,  # T.qty
        0.62 * inch,  # Rate
        0.54 * inch,  # Disc.
        0.66 * inch,  # Inv. Loc
        0.73 * inch,  # Amount
    ]
    # Guard: keep exact page content width even if column list drifts.
    _item_w_sum = sum(item_col_w)
    if abs(_item_w_sum - W) > 0.01:
        item_col_w[-1] = max(0.55 * inch, item_col_w[-1] + (W - _item_w_sum))
    pt = Table(pt_rows, repeatRows=1, colWidths=item_col_w, hAlign='LEFT')
    pt.setStyle(TableStyle([('BACKGROUND', (0, 0), (-1, 0), BLUE), ('TEXTCOLOR', (0, 0), (-1, 0), colors.white), ('FONTSIZE', (0, 0), (-1, -1), 8.5), ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'), ('GRID', (0, 0), (-1, -1), 0.4, BORDER), ('ROWBACKGROUNDS', (0, 1), (-1, -1), [colors.white, GRAY_ROW]), ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'), ('TOPPADDING', (0, 0), (-1, -1), PAD), ('BOTTOMPADDING', (0, 0), (-1, -1), PAD), ('LEFTPADDING', (0, 0), (-1, -1), PAD), ('RIGHTPADDING', (0, 0), (-1, -1), PAD)]))
    elements.append(pt)
    elements.append(Spacer(1, 8))
    SL = _s('gsl', fontSize=9, leading=12, alignment=TA_RIGHT, textColor=colors.HexColor('#333'))
    SR_NB = _s('gsr_nb', fontSize=9, leading=12, alignment=TA_RIGHT, splitLongWords=False)
    SR_NB_BOLD = _s('gsr_nb_b', fontSize=9, leading=12, alignment=TA_RIGHT, splitLongWords=False, fontName='Helvetica-Bold')
    sum_rows = [[Paragraph('Receipt Line Total', SL), Paragraph(f'{subtotal:.2f}', SR_NB)]]
    if line_discount_total > 0.001:
        sum_rows.insert(0, [Paragraph('Gross Total', SL), Paragraph(f'{gross_before_line_disc:.2f}', SR_NB)])
        sum_rows.insert(1, [Paragraph('Line Discount  (-)', SL), Paragraph(f'{line_discount_total:.2f}', SR_NB)])
    if discount > 0.001:
        sum_rows.append([Paragraph('Trade discount (header)', SL), Paragraph(f'{discount:.2f}', SR_NB)])
    sum_rows.append([Paragraph('<b>Net Total</b>', SL), Paragraph(f'<b>{net_total:.2f}</b>', SR_NB_BOLD)])
    total_row_idx = len(sum_rows) - 1
    sum_tbl = Table(sum_rows, colWidths=[W - 1.6 * inch, 1.6 * inch], hAlign='LEFT')
    sum_tbl.setStyle(TableStyle([('BOX', (0, 0), (-1, -1), 0.5, BORDER), ('LINEBELOW', (0, 0), (-1, -2), 0.3, colors.HexColor('#dde3ea')), ('BACKGROUND', (0, total_row_idx), (-1, total_row_idx), BLUE_LIGHT), ('FONTSIZE', (0, 0), (-1, -1), 9), ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'), ('TOPPADDING', (0, 0), (-1, -1), PAD), ('BOTTOMPADDING', (0, 0), (-1, -1), PAD), ('LEFTPADDING', (0, 0), (-1, -1), PAD), ('RIGHTPADDING', (0, 0), (-1, -1), PAD)]))
    elements.append(sum_tbl)
    elements.append(Spacer(1, 10))
    doc.build(elements)
    return (buffer.getvalue(), None)

def _build_purchase_return_doc_pdf_bytes(header: Dict[str, Any], lines: List[Dict[str, Any]], *, doc_title: str, doc_no_label: str) -> tuple:
    if not REPORTLAB_AVAILABLE:
        return (None, 'PDF library (reportlab) is not available.')
    goods_return_no = header.get('goodsreturnno')
    supplier_code = str(header.get('suppliercode') or '').strip()
    supplier = _get_supplier_profile(supplier_code)
    company = _get_company_profile()
    supplier_name = str(supplier.get('name') or '')
    company_name = str(company.get('name') or session.get('location_name') or '')
    company_address = str(company.get('address') or '')
    company_phone = str(company.get('phone') or '')
    company_email = str(company.get('email') or '')
    username = str(session.get('user') or '')
    created_by = str(header.get('createdby') or '').strip()
    return_date = str(header.get('returndate') or '')
    return_date_display = return_date
    try:
        if return_date:
            return_date_display = datetime.strptime(return_date[:10], '%Y-%m-%d').strftime('%d-%m-%Y')
    except Exception:
        return_date_display = return_date
    receipt_no = str(header.get('receiptno') or '')
    remarks = str(header.get('sectioninc') or header.get('remarks') or '')
    is_debit_note_request = str(header.get('returntype') or '').strip().upper() == 'D'
    resolved_title = doc_title or ('PURCHASE DEBIT NOTE REQUEST' if is_debit_note_request else 'PURCHASE RETURN ORDER')
    resolved_no_label = doc_no_label or ('Request No' if is_debit_note_request else 'Return No')
    _enrich_pr_header_discount(header, lines or [])
    subtotal_gross = 0.0
    line_discount_total = 0.0
    net_line_total = 0.0
    show_discount = not is_debit_note_request
    if show_discount:
        table_rows = [['S.No', 'Item Code', 'Item Name', 'UOM', 'Qty', 'Rate', 'Discount', 'Amount']]
    else:
        table_rows = [['S.No', 'Item Code', 'Item Name', 'UOM', 'Qty', 'Rate', 'Amount']]
    for idx, ln in enumerate(lines or [], 1):
        qty = float(ln.get('quantity') or 0)
        rate = float(ln.get('rate') or 0)
        gross = qty * rate
        line_disc = float(ln.get('discount') or 0) if show_discount else 0.0
        net_amt = max(0.0, gross - line_disc)
        subtotal_gross += gross
        line_discount_total += line_disc
        net_line_total += net_amt
        if show_discount:
            table_rows.append([
                str(idx), str(ln.get('itemcode') or ''), str(ln.get('itemname') or ''),
                str(ln.get('uom') or 'NOS').upper(), f'{qty:.2f}', f'{rate:.3f}',
                f'{line_disc:.2f}', f'{net_amt:.2f}',
            ])
        else:
            table_rows.append([
                str(idx), str(ln.get('itemcode') or ''), str(ln.get('itemname') or ''),
                str(ln.get('uom') or 'NOS').upper(), f'{qty:.2f}', f'{rate:.3f}', f'{net_amt:.2f}',
            ])
    try:
        header_discount = float(header.get('discount') or 0)
    except (TypeError, ValueError):
        header_discount = 0.0
    discount_total = header_discount if header_discount > 0.001 else line_discount_total
    try:
        grand_total = float(header.get('returnamount') or 0)
    except (TypeError, ValueError):
        grand_total = 0.0
    if grand_total <= 0.001:
        grand_total = max(0.0, subtotal_gross - discount_total)
    if net_line_total > 0.001 and abs(grand_total - net_line_total) <= 0.02:
        grand_total = net_line_total
    styles = getSampleStyleSheet()
    BLUE = colors.HexColor('#1a56a4')
    BLUE_LIGHT = colors.HexColor('#e8f0fb')
    BORDER = colors.HexColor('#b0b8c4')
    GRAY_ROW = colors.HexColor('#f7f8fa')
    TEXT = colors.HexColor('#1a1a1a')
    PAD = 5

    def _s(name, **kw):
        base = kw.pop('parent', styles['Normal'])
        kw.setdefault('textColor', TEXT)
        return ParagraphStyle(name, parent=base, **kw)
    N9 = _s('pr9', fontSize=9, leading=12)
    N9R = _s('pr9r', fontSize=9, leading=12, alignment=TA_RIGHT)
    LBL = _s('prlbl', fontSize=8, leading=11, textColor=colors.HexColor('#555f6b'))
    SUB = _s('prsub', fontSize=9, leading=12, alignment=TA_CENTER, textColor=colors.HexColor('#555f6b'))
    WHT = _s('prwht', fontSize=9, leading=12, alignment=TA_CENTER, textColor=colors.white)
    W = 7.47 * inch
    LEFT_W = W * 0.57
    RIGHT_W = W - LEFT_W
    buffer = io.BytesIO()
    doc = SimpleDocTemplate(buffer, pagesize=A4, topMargin=0.45 * inch, bottomMargin=0.35 * inch, leftMargin=0.4 * inch, rightMargin=0.4 * inch)
    elements = []
    company_lines = [Paragraph(f'<b>{company_name}</b>', _s('prcn', fontSize=11, leading=14, alignment=TA_CENTER, textColor=BLUE))]
    if company_address:
        company_lines.append(Paragraph(company_address, SUB))
    if company_phone:
        company_lines.append(Paragraph(f'Tel: {company_phone}', SUB))
    if company_email:
        company_lines.append(Paragraph(f'Email: {company_email}', SUB))
    title_tbl = Table([[company_lines]], colWidths=[W], hAlign='LEFT')
    title_tbl.setStyle(TableStyle([('VALIGN', (0, 0), (-1, -1), 'MIDDLE'), ('ALIGN', (0, 0), (0, 0), 'CENTER'), ('TOPPADDING', (0, 0), (-1, -1), PAD), ('BOTTOMPADDING', (0, 0), (-1, -1), PAD), ('LEFTPADDING', (0, 0), (-1, -1), PAD), ('RIGHTPADDING', (0, 0), (-1, -1), PAD)]))
    elements.append(title_tbl)
    elements.append(Spacer(1, 2))
    elements.append(Paragraph(f'<b>{resolved_title}</b>', _s('prt1', fontSize=12, leading=15, alignment=TA_CENTER, textColor=BLUE)))
    elements.append(Spacer(1, 4))
    rule_tbl = Table([['']], colWidths=[W], rowHeights=[2], hAlign='LEFT')
    rule_tbl.setStyle(TableStyle([('BACKGROUND', (0, 0), (-1, -1), BLUE)]))
    elements.append(rule_tbl)
    elements.append(Spacer(1, 6))

    def _info_row(label, value):
        return [Paragraph(label, LBL), Paragraph(str(value or ''), N9)]
    left_rows = [_info_row('Supplier Code', supplier_code), _info_row('Supplier Name', supplier_name), _info_row('Reference Invoice No', receipt_no), _info_row('Remarks', remarks)]
    right_rows = [_info_row(resolved_no_label, goods_return_no), _info_row('Date', return_date_display), _info_row('Created By', created_by), _info_row('Prepared By', username)]
    while len(right_rows) < len(left_rows):
        right_rows.append(_info_row('', ''))
    LBL_W = 1.35 * inch
    VAL_W = LEFT_W - LBL_W - 0.1 * inch
    LBL_W2 = 1.1 * inch
    VAL_W2 = RIGHT_W - LBL_W2 - 0.1 * inch
    left_tbl = Table(left_rows, colWidths=[LBL_W, VAL_W])
    right_tbl = Table(right_rows, colWidths=[LBL_W2, VAL_W2])
    for t in (left_tbl, right_tbl):
        t.setStyle(TableStyle([('FONTSIZE', (0, 0), (-1, -1), 8.5), ('VALIGN', (0, 0), (-1, -1), 'TOP'), ('LINEBELOW', (0, 0), (-1, -2), 0.3, colors.HexColor('#dde3ea')), ('TOPPADDING', (0, 0), (-1, -1), PAD), ('BOTTOMPADDING', (0, 0), (-1, -1), PAD), ('LEFTPADDING', (0, 0), (-1, -1), PAD), ('RIGHTPADDING', (0, 0), (-1, -1), PAD)]))
    info_outer = Table([[left_tbl, right_tbl]], colWidths=[LEFT_W, RIGHT_W], hAlign='LEFT')
    info_outer.setStyle(TableStyle([('BOX', (0, 0), (-1, -1), 0.5, BORDER), ('LINEBEFORE', (1, 0), (1, 0), 0.5, BORDER), ('BACKGROUND', (0, 0), (-1, -1), BLUE_LIGHT), ('VALIGN', (0, 0), (-1, -1), 'TOP'), ('LEFTPADDING', (0, 0), (-1, -1), PAD), ('RIGHTPADDING', (0, 0), (-1, -1), PAD), ('TOPPADDING', (0, 0), (-1, -1), PAD), ('BOTTOMPADDING', (0, 0), (-1, -1), PAD)]))
    elements.append(info_outer)
    elements.append(Spacer(1, 8))

    def _hcell(txt):
        return Paragraph(f'<b>{txt}</b>', WHT)

    def _dcell(txt, align='LEFT'):
        st = N9R if align == 'RIGHT' else N9
        return Paragraph(str(txt), st)
    pt_rows = [[_hcell(c) for c in table_rows[0]]]
    for row in table_rows[1:]:
        if show_discount:
            pt_rows.append([
                _dcell(row[0], 'RIGHT'), _dcell(row[1]), _dcell(row[2]), _dcell(row[3]),
                _dcell(row[4], 'RIGHT'), _dcell(row[5], 'RIGHT'), _dcell(row[6], 'RIGHT'), _dcell(row[7], 'RIGHT'),
            ])
        else:
            pt_rows.append([
                _dcell(row[0], 'RIGHT'), _dcell(row[1]), _dcell(row[2]), _dcell(row[3]),
                _dcell(row[4], 'RIGHT'), _dcell(row[5], 'RIGHT'), _dcell(row[6], 'RIGHT'),
            ])
    if show_discount:
        col_widths = [0.40 * inch, 0.85 * inch, 2.15 * inch, 0.58 * inch, 0.68 * inch, 0.72 * inch, 0.58 * inch, 1.51 * inch]
    else:
        col_widths = [0.42 * inch, 0.9 * inch, 2.5 * inch, 0.62 * inch, 0.72 * inch, 0.82 * inch, 1.49 * inch]
    pt = Table(pt_rows, repeatRows=1, colWidths=col_widths, hAlign='LEFT')
    pt.setStyle(TableStyle([('BACKGROUND', (0, 0), (-1, 0), BLUE), ('TEXTCOLOR', (0, 0), (-1, 0), colors.white), ('FONTSIZE', (0, 0), (-1, -1), 8.5), ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'), ('GRID', (0, 0), (-1, -1), 0.4, BORDER), ('ROWBACKGROUNDS', (0, 1), (-1, -1), [colors.white, GRAY_ROW]), ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'), ('TOPPADDING', (0, 0), (-1, -1), PAD), ('BOTTOMPADDING', (0, 0), (-1, -1), PAD), ('LEFTPADDING', (0, 0), (-1, -1), PAD), ('RIGHTPADDING', (0, 0), (-1, -1), PAD)]))
    elements.append(pt)
    elements.append(Spacer(1, 8))
    SL = _s('prsl', fontSize=9, leading=12, alignment=TA_RIGHT, textColor=colors.HexColor('#333'))
    SR = _s('prsr', fontSize=9, leading=12, alignment=TA_RIGHT)
    SR_B = _s('prsrb', fontSize=9, leading=12, alignment=TA_RIGHT, fontName='Helvetica-Bold')
    sum_rows = [[Paragraph('Sub Total', SL), Paragraph(f'{subtotal_gross:.2f}', SR)]]
    if show_discount and discount_total > 0.001:
        sum_rows.append([Paragraph('Discount  (–)', SL), Paragraph(f'{discount_total:.2f}', SR)])
    sum_rows.append([Paragraph('<b>Grand Total</b>', SL), Paragraph(f'<b>{grand_total:.2f}</b>', SR_B)])
    total_row_idx = len(sum_rows) - 1
    sum_tbl = Table(sum_rows, colWidths=[W - 1.6 * inch, 1.6 * inch], hAlign='LEFT')
    sum_tbl.setStyle(TableStyle([('BOX', (0, 0), (-1, -1), 0.5, BORDER), ('LINEBELOW', (0, 0), (-1, -2), 0.3, colors.HexColor('#dde3ea')), ('BACKGROUND', (0, total_row_idx), (-1, total_row_idx), BLUE_LIGHT), ('FONTSIZE', (0, 0), (-1, -1), 9), ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'), ('TOPPADDING', (0, 0), (-1, -1), PAD), ('BOTTOMPADDING', (0, 0), (-1, -1), PAD), ('LEFTPADDING', (0, 0), (-1, -1), PAD), ('RIGHTPADDING', (0, 0), (-1, -1), PAD)]))
    elements.append(sum_tbl)
    doc.build(elements)
    return (buffer.getvalue(), None)

def _build_purchase_return_order_pdf_bytes(goods_return_no: Any) -> tuple:
    gno = parse_goodsreturnno_from_request(goods_return_no)
    header = _get_purchase_return_header(gno)
    if not header:
        return (None, 'Purchase Return Order not found.')
    lines = _get_purchase_return_details(gno)
    _enrich_pr_header_discount(header, lines)
    is_debit = str(header.get('returntype') or '').strip().upper() == 'D'
    title = 'PURCHASE DEBIT NOTE REQUEST' if is_debit else 'PURCHASE RETURN ORDER'
    label = 'Request No' if is_debit else 'Return No'
    return _build_purchase_return_doc_pdf_bytes(header, lines, doc_title=title, doc_no_label=label)

def _build_purchase_return_pdf_bytes(goods_return_no: int) -> tuple:
    header = _get_posted_purchase_return_header(goods_return_no, return_type='P,R')
    if not header:
        return (None, 'Purchase Return not found.')
    lines = _get_posted_purchase_return_details(goods_return_no)
    _enrich_pr_header_discount(header, lines)
    return _build_purchase_return_doc_pdf_bytes(header, lines, doc_title='PURCHASE RETURN', doc_no_label='Return No')

def _build_purchase_debit_note_pdf_bytes(dr_no: int) -> tuple:
    if not REPORTLAB_AVAILABLE:
        return (None, 'PDF library (reportlab) is not available.')
    header = _get_purchase_debit_note_header(dr_no)
    if not header:
        return (None, 'Purchase Debit Note not found.')
    lines = _get_purchase_debit_note_details(dr_no)
    supplier_code = str(header.get('suppliercode') or '').strip()
    supplier = _get_supplier_profile(supplier_code)
    company = _get_company_profile()
    supplier_name = str(supplier.get('name') or '')
    company_name = str(company.get('name') or session.get('location_name') or '')
    company_address = str(company.get('address') or '')
    company_phone = str(company.get('phone') or '')
    company_email = str(company.get('email') or '')
    username = str(session.get('user') or '')
    return_date = str(header.get('returndate') or '')
    return_date_display = return_date
    try:
        if return_date:
            return_date_display = datetime.strptime(return_date[:10], '%Y-%m-%d').strftime('%d-%m-%Y')
    except Exception:
        return_date_display = return_date
    remarks = str(header.get('sectioninc') or '')
    subtotal = 0.0
    table_rows = [['S.No', 'Item Code', 'Item Name', 'UOM', 'Qty', 'Rate', 'Inv. Loc', 'Amount']]
    for idx, ln in enumerate(lines or [], 1):
        qty = float(ln.get('quantity') or 0)
        rate = float(ln.get('rate') or 0)
        amt = float(ln.get('amount') or qty * rate)
        subtotal += amt
        table_rows.append([str(idx), str(ln.get('itemcode') or ''), str(ln.get('itemname') or ''), str(ln.get('uom') or 'NOS').upper(), f'{qty:.2f}', f'{rate:.3f}', str(ln.get('store') or ''), f'{amt:.2f}'])
    grand_total = float(header.get('returnamount') or subtotal)
    styles = getSampleStyleSheet()
    BLUE = colors.HexColor('#1a56a4')
    BLUE_LIGHT = colors.HexColor('#e8f0fb')
    BORDER = colors.HexColor('#b0b8c4')
    GRAY_ROW = colors.HexColor('#f7f8fa')
    TEXT = colors.HexColor('#1a1a1a')
    PAD = 5

    def _s(name, **kw):
        base = kw.pop('parent', styles['Normal'])
        kw.setdefault('textColor', TEXT)
        return ParagraphStyle(name, parent=base, **kw)
    N9 = _s('dn9', fontSize=9, leading=12)
    N9R = _s('dn9r', fontSize=9, leading=12, alignment=TA_RIGHT)
    LBL = _s('dnlbl', fontSize=8, leading=11, textColor=colors.HexColor('#555f6b'))
    SUB = _s('dnsub', fontSize=9, leading=12, alignment=TA_CENTER, textColor=colors.HexColor('#555f6b'))
    WHT = _s('dnwht', fontSize=9, leading=12, alignment=TA_CENTER, textColor=colors.white)
    W = 7.47 * inch
    LEFT_W = W * 0.57
    RIGHT_W = W - LEFT_W
    buffer = io.BytesIO()
    doc = SimpleDocTemplate(buffer, pagesize=A4, topMargin=0.45 * inch, bottomMargin=0.35 * inch, leftMargin=0.4 * inch, rightMargin=0.4 * inch)
    elements = []
    company_lines = [Paragraph(f'<b>{company_name}</b>', _s('dncn', fontSize=11, leading=14, alignment=TA_CENTER, textColor=BLUE))]
    if company_address:
        company_lines.append(Paragraph(company_address, SUB))
    if company_phone:
        company_lines.append(Paragraph(f'Tel: {company_phone}', SUB))
    if company_email:
        company_lines.append(Paragraph(f'Email: {company_email}', SUB))
    title_tbl = Table([[company_lines]], colWidths=[W], hAlign='LEFT')
    title_tbl.setStyle(TableStyle([('VALIGN', (0, 0), (-1, -1), 'MIDDLE'), ('ALIGN', (0, 0), (0, 0), 'CENTER'), ('TOPPADDING', (0, 0), (-1, -1), PAD), ('BOTTOMPADDING', (0, 0), (-1, -1), PAD), ('LEFTPADDING', (0, 0), (-1, -1), PAD), ('RIGHTPADDING', (0, 0), (-1, -1), PAD)]))
    elements.append(title_tbl)
    elements.append(Spacer(1, 2))
    elements.append(Paragraph('<b>PURCHASE DEBIT NOTE</b>', _s('dnt1', fontSize=12, leading=15, alignment=TA_CENTER, textColor=BLUE)))
    elements.append(Spacer(1, 4))
    rule_tbl = Table([['']], colWidths=[W], rowHeights=[2], hAlign='LEFT')
    rule_tbl.setStyle(TableStyle([('BACKGROUND', (0, 0), (-1, -1), BLUE)]))
    elements.append(rule_tbl)
    elements.append(Spacer(1, 6))

    def _info_row(label, value):
        return [Paragraph(label, LBL), Paragraph(str(value or ''), N9)]
    left_rows = [_info_row('Supplier Code', supplier_code), _info_row('Supplier Name', supplier_name), _info_row('Remarks', remarks)]
    right_rows = [_info_row('Debit Note No', dr_no), _info_row('Date', return_date_display), _info_row('Prepared By', username)]
    LBL_W = 1.35 * inch
    VAL_W = LEFT_W - LBL_W - 0.1 * inch
    LBL_W2 = 1.2 * inch
    VAL_W2 = RIGHT_W - LBL_W2 - 0.1 * inch
    left_tbl = Table(left_rows, colWidths=[LBL_W, VAL_W])
    right_tbl = Table(right_rows, colWidths=[LBL_W2, VAL_W2])
    for t in (left_tbl, right_tbl):
        t.setStyle(TableStyle([('FONTSIZE', (0, 0), (-1, -1), 8.5), ('VALIGN', (0, 0), (-1, -1), 'TOP'), ('LINEBELOW', (0, 0), (-1, -2), 0.3, colors.HexColor('#dde3ea')), ('TOPPADDING', (0, 0), (-1, -1), PAD), ('BOTTOMPADDING', (0, 0), (-1, -1), PAD), ('LEFTPADDING', (0, 0), (-1, -1), PAD), ('RIGHTPADDING', (0, 0), (-1, -1), PAD)]))
    info_outer = Table([[left_tbl, right_tbl]], colWidths=[LEFT_W, RIGHT_W], hAlign='LEFT')
    info_outer.setStyle(TableStyle([('BOX', (0, 0), (-1, -1), 0.5, BORDER), ('LINEBEFORE', (1, 0), (1, 0), 0.5, BORDER), ('BACKGROUND', (0, 0), (-1, -1), BLUE_LIGHT), ('VALIGN', (0, 0), (-1, -1), 'TOP'), ('LEFTPADDING', (0, 0), (-1, -1), PAD), ('RIGHTPADDING', (0, 0), (-1, -1), PAD), ('TOPPADDING', (0, 0), (-1, -1), PAD), ('BOTTOMPADDING', (0, 0), (-1, -1), PAD)]))
    elements.append(info_outer)
    elements.append(Spacer(1, 8))

    def _hcell(txt):
        return Paragraph(f'<b>{txt}</b>', WHT)

    def _dcell(txt, align='LEFT'):
        st = N9R if align == 'RIGHT' else N9
        return Paragraph(str(txt), st)
    pt_rows = [[_hcell(c) for c in table_rows[0]]]
    for row in table_rows[1:]:
        pt_rows.append([_dcell(row[0], 'RIGHT'), _dcell(row[1]), _dcell(row[2]), _dcell(row[3]), _dcell(row[4], 'RIGHT'), _dcell(row[5], 'RIGHT'), _dcell(row[6], 'CENTER'), _dcell(row[7], 'RIGHT')])
    pt = Table(pt_rows, repeatRows=1, colWidths=[0.35 * inch, 0.85 * inch, 2.25 * inch, 0.55 * inch, 0.7 * inch, 0.8 * inch, 1.0 * inch, 0.97 * inch], hAlign='LEFT')
    pt.setStyle(TableStyle([('BACKGROUND', (0, 0), (-1, 0), BLUE), ('TEXTCOLOR', (0, 0), (-1, 0), colors.white), ('FONTSIZE', (0, 0), (-1, -1), 8.5), ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'), ('GRID', (0, 0), (-1, -1), 0.4, BORDER), ('ROWBACKGROUNDS', (0, 1), (-1, -1), [colors.white, GRAY_ROW]), ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'), ('TOPPADDING', (0, 0), (-1, -1), PAD), ('BOTTOMPADDING', (0, 0), (-1, -1), PAD), ('LEFTPADDING', (0, 0), (-1, -1), PAD), ('RIGHTPADDING', (0, 0), (-1, -1), PAD)]))
    elements.append(pt)
    elements.append(Spacer(1, 8))
    SL = _s('dnsl', fontSize=9, leading=12, alignment=TA_RIGHT, textColor=colors.HexColor('#333'))
    SR = _s('dnsr', fontSize=9, leading=12, alignment=TA_RIGHT)
    sum_rows = [[Paragraph('Sub Total', SL), Paragraph(f'{subtotal:.2f}', SR)], [Paragraph('<b>Grand Total</b>', SL), Paragraph(f'<b>{grand_total:.2f}</b>', SR)]]
    sum_tbl = Table(sum_rows, colWidths=[W - 1.6 * inch, 1.6 * inch], hAlign='LEFT')
    sum_tbl.setStyle(TableStyle([('BOX', (0, 0), (-1, -1), 0.5, BORDER), ('LINEBELOW', (0, 0), (-1, -2), 0.3, colors.HexColor('#dde3ea')), ('BACKGROUND', (0, -1), (-1, -1), BLUE_LIGHT), ('FONTSIZE', (0, 0), (-1, -1), 9), ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'), ('TOPPADDING', (0, 0), (-1, -1), PAD), ('BOTTOMPADDING', (0, 0), (-1, -1), PAD), ('LEFTPADDING', (0, 0), (-1, -1), PAD), ('RIGHTPADDING', (0, 0), (-1, -1), PAD)]))
    elements.append(sum_tbl)
    doc.build(elements)
    return (buffer.getvalue(), None)

