def api_lpo_pdf(lpo_no: str):
    if not session.get('user'):
        return jsonify({'error': 'Not authenticated'}, 401)
    _apply_db()
    lpo_key = parse_lpono_from_request(lpo_no)
    pdf_bytes, err = _build_lpo_pdf_bytes(lpo_key)
