def _receipt_next_no() -> Any:
    ensure_receiptno_varchar_columns()
    loc_code = _resolve_location_code()
    peeked = peek_next_grn_receipt_no(loc_code, reset_no=RESET_NO)
    if peeked is not None and receiptno_is_valid(peeked):
        return peeked
    tbl = _detect_table(['RECEIPTHDR', 'receipthdr'])
    if not tbl:
        return coerce_receiptno(1)
    no_col = _detect_column(tbl, ['RECEIPTNO', 'RECEIPT_NO', 'receiptno'])
    loc_col = _detect_column(tbl, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    reset_col = _detect_column(tbl, ['RESETNO', 'RESET_NO', 'resetno'])
    if not no_col:
        return coerce_receiptno(1)
    where = ' 1=1 '
    params: Dict[str, Any] = {}
    if loc_col:
        where += f' AND {loc_col} = :loc'
        params['loc'] = loc_code
    if reset_col:
        where += f' AND {reset_col} = :rn'
        params['rn'] = RESET_NO
    q = f'SELECT NVL(MAX({no_col}), 0) + 1 AS n FROM {tbl} WHERE {where}'
    try:
        _, rows = _fetch_rows(q, params)
        n = int(rows[0]['n']) if rows else 1
        return coerce_receiptno(n)
    except Exception:
        return coerce_receiptno(1)

def _grn_list_supplier_name_expr(hdr_alias: str, sup_col: Optional[str], loc_col: Optional[str], supp_tbl: Optional[str], sup_code_col: Optional[str], sup_name_col: Optional[str]) -> str:
    if not (supp_tbl and sup_col and sup_code_col and sup_name_col):
        return 'NULL AS suppliername'
    s_loc = _detect_column(supp_tbl, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    loc_match = f' AND s.{s_loc} = {hdr_alias}.{loc_col}' if s_loc and loc_col else ''
    return (
        f"(SELECT NVL(MAX(s.{sup_name_col}), '') FROM {supp_tbl} s"
        f" WHERE s.{sup_code_col} = {hdr_alias}.{sup_col}{loc_match}) AS suppliername"
    )

def _grn_hdr_line_discount_sql(hdr_alias: str, hdr_tbl: str) -> str:
    """Scalar subquery: sum RECEIPTDTL line discounts for one RECEIPTHDR row."""
    dtl_tbl = _detect_table(['RECEIPTDTL', 'receiptdtl'])
    if not dtl_tbl:
        return '0'
    h_no = _detect_column(hdr_tbl, ['RECEIPTNO', 'RECEIPT_NO', 'receiptno'])
    h_loc = _detect_column(hdr_tbl, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    h_reset = _detect_column(hdr_tbl, ['RESETNO', 'RESET_NO', 'resetno'])
    d_no = _detect_column(dtl_tbl, ['RECEIPTNO', 'RECEIPT_NO', 'receiptno'])
    d_loc = _detect_column(dtl_tbl, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    d_reset = _detect_column(dtl_tbl, ['RESETNO', 'RESET_NO', 'resetno'])
    d_disc = _detect_column(dtl_tbl, ['DISCOUNT', 'discount'])
    if not (h_no and d_no and d_disc):
        return '0'
    d_where = [f'd.{d_no} = {hdr_alias}.{h_no}']
    if d_loc and h_loc:
        d_where.append(f'd.{d_loc} = {hdr_alias}.{h_loc}')
    if d_reset and h_reset:
        d_where.append(f'd.{d_reset} = {hdr_alias}.{h_reset}')
    return (
        f'(SELECT NVL(SUM(NVL(d.{d_disc}, 0)), 0) FROM {dtl_tbl} d WHERE {" AND ".join(d_where)})'
    )


def _grn_hdr_discount_list_expr(hdr_alias: str, hdr_tbl: str) -> str:
    """Fast list-screen discount (header column only — no per-row RECEIPTDTL subquery)."""
    disc_col = _detect_column(hdr_tbl, ['DISCOUNT', 'discount'])
    if disc_col:
        return f'NVL({hdr_alias}.{disc_col}, 0) AS discount'
    return '0 AS discount'


def _grn_receipt_keys_for_batch(receipt_nos: List[Any]) -> List[Any]:
    nos: List[Any] = []
    seen: Set[str] = set()
    for x in receipt_nos or []:
        rno = coerce_receiptno(x)
        if not receiptno_is_valid(rno):
            continue
        key = str(rno)
        if key not in seen:
            seen.add(key)
            nos.append(rno)
    return nos


def _grn_receiptno_sql_in_list(keys: Set[str]) -> str:
    return ', '.join(
        f"'{s.replace(chr(39), chr(39) + chr(39))}'" for s in sorted(k for k in keys if k and k != '0')
    )

def _pr_hdr_line_discount_sql(hdr_alias: str, hdr_tbl: str, *, temp: bool=False) -> str:
    """Scalar subquery: sum RETURNDTL / TEMPRETURNDTL line discounts for one return header row."""
    dtl_tbl = _detect_table(['TEMPRETURNDTL', 'tempreturndtl'] if temp else ['RETURNDTL', 'returndtl'])
    if not dtl_tbl:
        return '0'
    h_no = _detect_column(hdr_tbl, ['GOODSRETURNNO', 'goodsreturnno'])
    h_loc = _detect_column(hdr_tbl, ['LOCATIONCODE', 'locationcode'])
    h_reset = _detect_column(hdr_tbl, ['RESETNO', 'RESET_NO', 'resetno'])
    d_no = _detect_column(dtl_tbl, ['GOODSRETURNNO', 'goodsreturnno'])
    d_loc = _detect_column(dtl_tbl, ['LOCATIONCODE', 'locationcode'])
    d_reset = _detect_column(dtl_tbl, ['RESETNO', 'RESET_NO', 'resetno'])
    d_disc = _detect_column(dtl_tbl, ['DISCOUNT', 'discount'])
    if not (h_no and d_no and d_disc):
        return '0'
    d_where = [f'd.{d_no} = {hdr_alias}.{h_no}']
    if d_loc and h_loc:
        d_where.append(f'd.{d_loc} = {hdr_alias}.{h_loc}')
    if d_reset and h_reset:
        d_where.append(f'd.{d_reset} = {hdr_alias}.{h_reset}')
    return (
        f'(SELECT NVL(SUM(NVL(d.{d_disc}, 0)), 0) FROM {dtl_tbl} d WHERE {" AND ".join(d_where)})'
    )

def _pr_hdr_discount_expr(hdr_alias: str, hdr_tbl: str, *, temp: bool=False) -> str:
    """Header discount with line-sum fallback (RETURNHDR / TEMPRETURNHDR)."""
    line_disc_subq = _pr_hdr_line_discount_sql(hdr_alias, hdr_tbl, temp=temp)
    disc_col = _detect_column(hdr_tbl, ['DISCOUNT', 'discount'])
    if disc_col:
        return f'NVL(NULLIF({hdr_alias}.{disc_col}, 0), {line_disc_subq}) AS discount'
    return f'{line_disc_subq} AS discount'


def _pr_hdr_discount_list_expr(hdr_alias: str, hdr_tbl: str) -> str:
    """Fast list-screen discount (header column only — no per-row line subquery)."""
    disc_col = _detect_column(hdr_tbl, ['DISCOUNT', 'discount'])
    if disc_col:
        return f'NVL({hdr_alias}.{disc_col}, 0) AS discount'
    return '0 AS discount'

def _pr_sum_line_discount_from_details(details: List[Dict[str, Any]]) -> float:
    try:
        return round(sum(float(ln.get('discount') or 0) for ln in (details or []) if isinstance(ln, dict)), 2)
    except (TypeError, ValueError):
        return 0.0

def _enrich_pr_header_discount(header: Optional[Dict[str, Any]], details: List[Dict[str, Any]]) -> None:
    if header is None:
        return
    try:
        hdr_disc = float(header.get('discount') or 0)
    except (TypeError, ValueError):
        hdr_disc = 0.0
    if hdr_disc <= 0.001:
        header['discount'] = _pr_sum_line_discount_from_details(details)
    else:
        header['discount'] = round(hdr_disc, 2)

def _apply_pr_header_discount_to_lines(lines: List[Dict[str, Any]], header_discount: float) -> List[Dict[str, Any]]:
    """Split document-level discount across return lines (same rules as GRN trade discount)."""
    try:
        total_disc = float(header_discount or 0)
    except (TypeError, ValueError):
        total_disc = 0.0
    if total_disc <= 0.001:
        return lines
    return _distribute_grn_header_discount_to_lines(lines, total_disc)

def _get_receipt_list_page(page: int=1, per_page: int=50, search: Optional[str]=None, date_from: Optional[str]=None, date_to: Optional[str]=None, *, inventory_tab: str='posted') -> Tuple[List[Dict[str, Any]], int]:
    """Paginated GRN list — inventory_tab: ``draft`` | ``posted`` | ``reversed``."""
    tbl = _detect_table(['RECEIPTHDR', 'receipthdr'])
    if not tbl:
        return ([], 0)
    no_col = _detect_column(tbl, ['RECEIPTNO', 'RECEIPT_NO', 'receiptno'])
    date_col = _detect_column(tbl, ['RECEIPTDATE', 'RECEIPT_DATE', 'receiptdate'])
    sup_col = _detect_column(tbl, ['SUPPLIERCODE', 'SUPPLIER_CODE', 'suppliercode'])
    amt_col = _detect_column(tbl, ['INVOICEAMOUNT', 'INVOICE_AMOUNT', 'invoiceamount'])
    disc_col = _detect_column(tbl, ['DISCOUNT', 'discount'])
    inv_no_col = _detect_column(tbl, ['INVOICENO', 'INVOICE_NO', 'invoiceno'])
    created_col = _detect_column(tbl, ['CREATEDBY', 'CREATED_BY', 'createdby'])
    loc_col = _detect_column(tbl, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    del_col = _detect_column(tbl, ['DELFLAG', 'DEL_FLAG', 'delflag'])
    if not no_col:
        return ([], 0)
    loc_code = _resolve_location_code()
    page = max(1, int(page or 1))
    per_page = max(20, min(int(per_page or 50), 200))
    h = 'H'
    supp_tbl = _detect_table(['SUPPLIER', 'supplier', 'SUPPLIERS'])
    sup_name_col = _detect_column(supp_tbl, ['SUPPLIERNAME', 'SUPPLIER_NAME', 'suppliername']) if supp_tbl else None
    sup_code_col = _detect_column(supp_tbl, ['SUPPLIERCODE', 'SUPPLIER_CODE', 'suppliercode']) if supp_tbl else None
    where_parts: List[str] = []
    params: Dict[str, Any] = {'loc': loc_code}
    if loc_col:
        where_parts.append(f'{h}.{loc_col} = :loc')
    inv_tab = (inventory_tab or 'posted').strip().lower()
    if inv_tab == 'reversed':
        # Soft-void stubs reserved after GRN reverse (DELFLAG=Y / APPROVE_MODE=grn_reversed).
        if del_col:
            where_parts.append(f"NVL({h}.{del_col}, 'N') = 'Y'")
        mode_col = _detect_column(tbl, ['APPROVE_MODE', 'APPROVEMODE', 'POSTMODE', 'SAVE_MODE', 'SAVEMODE'])
        rem_col = _detect_column(tbl, ['REMARKS', 'remarks'])
        rev_bits: List[str] = []
        if mode_col:
            rev_bits.append(f"LOWER(NVL({h}.{mode_col}, '')) = 'grn_reversed'")
        if rem_col:
            rev_bits.append(f"UPPER(NVL({h}.{rem_col}, '')) LIKE '[REVERSED]%'")
        if rev_bits:
            where_parts.append('(' + ' OR '.join(rev_bits) + ')')
        elif not del_col:
            return ([], 0)
    else:
        if del_col:
            where_parts.append(f"NVL({h}.{del_col}, 'N') = 'N'")
        if inv_tab == 'draft':
            where_parts.append(_grn_inventory_posted_filter_sql(h, posted=False))
        elif inv_tab == 'posted':
            where_parts.append(_grn_inventory_posted_filter_sql(h, posted=True))
    if search:
        sp = search.upper().replace('*', '%')
        if '%' not in sp:
            sp = f'%{sp}%'
        params['search'] = sp
        bits = [f'TO_CHAR({h}.{no_col}) LIKE :search']
        if inv_no_col:
            bits.append(f'UPPER({h}.{inv_no_col}) LIKE :search')
        if sup_col:
            bits.append(f'TO_CHAR({h}.{sup_col}) LIKE :search')
        if supp_tbl and sup_name_col and sup_col and sup_code_col:
            bits.append(
                f"EXISTS (SELECT 1 FROM {supp_tbl} s WHERE s.{sup_code_col} = {h}.{sup_col}"
                f' AND UPPER(s.{sup_name_col}) LIKE :search)'
            )
        where_parts.append('(' + ' OR '.join(bits) + ')')
    if date_col and date_from:
        where_parts.append(f'TRUNC({h}.{date_col}) >= TO_DATE(:date_from, \'YYYY-MM-DD\')')
        params['date_from'] = date_from[:10]
    if date_col and date_to:
        where_parts.append(f'TRUNC({h}.{date_col}) <= TO_DATE(:date_to, \'YYYY-MM-DD\')')
        params['date_to'] = date_to[:10]
    where_sql = ' AND '.join(where_parts) if where_parts else '1=1'
    discount_expr = _grn_hdr_discount_list_expr(h, tbl)
    cols = [
        f'{h}.{no_col} AS receiptno',
        f'{h}.{date_col} AS receiptdate' if date_col else 'NULL AS receiptdate',
        f'{h}.{inv_no_col} AS invoiceno' if inv_no_col else 'NULL AS invoiceno',
        f'{h}.{sup_col} AS suppliercode' if sup_col else 'NULL AS suppliercode',
        'NULL AS suppliername',
        discount_expr,
        f'NVL({h}.{amt_col}, 0) AS amount' if amt_col else '0 AS amount',
        f'{h}.{created_col} AS createdby' if created_col else 'NULL AS createdby',
    ]
    base_from = f' FROM {tbl} {h} WHERE {where_sql} ORDER BY {h}.{no_col} DESC '
    count_q = f'SELECT COUNT(*) AS cnt FROM {tbl} {h} WHERE {where_sql}'
    base_q = f'SELECT {", ".join(cols)} {base_from}'
    cache_key = ('grn_completed', inv_tab, int(loc_code), (search or '').strip().upper(), date_from or '', date_to or '')
    cached_total = _lpo_list_count_cache_get(cache_key)
    total_count = cached_total if cached_total is not None else 0
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                if cached_total is None:
                    count_rows = _lpo_list_fetch_rows_cur(cur, count_q, dict(params))
                    total_count = int(count_rows[0].get('cnt') or 0) if count_rows else 0
                    _lpo_list_count_cache_set(cache_key, total_count)
                    if total_count == 0:
                        return ([], 0)
                offset = (page - 1) * per_page
                q_params = dict(params)
                q_params['max_row'] = offset + per_page
                q_params['min_row'] = offset
                page_q = f"\n                    SELECT receiptno, receiptdate, invoiceno, suppliercode, suppliername, discount, amount, createdby FROM (\n                        SELECT inner_q.*, ROWNUM rnum FROM (\n                            {base_q}\n                        ) inner_q WHERE ROWNUM <= :max_row\n                    ) WHERE rnum > :min_row\n                "
                rows = _lpo_list_fetch_rows_cur(cur, page_q, q_params)
                if rows:
                    sup_name_map = _lpo_list_supplier_names_for_page(cur, rows, supp_tbl, sup_code_col, sup_name_col, loc_code)
                    for r in rows:
                        sc = r.get('suppliercode')
                        if sc is not None and sc in sup_name_map:
                            r['suppliername'] = sup_name_map[sc]
                        try:
                            r['discount'] = round(float(r.get('discount') or 0), 2)
                        except (TypeError, ValueError):
                            r['discount'] = 0.0
                _grn_list_enrich_rows_cur(cur, rows, loc_code=loc_code, inv_tab=inv_tab)
                return (rows, total_count)
    except Exception as e:
        print(f'[_get_receipt_list_page] {e}')
        return ([], 0)

def _get_receipt_list() -> List[Dict[str, Any]]:
    rows, _ = _get_receipt_list_page(page=1, per_page=200)
    return rows

def _grn_pending_count_cache_key(loc_code: int, search: Optional[str], date_from: Optional[str], date_to: Optional[str]) -> Tuple[Any, ...]:
    return ('grn_pending', int(loc_code), (search or '').strip().upper(), date_from or '', date_to or '')


def _get_pending_po_for_grn_page(page: int=1, per_page: int=50, search: Optional[str]=None, date_from: Optional[str]=None, date_to: Optional[str]=None) -> Tuple[List[Dict[str, Any]], int]:
    """Approved LPOs without GRN — paginated (NOT EXISTS RECEIPTHDR, batched supplier names, cached COUNT)."""
    hdr = _detect_table(['LPOHDR', 'lpohdr', 'LPO_HDR'])
    if not hdr or not _table_exists('PURCHASE_APPROVAL_TXN'):
        return ([], 0)
    ensure_receipthdr_lpono_column(hdr)
    no_col = _detect_column(hdr, ['LPONO', 'LPO_NO', 'lpono'])
    date_col = _detect_column(hdr, ['LPODATE', 'LPO_DATE', 'lpodate'])
    sup_col = _detect_column(hdr, ['SUPPLIERCODE', 'SUPPLIER_CODE', 'suppliercode'])
    amt_col = _detect_column(hdr, ['LPOAMOUNT', 'LPO_AMOUNT', 'lpoamount'])
    disc_col = _detect_column(hdr, ['DISCOUNT', 'discount'])
    loc_col = _detect_column(hdr, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    del_col = _detect_column(hdr, ['DELFLAG', 'DEL_FLAG', 'delflag'])
    if not no_col:
        return ([], 0)
    loc_code = _resolve_location_code()
    page = max(1, int(page or 1))
    per_page = max(20, min(int(per_page or 50), 200))
    h = 'H'
    supp_tbl = _detect_table(['SUPPLIER', 'supplier', 'SUPPLIERS'])
    sup_code_col = _detect_column(supp_tbl, ['SUPPLIERCODE', 'SUPPLIER_CODE', 'suppliercode']) if supp_tbl else None
    sup_name_col = _detect_column(supp_tbl, ['SUPPLIERNAME', 'SUPPLIER_NAME', 'suppliername']) if supp_tbl else None
    pa_sub = (
        f"(SELECT DOC_NO FROM PURCHASE_APPROVAL_TXN"
        f" WHERE DOC_TYPE = 'LPO' AND LOCATIONCODE = :loc AND STATUS = 'APPROVED')"
    )
    where_parts: List[str] = []
    params: Dict[str, Any] = {'loc': loc_code}
    if loc_col:
        where_parts.append(f'{h}.{loc_col} = :loc')
    if del_col:
        where_parts.append(f"NVL({h}.{del_col}, 'N') = 'N'")
    receipt_exclude = _lpo_pending_po_exclude_receipt_sql(h, no_col, loc_col)
    if receipt_exclude:
        where_parts.append(receipt_exclude)
    if search:
        sp = search.upper().replace('*', '%')
        if '%' not in sp:
            sp = f'%{sp}%'
        params['search'] = sp
        bits = [f'TO_CHAR({h}.{no_col}) LIKE :search']
        if sup_col:
            bits.append(f'TO_CHAR({h}.{sup_col}) LIKE :search')
        if supp_tbl and sup_name_col and sup_col and sup_code_col:
            bits.append(
                f"EXISTS (SELECT 1 FROM {supp_tbl} s WHERE s.{sup_code_col} = {h}.{sup_col}"
                f' AND UPPER(s.{sup_name_col}) LIKE :search)'
            )
        where_parts.append('(' + ' OR '.join(bits) + ')')
    if date_col and date_from:
        where_parts.append(f'TRUNC({h}.{date_col}) >= TO_DATE(:date_from, \'YYYY-MM-DD\')')
        params['date_from'] = date_from[:10]
    if date_col and date_to:
        where_parts.append(f'TRUNC({h}.{date_col}) <= TO_DATE(:date_to, \'YYYY-MM-DD\')')
        params['date_to'] = date_to[:10]
    where_sql = ' AND '.join(where_parts) if where_parts else '1=1'
    cols = [
        f'{h}.{no_col} AS lpono',
        f'{h}.{date_col} AS lpodate' if date_col else 'NULL AS lpodate',
        f'{h}.{sup_col} AS suppliercode' if sup_col else 'NULL AS suppliercode',
        'NULL AS suppliername',
        f'NVL({h}.{disc_col}, 0) AS discount' if disc_col else '0 AS discount',
        f'NVL({h}.{amt_col}, 0) AS amount' if amt_col else '0 AS amount',
    ]
    base_from = (
        f' FROM {pa_sub} pa INNER JOIN {hdr} {h} ON {h}.{no_col} = pa.DOC_NO'
        f' WHERE {where_sql} ORDER BY {h}.{no_col} DESC '
    )
    count_q = (
        f'SELECT COUNT(*) AS cnt FROM {pa_sub} pa INNER JOIN {hdr} {h} ON {h}.{no_col} = pa.DOC_NO'
        f' WHERE {where_sql}'
    )
    base_q = f'SELECT {", ".join(cols)} {base_from}'
    cache_key = _grn_pending_count_cache_key(loc_code, search, date_from, date_to)
    total_count = _lpo_list_count_cache_get(cache_key)
    if total_count is None:
        total_count = 0
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                if total_count == 0:
                    count_rows = _lpo_list_fetch_rows_cur(cur, count_q, dict(params))
                    total_count = int(count_rows[0].get('cnt') or 0) if count_rows else 0
                    _lpo_list_count_cache_set(cache_key, total_count)
                    if total_count == 0:
                        return ([], 0)
                offset = (page - 1) * per_page
                q_params = dict(params)
                q_params['max_row'] = offset + per_page
                q_params['min_row'] = offset
                page_q = f"\n                    SELECT lpono, lpodate, suppliercode, suppliername, discount, amount FROM (\n                        SELECT inner_q.*, ROWNUM rnum FROM (\n                            {base_q}\n                        ) inner_q WHERE ROWNUM <= :max_row\n                    ) WHERE rnum > :min_row\n                "
                rows = _lpo_list_fetch_rows_cur(cur, page_q, q_params)
                if rows:
                    sup_name_map = _lpo_list_supplier_names_for_page(cur, rows, supp_tbl, sup_code_col, sup_name_col, loc_code)
                    for r in rows:
                        sc = r.get('suppliercode')
                        if sc is not None and sc in sup_name_map:
                            r['suppliername'] = sup_name_map[sc]
                        try:
                            r['discount'] = round(float(r.get('discount') or 0), 2)
                        except (TypeError, ValueError):
                            r['discount'] = 0.0
                return (rows, total_count)
    except Exception as e:
        print(f'[_get_pending_po_for_grn_page] {e}')
        return ([], 0)

def _get_pending_po_for_grn() -> List[Dict[str, Any]]:
    rows, _ = _get_pending_po_for_grn_page(page=1, per_page=200)
    return rows

def _po_has_receipt_for_lpo(lpo_no: Any) -> bool:
    """True if any active RECEIPTHDR references this LPO (goods already received)."""
    ensure_receipthdr_lpono_column()
    receipt_tbl = _detect_table(['RECEIPTHDR', 'receipthdr'])
    if not receipt_tbl:
        return False
    r_lpo_col = _detect_column(receipt_tbl, ['LPONO', 'LPO_NO', 'lpono'])
    r_loc_col = _detect_column(receipt_tbl, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    r_del_col = _detect_column(receipt_tbl, ['DELFLAG', 'DEL_FLAG', 'delflag'])
    if not r_lpo_col:
        return False
    loc_code = _resolve_location_code()
    wp = [f'{r_lpo_col} = :lpo']
    prm: Dict[str, Any] = {'lpo': coerce_lpono(lpo_no)}
    if r_loc_col:
        wp.append(f'{r_loc_col} = :loc')
        prm['loc'] = loc_code
    if r_del_col:
        wp.append(f"NVL({r_del_col}, 'N') = 'N'")
    try:
        _, rows = _fetch_rows(f"SELECT COUNT(*) AS c FROM {receipt_tbl} WHERE {' AND '.join(wp)}", prm)
        return int((rows[0] or {}).get('c') or 0) > 0 if rows else False
    except Exception:
        return False

def _get_receive_locations_for_item(itemcode: Any, location_code: Optional[int]=None) -> tuple:
    """Return (locations_list, from_itemstore).

    Primary: **ITEMMASTER** default store (STORE / STORECODE) for this item + branch.
    Then (legacy):
    - STOREINVENTORY / STOREINVENTORYNEW via get_item_store_inventory
    Fallback:
    - itemstore query
    - purchase locations
    """
    itemcode_txt = str(itemcode or '').strip()
    if not itemcode_txt:
        return (get_purchase_locations(), False)
    loc_int = int(location_code) if location_code is not None else _resolve_location_code()
    try:
        item_int = int(itemcode_txt)
        im_rows = get_item_store_rows_from_itemmaster(item_int, loc_int)
    except Exception:
        im_rows = []
    if im_rows:
        locs: List[Dict[str, Any]] = []
        for row in im_rows:
            code = (row.get('store') or row.get('STORE') or row.get('code') or '').strip()
            if not code:
                continue
            try:
                stock = float(row.get('stock') or row.get('STOCK') or 0)
            except (TypeError, ValueError):
                stock = 0.0
            locs.append({'code': code, 'stock': stock})
        if locs:
            return (locs, True)
    try:
        item_int = int(itemcode_txt)
        si_rows = get_item_store_inventory(loc_int, item_int)
    except Exception:
        si_rows = []
    if si_rows:
        locs: List[Dict[str, Any]] = []
        for row in si_rows:
            code = (row.get('store') or row.get('STORE') or '').strip()
            if not code:
                continue
            try:
                stock = float(row.get('stock') or row.get('STOCK') or 0)
            except (TypeError, ValueError):
                stock = 0.0
            locs.append({'code': code, 'stock': stock})
        if locs:
            return (locs, True)
    rows = get_item_stores_stock(itemcode_txt)
    if rows:

        def inv_loc_val(r):
            return (r.get('itemlocation') or r.get('ITEMLOCATION') or r.get('inventorylocation') or r.get('INVENTORYLOCATION') or r.get('location') or r.get('LOCATION') or r.get('store') or r.get('STORE') or '').strip() or None

        def stock_val(r):
            try:
                return float(r.get('stock') or r.get('STOCK') or 0)
            except (TypeError, ValueError):
                return 0.0
        locs = [{'code': inv_loc_val(r), 'stock': stock_val(r)} for r in rows if inv_loc_val(r)]
        if locs:
            return (locs, True)
    fallback = [{'code': (r.get('dbcode') or r.get('DBCODE') or '').strip()} for r in get_purchase_locations() if (r.get('dbcode') or r.get('DBCODE') or '').strip()]
    return (fallback, False)

def _grn_read_pdf_text(data: bytes) -> str:
    try:
        import fitz
        doc = fitz.open(stream=data, filetype='pdf')
        parts: List[str] = []
        for i in range(len(doc)):
            page = doc.load_page(i)
            chunk = page.get_text('text', sort=True) or page.get_text('text') or ''
            parts.append(chunk)
        doc.close()
        joined = '\n'.join(parts).strip()
        if len(joined) >= 20:
            return joined
    except Exception:
        pass
    try:
        from pypdf import PdfReader
        r = PdfReader(io.BytesIO(data))
        parts = [p.extract_text() or '' for p in r.pages]
        return '\n'.join(parts)
    except Exception:
        return ''

