@bp.route('/purchase/api/inventory-valuation')
def inventory_valuation_api():
    if not session.get('user'):
        return jsonify({'ok': False, 'error': 'Not logged in'}, 401)
    _apply_db()
    opts = _inventory_valuation_opts_from_request()
    try:
        common = {
            'search': opts.get('search') or None,
            'barcode': opts.get('barcode') or None,
            'item_code': opts.get('item_code'),
            'category_code': opts.get('category_code'),
            'cost_method': opts.get('cost_method') or 'average',
            'include_zero': opts['include_zero'],
            'limit': opts['per_page'],
            'offset': opts['offset'],
        }
        loc = _resolve_location_code()
        view = opts.get('view') or 'pivot'
        if view == 'list':
            payload = get_inventory_valuation_report(
                loc,
                warehouse_id=opts.get('warehouse_id'),
                **common,
            )
        else:
            payload = get_inventory_valuation_pivot_report(
                loc,
                warehouse_id=opts.get('warehouse_id'),
                **common,
            )
        return jsonify({'ok': True, **payload})
    except Exception as exc:
        logging.getLogger(__name__).exception('inventory_valuation_api failed')
        return jsonify({'ok': False, 'error': str(exc) or 'Report failed'}, 500)


@bp.route('/purchase/inventory-valuation/export.csv')
def inventory_valuation_export_csv():
    if not session.get('user'):
        return redirect(url_for('auth.login'))
    _apply_db()
    opts = _inventory_valuation_opts_from_request()
    loc = _resolve_location_code()
    common = _inventory_valuation_fetch_kwargs(opts)
    view = opts.get('view') or 'pivot'
    if view not in ('list', 'pivot', 'both'):
        view = 'pivot'
    ts = datetime.now().strftime('%Y%m%d-%H%M%S')
    loc_tag = f'b{loc}'

    if view == 'both':
        pivot_payload = get_inventory_valuation_pivot_report(
            loc, warehouse_id=opts.get('warehouse_id'), **common,
        )
        list_payload = get_inventory_valuation_report(
            loc, warehouse_id=opts.get('warehouse_id'), **common,
        )
        pivot_fields, pivot_rows = _inventory_valuation_pivot_csv_rows(pivot_payload)
        list_fields, list_rows = _inventory_valuation_list_csv_rows(list_payload)
        pivot_buf = io.StringIO()
        pivot_wrt = csv.DictWriter(pivot_buf, fieldnames=pivot_fields)
        pivot_wrt.writeheader()
        for row in pivot_rows:
            pivot_wrt.writerow(row)
        list_buf = io.StringIO()
        list_wrt = csv.DictWriter(list_buf, fieldnames=list_fields)
        list_wrt.writeheader()
        for row in list_rows:
            list_wrt.writerow(row)
        return _inventory_valuation_zip_csv_response([
            (f'inventory-valuation-pivot-{loc_tag}-{ts}.csv', pivot_buf),
            (f'inventory-valuation-list-{loc_tag}-{ts}.csv', list_buf),
        ])

    if view == 'list':
        payload = get_inventory_valuation_report(
            loc, warehouse_id=opts.get('warehouse_id'), **common,
        )
        fieldnames, out_rows = _inventory_valuation_list_csv_rows(payload)
        suffix = 'list'
    else:
        payload = get_inventory_valuation_pivot_report(
            loc, warehouse_id=opts.get('warehouse_id'), **common,
        )
        fieldnames, out_rows = _inventory_valuation_pivot_csv_rows(payload)
        suffix = 'pivot'
    buf = io.StringIO()
    wrt = csv.DictWriter(buf, fieldnames=fieldnames)
    wrt.writeheader()
    for row in out_rows:
        wrt.writerow(row)
    fname = f'inventory-valuation-{suffix}-{loc_tag}-{ts}.csv'
    return _inventory_valuation_csv_response(buf, fname)


@bp.route('/purchase/inventory-valuation/export.pdf')
def inventory_valuation_export_pdf():
    if not session.get('user'):
        return redirect(url_for('auth.login'))
    _apply_db()
