@bp.route('/purchase/repacking/api/save', methods=['POST'])
def repacking_save():
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    if not _try_acquire_session_lock(_REPACKING_SAVE_SESSION_LOCK_UNTIL):
        return json_response_rotate_global({
            'success': False,
            'error': 'A repacking save is already in progress for this session. Please wait until it completes.',
            'save_session_locked': True,
        }, 423)
    try:
        if not verify_consume_save_nonce(GLOBAL_SAVE_NONCE_SESSION_KEY, extract_submitted_save_nonce(request)):
            return replay_blocked_response_global()
        data = request.get_json(silent=True) or {}
        try:
            repack_no = int(data.get('repack_no') or 0)
        except Exception:
            repack_no = 0
        repack_date = (data.get('repack_date') or '').strip()
        remarks = (data.get('remarks') or '').strip()
        warehouse = (data.get('warehouse') or '').strip()
        lines = data.get('lines') or []
        if not repack_no or not repack_date:
            return json_response_rotate_global({'success': False, 'error': 'Repacking No and Date are required'}, 400)
        if not warehouse:
            return json_response_rotate_global({'success': False, 'error': 'Warehouse is required'}, 400)
        try:
            err = _save_repacking(repack_no, repack_date, remarks, warehouse, lines)
        except Exception as exc:
            return json_response_rotate_global({'success': False, 'error': str(exc)}, 400)
        if err:
            return json_response_rotate_global({'success': False, 'error': err}, 400)
        from addons.purchase.repacking_accounting import repacking_gl_voucher_no
        loc = _resolve_location_code()
        gl_vno = repacking_gl_voucher_no(loc, repack_no)
        list_url = url_for('purchase.repacking_list')
        pdf_url = url_for('purchase.repacking_pdf', repack_no=repack_no)
        pdf_error = None
        _pdf_bytes, pdf_err = _build_repacking_pdf_bytes(repack_no, gl_voucher_no=gl_vno)
        if pdf_err:
            pdf_error = pdf_err
        resp: Dict[str, Any] = {
            'success': True,
            'repack_no': repack_no,
            'message': f'Saved and posted. Stock, item journal, and GL {gl_vno}.',
            'gl_voucher_no': gl_vno,
            'list_url': list_url,
            'pdf_url': pdf_url if not pdf_error else None,
        }
        if pdf_error:
            resp['pdf_error'] = pdf_error
        return json_response_rotate_global(resp, 200)
    finally:
        _release_session_lock(_REPACKING_SAVE_SESSION_LOCK_UNTIL)


@bp.route('/purchase/repacking/pdf/<path:repack_no>')
def repacking_pdf(repack_no):
    if not session.get('user'):
        return redirect(url_for('auth.login'))
    _apply_db()
    repack_no = parse_repackno_from_request(repack_no)
    gl_vno = (request.args.get('gl_voucher_no') or '').strip() or None
    pdf_bytes, err = _build_repacking_pdf_bytes(repack_no, gl_voucher_no=gl_vno)
    if err:
        return jsonify({'error': err}, 400)
    return send_file(
        io.BytesIO(pdf_bytes),
        mimetype='application/pdf',
        as_attachment=False,
        download_name=f'repacking_{repack_no}.pdf',
    )


def _stk_adj_active_coa_options() -> List[Dict[str, str]]:
    accounts_out: List[Dict[str, str]] = []
    try:
        rows = get_all_chart_of_accounts() or []
    except Exception:
        rows = []
    for r in rows:
        if str(r.get('status') or 'ACTIVE').strip().upper() != 'ACTIVE':
            continue
        code = str(r.get('code') or '').strip()
        if not code:
            continue
        accounts_out.append({'code': code[:20], 'name': str(r.get('name') or '').strip()[:200]})
    accounts_out.sort(key=lambda x: str(x.get('code') or ''))
    return accounts_out


