STK_ADJ_IMPORT_JOB_MAX_ROWS = 50000
STK_ADJ_IMPORT_JOB_MAX_FILE_BYTES = 30 * 1024 * 1024
_STK_ADJ_IMPORT_POST_JOBS: Dict[str, Dict[str, Any]] = {}
_STK_ADJ_IMPORT_POST_JOBS_LOCK = threading.Lock()


def _stk_adj_import_job_put(job_id: str, updates: Dict[str, Any]) -> None:
    jid = str(job_id or '').strip()
    if not jid:
        return
    with _STK_ADJ_IMPORT_POST_JOBS_LOCK:
        job = _STK_ADJ_IMPORT_POST_JOBS.get(jid) or {}
        job.update(updates or {})
        job['updated_at'] = time.time()
        _STK_ADJ_IMPORT_POST_JOBS[jid] = job


def _stk_adj_import_job_get(job_id: str) -> Optional[Dict[str, Any]]:
    jid = str(job_id or '').strip()
    if not jid:
        return None
    with _STK_ADJ_IMPORT_POST_JOBS_LOCK:
        job = _STK_ADJ_IMPORT_POST_JOBS.get(jid)
        return dict(job) if job else None


def _stock_adjustment_import_post_worker(job_id: str, raw: bytes, ctx: Dict[str, Any]) -> None:
    tenant_id = str(ctx.get('tenant_id') or '').strip() or None
    if tenant_id:
        set_active_db_key(tenant_id)
    try:
        from addons.purchase.stock_adjustment_excel import build_lines_from_import_rows, parse_stk_adj_xlsx
        _stk_adj_import_job_put(job_id, {'status': 'RUNNING', 'phase': 'Reading Excel', 'processed': 0})
        rows, perr = parse_stk_adj_xlsx(raw, max_rows=STK_ADJ_IMPORT_JOB_MAX_ROWS)
        if perr:
            _stk_adj_import_job_put(job_id, {'status': 'FAILED', 'phase': 'Failed', 'error': perr})
            return
        if not rows:
            _stk_adj_import_job_put(job_id, {'status': 'FAILED', 'phase': 'Failed', 'error': 'No data rows found in the spreadsheet.'})
            return
        _stk_adj_import_job_put(job_id, {'phase': 'Validating rows', 'total': len(rows), 'processed': 0})

        loc = int(ctx.get('location_code') or 1)

        def _stk_adj_uom_valid(_item_code: Any, _uom: Optional[str]) -> bool:
            return False

        def _stk_adj_uom_factor(_item_code: Any, _uom: Optional[str]) -> float:
            return 1.0

        lines, errors = build_lines_from_import_rows(
            rows,
            location_code=loc,
            uom_factor_fn=_stk_adj_uom_factor,
            cost_fn=lambda ic, uom: _get_itemmaster_costprice(ic, loc),
            uom_valid_fn=_stk_adj_uom_valid,
            max_rows=STK_ADJ_IMPORT_JOB_MAX_ROWS,
        )
        bad_line_count = sum(1 for ln in lines if ln.get('field_errors'))
        if errors or bad_line_count:
            _stk_adj_import_job_put(job_id, {
                'status': 'FAILED',
                'phase': 'Validation failed',
                'error': f'{len(errors)} validation issue(s). Nothing was posted.',
                'errors': errors,
                'processed': len(lines),
                'total': len(rows),
            })
            return
        if not lines:
            _stk_adj_import_job_put(job_id, {'status': 'FAILED', 'phase': 'Failed', 'error': 'No valid stock adjustment lines found.'})
            return

        _stk_adj_import_job_put(job_id, {'phase': 'Posting inventory & GL', 'processed': len(lines), 'total': len(lines)})
        opening_stock = bool(ctx.get('opening_stock_mode'))
        err = _save_stock_adjustment(
            coerce_adjno(ctx.get('adj_no')),
            str(ctx.get('adj_date') or ''),
            str(ctx.get('remarks') or ''),
            lines,
            post_inventory=True,
            header_status='P',
            opening_stock=opening_stock,
            loc_code_override=loc,
            user_override=str(ctx.get('user') or 'web'),
        )
        if err:
            _stk_adj_import_job_put(job_id, {'status': 'FAILED', 'phase': 'Posting failed', 'error': err})
            return
        saved_adj_no = coerce_adjno(ctx.get('adj_no'))
        gl_vno = None
        try:
            from addons.purchase.stock_adjustment_accounting import stock_adjustment_gl_voucher_no
            gl_vno = stock_adjustment_gl_voucher_no(loc, ADJNO_SPEC.numeric_ref(saved_adj_no))
        except Exception:
            gl_vno = None
        _stk_adj_import_job_put(job_id, {
            'status': 'DONE',
            'phase': 'Completed',
            'processed': len(lines),
            'total': len(lines),
            'adj_no': saved_adj_no,
            'gl_voucher_no': gl_vno,
            'message': f"Imported and posted {len(lines)} line(s).",
        })
    except Exception as exc:
        _stk_adj_import_job_put(job_id, {'status': 'FAILED', 'phase': 'Failed', 'error': str(exc)})
    finally:
        if tenant_id:
            set_active_db_key(None)


@bp.route('/purchase/stock-adjustment/api/import-post-job', methods=['POST'])
def stock_adjustment_import_post_job_start():
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    try:
        adj_no = _adj_no_from_client(request.form.get('adj_no'))
    except Exception:
        adj_no = coerce_adjno(0)
    adj_date = (request.form.get('adj_date') or '').strip()
    remarks = (request.form.get('remarks') or '').strip()
    if not adjno_is_valid(adj_no) or not adj_date:
        return jsonify({'success': False, 'error': 'Adjustment No and Date are required.'}, 400)
    fobj = request.files.get('excel_file') or request.files.get('file')
    if not fobj or not getattr(fobj, 'filename', None):
        return jsonify({'success': False, 'error': 'Choose an Excel file (.xlsx).'}, 400)
    fname = str(fobj.filename or '').lower()
    if not fname.endswith(('.xlsx', '.xlsm')):
        return jsonify({'success': False, 'error': 'Please upload a .xlsx or .xlsm file.'}, 400)
    raw = fobj.read()
    if not isinstance(raw, bytes):
        raw = bytes(raw) if raw else b''
    if len(raw) > STK_ADJ_IMPORT_JOB_MAX_FILE_BYTES:
        return jsonify({'success': False, 'error': 'File too large (max 30 MB).'}, 400)
    job_id = secrets.token_urlsafe(16)
    ctx = {
        'adj_no': adj_no,
        'adj_date': adj_date,
        'remarks': remarks,
        'user': str(session.get('user') or 'web'),
        'tenant_id': str(session.get('tenant_id') or '').strip(),
        'location_code': _resolve_location_code(),
        'opening_stock_mode': get_stk_adj_opening_stock_mode_enabled(),
    }
    _stk_adj_import_job_put(job_id, {
        'status': 'QUEUED',
        'phase': 'Queued',
        'processed': 0,
        'total': 0,
        'created_at': time.time(),
        'adj_no': adj_no,
    })
    t = threading.Thread(
        target=_stock_adjustment_import_post_worker,
        args=(job_id, raw, ctx),
        daemon=True,
        name=f'stk-adj-import-post-{job_id[:6]}',
    )
    t.start()
    return jsonify({'success': True, 'job_id': job_id})


@bp.route('/purchase/stock-adjustment/api/import-post-job/<job_id>', methods=['GET'])
def stock_adjustment_import_post_job_status(job_id: str):
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    job = _stk_adj_import_job_get(job_id)
    if not job:
        return jsonify({'success': False, 'error': 'Import job not found or server restarted.'}, 404)
    out = {k: v for k, v in job.items() if k != 'errors'}
    out['success'] = True
    if job.get('status') == 'DONE':
        adj_no = coerce_adjno(job.get('adj_no'))
        out['list_url'] = url_for('purchase.stock_adjustment_list')
        out['pdf_url'] = url_for('purchase.stock_adjustment_pdf', adj_no=adj_no) if adjno_is_valid(adj_no) else ''
    if job.get('errors'):
        out['error_count'] = len(job.get('errors') or [])
        out['error_url'] = url_for('purchase.stock_adjustment_import_post_job_errors', job_id=job_id)
    return jsonify(out)


@bp.route('/purchase/stock-adjustment/api/import-post-job/<job_id>/errors', methods=['GET'])
def stock_adjustment_import_post_job_errors(job_id: str):
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    job = _stk_adj_import_job_get(job_id)
    if not job:
        return jsonify({'success': False, 'error': 'Import job not found or server restarted.'}, 404)
    errors = list(job.get('errors') or [])
    body = 'Row/Error\n' + '\n'.join('"' + str(e).replace('"', '""') + '"' for e in errors)
    return Response(
        body,
        mimetype='text/csv',
        headers={'Content-Disposition': f'attachment; filename="stock_adjustment_import_errors_{job_id[:8]}.csv"'},
    )


@bp.route('/purchase/stock-adjustment/import-template')
def stock_adjustment_import_template():
    """Download Excel template for stock adjustment line import."""
    if not session.get('user'):
        return redirect(url_for('auth.login'))
    try:
        from openpyxl import Workbook
    except ImportError:
        return jsonify({'success': False, 'error': 'Excel template requires openpyxl (pip install openpyxl).'}, 500)
