@bp.route('/purchase/stock-adjustment/api/import-excel', methods=['POST'])
def stock_adjustment_import_excel():
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    from addons.purchase.stock_adjustment_excel import (
        STK_ADJ_IMPORT_MAX_FILE_BYTES,
        build_lines_from_import_rows,
        parse_stk_adj_xlsx,
    )
    try:
        fobj = request.files.get('excel_file') or request.files.get('file')
        if not fobj or not getattr(fobj, 'filename', None):
            return jsonify({'success': False, 'error': 'Choose an Excel file (.xlsx).'}, 400)
        fname = str(fobj.filename or '').lower()
        if not fname.endswith(('.xlsx', '.xlsm')):
            return jsonify({'success': False, 'error': 'Please upload a .xlsx or .xlsm file.'}, 400)
        raw = fobj.read()
        if not isinstance(raw, bytes):
            raw = bytes(raw) if raw else b''
        if len(raw) > STK_ADJ_IMPORT_MAX_FILE_BYTES:
            return jsonify({'success': False, 'error': 'File too large (max 5 MB).'}, 400)
        rows, perr = parse_stk_adj_xlsx(raw)
        if perr:
            return jsonify({'success': False, 'error': perr}, 400)
        if not rows:
            return jsonify({'success': False, 'error': 'No data rows found in the spreadsheet.'}, 400)
        loc = _resolve_location_code()

        def _stk_adj_uom_valid(item_code: Any, uom: Optional[str]) -> bool:
            return False

        def _stk_adj_uom_factor(item_code: Any, uom: Optional[str]) -> float:
            return 1.0

        lines, errors = build_lines_from_import_rows(
            rows,
            location_code=int(loc),
            uom_factor_fn=_stk_adj_uom_factor,
            cost_fn=lambda ic, uom: _get_itemmaster_costprice(ic, loc),
            uom_valid_fn=_stk_adj_uom_valid,
        )
        if not lines:
            return jsonify({
                'success': False,
                'error': 'No data rows found in the spreadsheet.',
                'errors': errors[:50],
                'error_count': len(errors),
            }, 400)
        valid_count = sum(1 for ln in lines if not ln.get('field_errors'))
        return jsonify({
            'success': True,
            'lines': lines,
            'imported': len(lines),
            'valid_count': valid_count,
            'errors': errors[:50],
            'error_count': len(errors),
            'partial': bool(errors),
        })
    except Exception as exc:
        import traceback
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': f'Import failed: {exc}',
        }, 500)


@bp.route('/purchase/stock-adjustment/api/change-date', methods=['POST'])
def api_stock_adjustment_change_date():
    """Change stock adjustment date and GL voucher date (password required)."""
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    data = request.get_json(silent=True) or {}
    adj_no = parse_adjno_from_request(data.get('adj_no') or data.get('adjno'))
    new_adj_date = (data.get('new_adj_date') or data.get('adj_date') or data.get('new_date') or '').strip()
    new_gl_date = (data.get('new_gl_date') or data.get('gl_date') or '').strip()
    if not adjno_is_valid(adj_no):
        return json_response_keep_global_nonce({'success': False, 'error': 'Adjustment number is required.'}, 400)
    if not new_adj_date:
        return json_response_keep_global_nonce({'success': False, 'error': 'Adjustment date is required.'}, 400)
    pwd_err = _verify_current_user_password(
        data.get('password'),
        required_msg='Password is required to change date.',
    )
    if pwd_err:
        return json_response_keep_global_nonce({'success': False, 'error': pwd_err}, 403)
    if not verify_consume_save_nonce(GLOBAL_SAVE_NONCE_SESSION_KEY, extract_submitted_save_nonce(request)):
        return replay_blocked_response_global()
    ok, err = _change_stock_adjustment_dates(adj_no, new_adj_date, new_gl_date)
    if not ok:
        return json_response_rotate_global({'success': False, 'error': err or 'Date change failed.'}, 400)
    gl_iso = (new_gl_date or new_adj_date)[:10]
    return json_response_rotate_global({
        'success': True,
        'message': (
            f'Stock adjustment #{adj_no} dates updated — '
            f'adjustment {new_adj_date[:10]}, GL {gl_iso}.'
        ),
        'adj_no': adj_no,
        'adj_date': new_adj_date[:10],
        'gl_date': gl_iso,
    }, 200)


@bp.route('/purchase/stock-adjustment/<path:adj_no>/reverse', methods=['POST'])
def stock_adjustment_reverse(adj_no):
    wants_json = (
        (request.headers.get('X-Requested-With') or '').lower() == 'xmlhttprequest'
        or 'application/json' in (request.headers.get('Accept') or '').lower()
    )
    if not session.get('user'):
        if wants_json:
            return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
        return redirect(url_for('auth.login'))
    _apply_db()
    adj_no = parse_adjno_from_request(adj_no)
    data = request.get_json(silent=True) or {}
    if not data and request.form:
        data = request.form.to_dict()
    pwd_err = _verify_current_user_password(data.get('password'), required_msg='Password is required to reverse.')
    if pwd_err:
        if wants_json:
            return json_response_keep_global_nonce({'success': False, 'error': pwd_err}, 403)
        return redirect(url_for('purchase.stock_adjustment_list', reverse_error=pwd_err))
    if not verify_consume_save_nonce(GLOBAL_SAVE_NONCE_SESSION_KEY, extract_submitted_save_nonce(request)):
        if wants_json:
            return replay_blocked_response_global()
        return redirect(url_for('purchase.stock_adjustment_list', reverse_error='Duplicate or invalid reverse request. Refresh and try again.'))
    ok, err, rev_no = _reverse_stock_adjustment(adj_no, user=str(session.get('user') or 'web'))
    if not ok:
        if wants_json:
            return json_response_rotate_global({'success': False, 'error': err or 'Reverse failed.'}, 400)
        return redirect(url_for('purchase.stock_adjustment_view', adj_no=adj_no, reverse_error=err or 'Reverse failed.'))
    if wants_json:
        msg = f'Stock adjustment reversed. Reversal adjustment #{rev_no} was posted.'
        return json_response_rotate_global({
            'success': True,
            'message': msg,
            'reversal_no': rev_no,
            'list_url': url_for('purchase.stock_adjustment_list', reversed=rev_no),
            'view_url': url_for('purchase.stock_adjustment_view', adj_no=rev_no),
            'source_view_url': url_for('purchase.stock_adjustment_view', adj_no=adj_no),
            'pdf_url': url_for('purchase.stock_adjustment_pdf', adj_no=rev_no),
        }, 200)
    return redirect(url_for('purchase.stock_adjustment_view', adj_no=rev_no, reversed=1))

