@bp.route('/purchase/stock-adjustment/api/items')
def stock_adjustment_api_items():
    """Item picker for Stock Adjustment — same catalogue as PO item API plus STOREINVENTORY totals for the popup Stock column."""
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    search = (request.args.get('search') or '').strip()
    try:
        limit = int(request.args.get('limit') or 300)
        limit = min(max(limit, 50), 500)
    except (TypeError, ValueError):
        limit = 300
    rows = _get_items_for_location_filtered(search=search or None, limit=limit, supplier_code=None)
    loc = _resolve_location_code()
    codes_list: List[int] = []
    for r in rows or []:
        raw = r.get('code')
        try:
            codes_list.append(int(float(str(raw).strip())))
        except (TypeError, ValueError):
            pass
    summary = get_storeinventory_stock_summary_for_items(loc, codes_list)
    items_out: List[Dict[str, Any]] = []
    for r in rows or []:
        raw = r.get('code')
        try:
            ic = int(float(str(raw).strip()))
        except (TypeError, ValueError):
            ic = 0
        srow = summary.get(ic) if ic else None
        tot = float(srow.get('total') or 0) if srow else 0.0
        bstore = str(srow.get('best_store') or '').strip() if srow else ''
        items_out.append({
            'code': raw,
            'name': r.get('name'),
            'uom': r.get('uom'),
            'barcode': r.get('barcode'),
            'cost': r.get('cost'),
            'stock': tot,
            'best_store': bstore,
        })
    return jsonify({'success': True, 'items': items_out})

