@bp.route('/purchase/stock-adjustment/api/warehouses')
def stock_adjustment_warehouses():
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    stores = _get_transfer_store_options(skip_tbllocation_maintenance=True)
    codes = [
        str(s.get('code') or '').strip().upper()
        for s in (stores or [])
        if str(s.get('code') or '').strip()
    ]
    _, wh_row_map = _batch_warehouse_store_maps(codes)
    allow_neg_by_code: Dict[str, bool] = {}
    for wh in wh_row_map.values():
        code = str(wh.get('warehouse_code') or wh.get('WAREHOUSE_CODE') or '').strip().upper()
        if not code:
            continue
        allow_neg_by_code[code] = str(
            wh.get('allow_negative_stock') or wh.get('ALLOW_NEGATIVE_STOCK') or 'N'
        ).strip().upper() == 'Y'
    rows = [
        {
            'code': code,
            'name': str(s.get('description') or '').strip(),
            'allow_negative_stock': allow_neg_by_code.get(code, False),
        }
        for s in (stores or [])
        for code in [str(s.get('code') or '').strip().upper()]
        if code
    ]
    return jsonify({'success': True, 'warehouses': rows})


@bp.route('/purchase/stock-adjustment/api/item-stock')
def stock_adjustment_item_stock():
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    item_code = (request.args.get('item_code') or '').strip()
    store = (request.args.get('store') or '').strip().upper()
    if not item_code.isdigit():
        return jsonify({'success': False, 'error': 'Invalid item code'}, 400)
    loc = _resolve_location_code()
    rows = get_item_store_inventory(loc, int(item_code))
    if not rows:
        try:
            rows = get_item_store_rows_from_itemmaster(int(item_code), loc) or []
        except Exception:
            rows = []
    current_qty = 0.0
    if store:
        for r in rows or []:
            rs = str(r.get('store') or r.get('itemlocation') or '').strip().upper()
            if rs == store:
                current_qty = float(r.get('stock') or 0)
                break
    if not store and rows:
        best = max(rows, key=lambda x: float(x.get('stock') or 0))
        current_qty = float(best.get('stock') or 0)
        store = str(best.get('store') or best.get('itemlocation') or '').strip()
    return jsonify({'success': True, 'current_qty': current_qty, 'store': store, 'stores': rows})

STK_ADJ_SAVE_STAGING_SESSION_KEY = 'stk_adj_save_staging_v1'
_STK_ADJ_SAVE_STAGING_MEM: Dict[str, Dict[str, Any]] = {}
_STK_ADJ_STAGING_MEM_LOCK = threading.Lock()
_STK_ADJ_STAGING_TTL_SEC = 3600


def _stk_adj_staging_owner_key() -> str:
    u = str(session.get('user') or '')
    tid = str(session.get('tenant_id') or '')
    loc = str(session.get('location_code') or '')
    return f'{u}|{tid}|{loc}'


def _get_stk_adj_save_staging(save_token: str) -> Optional[Dict[str, Any]]:
    tok = str(save_token or '').strip()
    if not tok:
        return None
    with _STK_ADJ_STAGING_MEM_LOCK:
        rec = _STK_ADJ_SAVE_STAGING_MEM.get(tok)
        if not rec:
            return None
        if time.time() - float(rec.get('_ts') or 0) > _STK_ADJ_STAGING_TTL_SEC:
            _STK_ADJ_SAVE_STAGING_MEM.pop(tok, None)
            return None
        if str(rec.get('owner_key') or '') != _stk_adj_staging_owner_key():
            return None
        return rec


def _set_stk_adj_save_staging(save_token: str, data: Dict[str, Any]) -> None:
    tok = str(save_token or '').strip()
    if not tok:
        return
    payload = dict(data)
    payload['_ts'] = time.time()
    payload['owner_key'] = _stk_adj_staging_owner_key()
    with _STK_ADJ_STAGING_MEM_LOCK:
        _STK_ADJ_SAVE_STAGING_MEM[tok] = payload


def _clear_stk_adj_save_staging(save_token: Optional[str] = None) -> None:
    tok = str(save_token or '').strip()
    if tok:
        with _STK_ADJ_STAGING_MEM_LOCK:
            _STK_ADJ_SAVE_STAGING_MEM.pop(tok, None)
    session.pop(STK_ADJ_SAVE_STAGING_SESSION_KEY, None)
    session.modified = True


def _stock_adjustment_finalize_save(
    adj_no: Any,
    adj_date: str,
    remarks: str,
    lines: List[Dict[str, Any]],
    *,
    opening_stock: bool = False,
) -> tuple:
    """Run approval check + persist stock adjustment. Returns (response_dict, http_status) or raises."""
    # Create-only: if the form number is already used, take the next free number.
    requested_no = parse_adjno_from_request(adj_no)
    if not adjno_is_valid(requested_no) or _get_stock_adjustment_payload(requested_no):
        adj_no = _stock_adjustment_next_no(allocate=True)
    else:
        adj_no = coerce_adjno(requested_no)
    user = session.get('user') or 'web'
    loc = _resolve_location_code()
    needs_approval = False
    queue_id = None
    try:
        from addons.approval_workflow.approval_workflow_engine import evaluate_stock_adjustment_save
        needs_approval, wf_err, queue_id = evaluate_stock_adjustment_save(
            adj_no, lines, user, adj_date, loc_code=loc,
        )
        if wf_err:
            return ({'success': False, 'error': wf_err}, 400)
    except Exception:
        needs_approval = False
    try:
        err = _save_stock_adjustment(
            adj_no, adj_date, remarks, lines,
            post_inventory=not needs_approval,
            header_status='W' if needs_approval else 'P',
            opening_stock=opening_stock,
        )
    except StockAdjustmentWarehouseError as exc:
        if queue_id:
            try:
                from addons.approval_workflow.approval_workflow_engine import remove_pending_enqueue
                remove_pending_enqueue(loc, 'STK_ADJ', adj_no, queue_id=queue_id)
            except Exception:
                pass
        return ({
            'success': False,
            'error': str(exc),
            'negative_stock_lines': exc.line_issues,
        }, 400)
    except Exception as exc:
        msg = str(exc)
        if 'FK_STKADJDTL_TBLPAYMEN' in msg or 'TBLPAYMENTFOLLOWUP' in msg:
            msg = 'Stock adjustment detail could not be saved: invalid database constraint on line number (STKADJDTL.SLNO). Restart the app and try again.'
        if queue_id:
            try:
                from addons.approval_workflow.approval_workflow_engine import remove_pending_enqueue
                remove_pending_enqueue(loc, 'STK_ADJ', adj_no, queue_id=queue_id)
            except Exception:
                pass
        return ({'success': False, 'error': msg}, 400)
    if err:
        if queue_id:
            try:
                from addons.approval_workflow.approval_workflow_engine import remove_pending_enqueue
                remove_pending_enqueue(loc, 'STK_ADJ', adj_no, queue_id=queue_id)
            except Exception:
                pass
        return ({'success': False, 'error': err}, 400)
    from addons.purchase.stock_adjustment_accounting import stock_adjustment_gl_voucher_no
    if needs_approval:
        msg = 'Submitted for approval. Inventory and accounts will post after final approval.'
        gl_vno = None
    else:
        gl_vno = stock_adjustment_gl_voucher_no(loc, adj_no)
        msg = f'Saved and posted. Stock, item journal, and GL {gl_vno}.'
    return ({
        'success': True,
        'adj_no': adj_no,
        'needs_approval': needs_approval,
        'queue_id': queue_id,
        'message': msg,
        'gl_voucher_no': gl_vno,
        'list_url': url_for('purchase.stock_adjustment_list'),
        'pdf_url': url_for('purchase.stock_adjustment_pdf', adj_no=adj_no),
        'lines_total': len(lines or []),
        'lines_saved': len(lines or []),
    }, 200)


@bp.route('/purchase/stock-adjustment/api/save-batch', methods=['POST'])
def stock_adjustment_save_batch():
    """Staged save for large adjustments — client sends lines in batches with progress."""
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    if not _try_acquire_session_lock(_STOCK_ADJUSTMENT_SAVE_SESSION_LOCK_UNTIL):
        return json_response_rotate_global({
            'success': False,
            'error': 'A stock adjustment save is already in progress for this session. Please wait until it completes.',
            'save_session_locked': True,
        }, 423)
    lock_held = True
    data: Dict[str, Any] = {}
    try:
        data = request.get_json(silent=True) or {}
        submitted_nonce = extract_submitted_save_nonce(request)
        adj_no = _adj_no_from_client(data.get('adj_no'))
        adj_date = (data.get('adj_date') or '').strip()
        remarks = (data.get('remarks') or '').strip()
        existing_payload = _get_stock_adjustment_payload(adj_no) if adjno_is_valid(adj_no) else None
        if existing_payload:
            opening_stock = bool((existing_payload.get('header') or {}).get('opening_stock'))
        else:
            opening_stock = get_stk_adj_opening_stock_mode_enabled()
        batch_lines = data.get('lines') or []
        if not isinstance(batch_lines, list):
            batch_lines = []
        try:
            batch_index = int(data.get('batch_index') or 0)
        except Exception:
            batch_index = 0
        try:
            batch_count = int(data.get('batch_count') or 1)
        except Exception:
            batch_count = 1
        is_final_batch = bool(data.get('is_final_batch'))
        save_token = str(data.get('save_token') or '').strip()
        try:
            lines_total = int(data.get('lines_total') or 0)
        except Exception:
            lines_total = 0
        if not adjno_is_valid(adj_no) or not adj_date:
            return json_response_keep_global_nonce({'success': False, 'error': 'Adjustment No and Date are required'}, 400)
        if batch_count < 1:
            batch_count = 1
        if batch_index < 0 or batch_index >= batch_count:
            return json_response_keep_global_nonce({'success': False, 'error': 'Invalid batch index.'}, 400)
        if not batch_lines and not is_final_batch:
            return json_response_keep_global_nonce({'success': False, 'error': 'Batch has no lines.'}, 400)

        staging: Optional[Dict[str, Any]] = None
        if batch_index == 0:
            if not peek_save_nonce(GLOBAL_SAVE_NONCE_SESSION_KEY, submitted_nonce):
                return replay_blocked_response_global()
            save_token = secrets.token_hex(16)
            staging = {
                'save_token': save_token,
                'adj_no': adj_no,
                'adj_date': adj_date,
                'remarks': remarks,
                'opening_stock': opening_stock,
                'lines': list(batch_lines),
                'lines_total': lines_total or len(batch_lines),
                'batch_count': batch_count,
                'save_nonce': submitted_nonce,
            }
            _set_stk_adj_save_staging(save_token, staging)
        else:
            if not save_token:
                return json_response_keep_global_nonce({'success': False, 'error': 'Missing save token. Please save again from the start.'}, 400)
            staging = _get_stk_adj_save_staging(save_token)
            if not staging:
                return json_response_keep_global_nonce({'success': False, 'error': 'Save session expired. Please save again from the start.'}, 400)
            if str(coerce_adjno(staging.get('adj_no'))) != str(coerce_adjno(adj_no)):
                _clear_stk_adj_save_staging(save_token)
                return json_response_keep_global_nonce({'success': False, 'error': 'Adjustment number mismatch. Please save again.'}, 400)
            if not peek_save_nonce(GLOBAL_SAVE_NONCE_SESSION_KEY, staging.get('save_nonce') or submitted_nonce):
                _clear_stk_adj_save_staging(save_token)
                return replay_blocked_response_global()
            staging['lines'] = list(staging.get('lines') or []) + list(batch_lines)
            _set_stk_adj_save_staging(save_token, staging)

        all_lines = list(staging.get('lines') or [])
        total_expected = int(staging.get('lines_total') or lines_total or len(all_lines))
        lines_saved = len(all_lines)

        if not is_final_batch:
            return json_response_keep_global_nonce({
                'success': True,
                'staged': True,
                'save_token': staging.get('save_token') or save_token,
                'batch_index': batch_index,
                'batch_count': batch_count,
                'lines_saved': lines_saved,
                'lines_total': total_expected,
            }, 200)

        if batch_index != batch_count - 1:
            return json_response_keep_global_nonce({'success': False, 'error': 'Final batch index mismatch.'}, 400)
        if total_expected and lines_saved != total_expected:
            return json_response_keep_global_nonce({
                'success': False,
                'error': f'Expected {total_expected} lines but received {lines_saved}. Please save again.',
            }, 400)
        if not commit_form_save_nonce(staging.get('save_nonce') or submitted_nonce):
            _clear_stk_adj_save_staging(save_token)
            return replay_blocked_response_global()

        resp_body, status = _stock_adjustment_finalize_save(
            adj_no,
            str(staging.get('adj_date') or adj_date),
            str(staging.get('remarks') or remarks),
            all_lines,
            opening_stock=bool(staging.get('opening_stock')),
        )
        _clear_stk_adj_save_staging(save_token)
        if not resp_body.get('success'):
            return json_response_rotate_global(resp_body, status)
        resp_body['lines_saved'] = lines_saved
        resp_body['lines_total'] = total_expected or lines_saved
        resp_body['staged'] = False
        lock_held = False
        return json_response_rotate_global(resp_body, status)
    except Exception as exc:
        _clear_stk_adj_save_staging(str((data or {}).get('save_token') or '').strip() or None)
        return json_response_keep_global_nonce({'success': False, 'error': str(exc)}, 500)
    finally:
        if lock_held:
            _release_session_lock(_STOCK_ADJUSTMENT_SAVE_SESSION_LOCK_UNTIL)


@bp.route('/purchase/stock-adjustment/api/save', methods=['POST'])
def stock_adjustment_save():
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    if not _try_acquire_session_lock(_STOCK_ADJUSTMENT_SAVE_SESSION_LOCK_UNTIL):
        return json_response_rotate_global({
            'success': False,
            'error': 'A stock adjustment save is already in progress for this session. Please wait until it completes.',
            'save_session_locked': True,
        }, 423)
    try:
        if not verify_consume_save_nonce(GLOBAL_SAVE_NONCE_SESSION_KEY, extract_submitted_save_nonce(request)):
            return replay_blocked_response_global()
        data = request.get_json(silent=True) or {}
        adj_no = _adj_no_from_client(data.get('adj_no'))
        adj_date = (data.get('adj_date') or '').strip()
        remarks = (data.get('remarks') or '').strip()
        existing_payload = _get_stock_adjustment_payload(adj_no) if adjno_is_valid(adj_no) else None
        if existing_payload:
            opening_stock = bool((existing_payload.get('header') or {}).get('opening_stock'))
        else:
            opening_stock = get_stk_adj_opening_stock_mode_enabled()
        lines = data.get('lines') or []
        if not adjno_is_valid(adj_no) or not adj_date:
            return json_response_rotate_global({'success': False, 'error': 'Adjustment No and Date are required'}, 400)
        resp_body, status = _stock_adjustment_finalize_save(
            adj_no, adj_date, remarks, lines, opening_stock=opening_stock,
        )
        if not resp_body.get('success'):
            return json_response_rotate_global(resp_body, status)
        return json_response_rotate_global(resp_body, status)
    finally:
        _release_session_lock(_STOCK_ADJUSTMENT_SAVE_SESSION_LOCK_UNTIL)

