@bp.route('/purchase/stock-transfer')
def stock_transfer():
    if not session.get('user'):
        return redirect(url_for('auth.login'))
    _timed = _store_transfer_timing_enabled()
    _t_wall = time.perf_counter()
    _apply_db()
    if _timed:
        _t_after_apply = time.perf_counter()
    _ensure_stock_transfer_dashboard_db()
    if _timed:
        _t_after_schema = time.perf_counter()
    user = session.get('user') or ''
    user_dates = _store_transfer_user_provided_date_args(request.args.get('date_from'), request.args.get('date_to'))
    if user_dates:
        date_from, date_to = _store_transfer_parse_list_dates(request.args.get('date_from'), request.args.get('date_to'))
    else:
        date_from, date_to = (None, None)
    from_store = (request.args.get('from_store') or '').strip().upper()
    to_store = (request.args.get('to_store') or '').strip().upper()
    status_filter = (request.args.get('status') or '').strip().upper()[:1]
    workflow_filter = _resolve_store_transfer_workflow_filter(request.args.get('workflow'), user)
    row_cap = _store_transfer_dash_row_cap()
    all_pick, transit_pick = _tbllocation_transfer_store_options_bundle(True)
    pending_transfer_rows, pending_approve_rows, completed_rows = _build_store_transfer_dashboard_rows(user, workflow_filter=workflow_filter, date_from=date_from, date_to=date_to, dash_split_pending_completed_dates=not user_dates, from_store=from_store or None, to_store=to_store or None, status_filter=status_filter, skip_tbllocation_maintenance=True, list_row_cap=row_cap, transit_approval_options_precalc=transit_pick)
    if _timed:
        _t_after_dash = time.perf_counter()
    if _timed:
        _t_after_all = time.perf_counter()
    transfer_store_options = all_pick
    if _timed:
        _t_after_opts = time.perf_counter()
    out = render_template('purchase/stock_transfer.html', pending_transfer_rows=pending_transfer_rows, pending_approve_rows=pending_approve_rows, completed_rows=completed_rows, transfer_store_options=transfer_store_options, workflow_filter=workflow_filter, bulk_approve_api_url=url_for('purchase.stock_transfer_approve_selected'), filter_values={'date_from': date_from or '' if user_dates else '', 'date_to': date_to or '' if user_dates else '', 'from_store': from_store, 'to_store': to_store, 'status': status_filter, 'workflow': workflow_filter})
    if _timed:
        _t_done = time.perf_counter()
        _log_pg.info('[store_transfer timing] total=%.3fs template=%.3fs store_opts=%.3fs all_tab_inline=%.3fs (All tab deferred to /api/all-rows) dashboard_rows=%.3fs schema_ensure=%.3fs startup=%.3fs row_cap=%s user=%s q=%s', _t_done - _t_wall, _t_done - _t_after_opts, _t_after_opts - _t_after_all, _t_after_all - _t_after_dash, _t_after_dash - _t_after_schema, _t_after_schema - _t_after_apply, _t_after_apply - _t_wall, row_cap, (user or '')[:48], request.query_string.decode('utf-8', errors='replace') if request.query_string else '')
    return out

@bp.route('/purchase/stock-transfer/api/all-rows')
def stock_transfer_api_all_rows():
    """JSON rows for Store Transfer · All tab (same filters as list page; fetched on first tab open)."""
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    user_dates = _store_transfer_user_provided_date_args(request.args.get('date_from'), request.args.get('date_to'))
