    from_store = (request.args.get('from_store') or '').strip().upper()
    to_store = (request.args.get('to_store') or '').strip().upper()
    status_filter = (request.args.get('status') or '').strip().upper()[:1]
    user = session.get('user') or ''
    workflow_filter = _resolve_store_transfer_workflow_filter(request.args.get('workflow'), user)
    row_cap = _store_transfer_dash_row_cap()
    if user_dates:
        date_from, date_to = _store_transfer_parse_list_dates(request.args.get('date_from'), request.args.get('date_to'))
        all_statuses = 'C,T,P,A'
        if status_filter in {'C', 'A'}:
            all_statuses = status_filter
        elif status_filter == 'T':
            all_statuses = 'T,P'
        rows = _get_store_transfer_rows(all_statuses, allowed_stores=None, date_from=date_from, date_to=date_to, from_store=from_store or None, to_store=to_store or None, row_limit=row_cap)
        rows = _filter_store_transfer_rows_by_workflow(rows, workflow_filter, user)
    else:
        sf = status_filter
        if sf == 'C':
            buckets = [_get_store_transfer_rows('C', allowed_stores=None, date_from=None, date_to=None, from_store=from_store or None, to_store=to_store or None, row_limit=row_cap, order_transferno_desc=False)]
            rows = _merge_store_transfer_rows_flat(buckets, row_cap)
        elif sf == 'T':
            buckets = [_get_store_transfer_rows('T,P', allowed_stores=None, date_from=None, date_to=None, from_store=from_store or None, to_store=to_store or None, row_limit=row_cap, order_transferno_desc=False)]
            rows = _merge_store_transfer_rows_flat(buckets, row_cap)
        elif sf == 'A':
            buckets = [_get_store_transfer_rows('A', allowed_stores=None, date_from=today_iso, date_to=today_iso, from_store=from_store or None, to_store=to_store or None, row_limit=row_cap)]
            rows = _merge_store_transfer_rows_flat(buckets, row_cap)
        else:
            buckets = [_get_store_transfer_rows('C,T,P', allowed_stores=None, date_from=None, date_to=None, from_store=from_store or None, to_store=to_store or None, row_limit=row_cap, order_transferno_desc=False), _get_store_transfer_rows('A', allowed_stores=None, date_from=today_iso, date_to=today_iso, from_store=from_store or None, to_store=to_store or None, row_limit=row_cap)]
            rows = _merge_store_transfer_rows_flat(buckets, row_cap)
        rows = _filter_store_transfer_rows_by_workflow(rows, workflow_filter, user)
    payload = [_store_transfer_row_api_dict(r) for r in rows or []]
    return jsonify({'success': True, 'rows': payload})

