def _resolve_store_transfer_workflow_filter(request_arg: Optional[str], user: str) -> str:
    """``all`` | ``transit`` | ``standard`` — default ``transit`` for transit-only users."""
    wf = (request_arg or '').strip().lower()
    if wf in ('all', 'transit', 'standard'):
        return wf
    return 'transit' if get_user_transit_only(user) == 'Y' else 'all'


def _store_transfer_transit_codes(transit_approval_options_precalc: Optional[List[Dict[str, str]]]=None, *, skip_tbllocation_maintenance: bool=False) -> Set[str]:
    transit_src = transit_approval_options_precalc if transit_approval_options_precalc is not None else _get_transfer_approval_store_options(skip_tbllocation_maintenance=skip_tbllocation_maintenance)
    return {str(r.get('code') or '').strip().upper() for r in transit_src if str(r.get('code') or '').strip()}


def _filter_store_transfer_rows_by_workflow(rows: List[Dict[str, Any]], workflow_filter: str, user: str) -> List[Dict[str, Any]]:
    wf = (workflow_filter or 'all').strip().lower()
    if wf == 'all':
        return list(rows or [])
    transit_store_set = _store_transfer_transit_codes()
    setup_rows = _get_store_transfer_approval_rows(user, use_dashboard_cache=True)

    def _is_enabled(row: Dict[str, Any]) -> bool:
        keys = ['can_create', 'can_transfer', 'can_transfer_from', 'can_transfer_to', 'can_approve', 'can_approve_from', 'can_approve_to']
        return any(str(row.get(k) or 'N').strip().upper() == 'Y' for k in keys)

    allowed_stores = {str(r.get('storecode') or '').strip().upper() for r in setup_rows or [] if str(r.get('storecode') or '').strip() and _is_enabled(r)}
    use_transit_scope = wf == 'transit'
    if use_transit_scope and allowed_stores:
        assigned_transit_set = allowed_stores.intersection(transit_store_set)
    else:
        assigned_transit_set = transit_store_set if use_transit_scope else set()

    def _is_transit_linked(row: Dict[str, Any]) -> bool:
        f = str(row.get('fromstore') or '').strip().upper()
        t = str(row.get('tostore') or '').strip().upper()
        return f in transit_store_set or t in transit_store_set

    def _is_to_transit(row: Dict[str, Any]) -> bool:
        return str(row.get('tostore') or '').strip().upper() in transit_store_set

    def _is_in_assigned_transit_scope(row: Dict[str, Any]) -> bool:
        f = str(row.get('fromstore') or '').strip().upper()
        t = str(row.get('tostore') or '').strip().upper()
        return f in assigned_transit_set or t in assigned_transit_set

    def _is_from_assigned_transit_scope(row: Dict[str, Any]) -> bool:
        return str(row.get('fromstore') or '').strip().upper() in assigned_transit_set

    out: List[Dict[str, Any]] = []
    for row in rows or []:
        st = str(row.get('status') or '').strip().upper()
        if wf == 'transit':
            if st == 'C' and _is_from_assigned_transit_scope(row):
                out.append(row)
            elif st in ('T', 'P') and _is_to_transit(row) and _is_in_assigned_transit_scope(row):
                out.append(row)
            elif st == 'A' and _is_to_transit(row) and _is_in_assigned_transit_scope(row):
                out.append(row)
        elif wf == 'standard':
            if st == 'C' and not _is_transit_linked(row):
                out.append(row)
            elif st in ('T', 'P') and not _is_to_transit(row):
                out.append(row)
            elif st == 'A' and not _is_to_transit(row):
                out.append(row)
    return out


def _build_store_transfer_dashboard_rows(user: str, workflow_filter: str='all', ignore_store_permissions: bool=False, date_from: Optional[str]=None, date_to: Optional[str]=None, dash_split_pending_completed_dates: bool=False, from_store: Optional[str]=None, to_store: Optional[str]=None, status_filter: str='', skip_tbllocation_maintenance: bool=False, list_row_cap: Optional[int]=None, transit_approval_options_precalc: Optional[List[Dict[str, str]]]=None, *, transit_view: Optional[bool]=None):
    if transit_view is not None:
        workflow_filter = 'transit' if transit_view else 'standard'
    wf = (workflow_filter or 'all').strip().lower()
    use_transit_scope = wf == 'transit'
    transit_store_set = _store_transfer_transit_codes(transit_approval_options_precalc, skip_tbllocation_maintenance=skip_tbllocation_maintenance)
    transit_codes = sorted(transit_store_set)
    setup_rows = [] if ignore_store_permissions else _get_store_transfer_approval_rows(user, use_dashboard_cache=True)

    def _is_enabled(row: Dict[str, Any]) -> bool:
        keys = ['can_create', 'can_transfer', 'can_transfer_from', 'can_transfer_to', 'can_approve', 'can_approve_from', 'can_approve_to']
        for k in keys:
            if str(row.get(k) or 'N').strip().upper() == 'Y':
                return True
        return False
    allowed_stores = sorted({str(r.get('storecode') or '').strip().upper() for r in setup_rows or [] if str(r.get('storecode') or '').strip() and _is_enabled(r)})
    if use_transit_scope and allowed_stores:
        allowed_stores = sorted(set(allowed_stores).intersection(set(transit_codes)))
    scoped_stores = None if ignore_store_permissions else (allowed_stores if use_transit_scope else None)
    if use_transit_scope and (not ignore_store_permissions) and setup_rows and (not scoped_stores):
        pending_transfer_rows = []
        pending_approve_rows = []
        completed_rows = []
    else:
        try:
            cap_i = int(list_row_cap) if list_row_cap is not None else 0
        except (TypeError, ValueError):
            cap_i = 0
        df_pend: Optional[str] = None
        dt_pend: Optional[str] = None
        df_comp: Optional[str] = None
        dt_comp: Optional[str] = None
        if dash_split_pending_completed_dates:
            today_iso = datetime.now().strftime('%Y-%m-%d')
            df_pend = None
            dt_pend = None
            df_comp = today_iso
            dt_comp = today_iso
        else:
            df_pend = str(date_from)[:10].strip() if date_from else None
            dt_pend = str(date_to)[:10].strip() if date_to else None
            df_comp = df_pend
            dt_comp = dt_pend
        fused: Optional[Tuple[List[Dict[str, Any]], List[Dict[str, Any]], List[Dict[str, Any]]]] = None
        if cap_i > 0 and (not dash_split_pending_completed_dates):
            fused = _get_store_transfer_ctp_buckets_fused(allowed_stores=scoped_stores, date_from=df_pend, date_to=dt_pend, from_store=from_store, to_store=to_store, row_limit=cap_i)
        if fused is not None:
            created_rows, transferred_rows, all_completed_rows = fused
        else:
            created_rows = _get_store_transfer_rows('C', allowed_stores=scoped_stores, date_from=df_pend, date_to=dt_pend, from_store=from_store, to_store=to_store, row_limit=list_row_cap, order_transferno_desc=False)
            transferred_rows = _get_store_transfer_rows('T,P', allowed_stores=scoped_stores, date_from=df_pend, date_to=dt_pend, from_store=from_store, to_store=to_store, row_limit=list_row_cap, order_transferno_desc=False)
            all_completed_rows = _get_store_transfer_rows('A', allowed_stores=scoped_stores, date_from=df_comp, date_to=dt_comp, from_store=from_store, to_store=to_store, row_limit=list_row_cap)

        def _is_transit_linked(row: Dict[str, Any]) -> bool:
            f = str(row.get('fromstore') or '').strip().upper()
            t = str(row.get('tostore') or '').strip().upper()
            return f in transit_store_set or t in transit_store_set

        def _is_to_transit(row: Dict[str, Any]) -> bool:
            t = str(row.get('tostore') or '').strip().upper()
            return t in transit_store_set
        assigned_transit_set = set(scoped_stores or []) if use_transit_scope and scoped_stores else transit_store_set

        def _is_in_assigned_transit_scope(row: Dict[str, Any]) -> bool:
            f = str(row.get('fromstore') or '').strip().upper()
            t = str(row.get('tostore') or '').strip().upper()
            return f in assigned_transit_set or t in assigned_transit_set

        def _is_from_assigned_transit_scope(row: Dict[str, Any]) -> bool:
            f = str(row.get('fromstore') or '').strip().upper()
            return f in assigned_transit_set
        if wf == 'transit':
            pending_transfer_rows = [r for r in created_rows or [] if _is_from_assigned_transit_scope(r)]
            pending_approve_rows = [r for r in transferred_rows or [] if _is_to_transit(r) and _is_in_assigned_transit_scope(r)]
            completed_rows = [r for r in all_completed_rows or [] if _is_to_transit(r) and _is_in_assigned_transit_scope(r)]
        elif wf == 'standard':
            pending_transfer_rows = [r for r in created_rows or [] if not _is_transit_linked(r)]
            pending_approve_rows = [r for r in transferred_rows or [] if not _is_to_transit(r)]
            completed_rows = [r for r in all_completed_rows or [] if not _is_to_transit(r)]
        else:
            pending_transfer_rows = list(created_rows or [])
            pending_approve_rows = list(transferred_rows or [])
            completed_rows = list(all_completed_rows or [])
    sf = str(status_filter or '').strip().upper()[:1]
    if sf == 'C':
        pending_approve_rows = []
        completed_rows = []
    elif sf == 'T':
        pending_transfer_rows = []
        completed_rows = []
    elif sf == 'A':
        pending_transfer_rows = []
        pending_approve_rows = []
    return (pending_transfer_rows, pending_approve_rows, completed_rows)

