@bp.route('/purchase/stock-transfer/api/item-stock')
def stock_transfer_item_stock():
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    item_code = (request.args.get('item_code') or '').strip()
    store = (request.args.get('store') or '').strip().upper()
    if not item_code.isdigit():
        return jsonify({'success': False, 'error': 'Invalid item code'}, 400)
    loc = _resolve_location_code()
    rows = get_item_store_inventory(loc, int(item_code))
    current_qty = 0.0
    if store:
        for r in rows or []:
            rs = str(r.get('store') or r.get('itemlocation') or '').strip().upper()
            if rs == store:
                current_qty = float(r.get('stock') or 0)
                break
    pending_qty = 0.0
    try:
        pending_qty = float(_get_pending_approve_transfer_qty_map(store, [int(item_code)]).get(int(item_code), 0.0))
    except Exception:
        pending_qty = 0.0
    adjusted_qty = current_qty - pending_qty
    if adjusted_qty < 0:
        adjusted_qty = 0.0
    return jsonify({'success': True, 'current_qty': round(adjusted_qty, _STORE_TRANSFER_STOCK_DECIMALS), 'actual_qty': round(current_qty, _STORE_TRANSFER_STOCK_DECIMALS), 'pending_qty': round(pending_qty, _STORE_TRANSFER_STOCK_DECIMALS), 'store': store, 'stores': rows})

