@bp.route('/purchase/stock-transfer/api/lots')
def stock_transfer_lots():
    """FEFO lot list for batch-tracked item (optional pick on transfer line)."""
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    item_raw = (request.args.get('item_code') or '').strip()
    if not item_raw.isdigit():
        return jsonify({'success': False, 'error': 'Invalid item code'}, 400)
    ic = int(item_raw)
    loc_code = _resolve_location_code()
    if not is_location_batch_tracking_enabled(loc_code):
        return jsonify({'success': True, 'lots': []})
    if not is_item_batch_tracked(ic, loc_code):
        return jsonify({'success': True, 'lots': []})
    rows = get_item_lot_stock_list(int(loc_code), itemcode=ic) or []
    lots = []
    for r in rows:
        lid = r.get('lot_id')
        if lid is None:
            continue
        exp = r.get('expiry_date')
        exp_s = exp.strftime('%Y-%m-%d') if hasattr(exp, 'strftime') else str(exp or '')[:10]
        mfg = r.get('mfg_date')
        mfg_s = mfg.strftime('%Y-%m-%d') if hasattr(mfg, 'strftime') else str(mfg or '')[:10]
        lots.append({
            'lot_id': int(lid),
            'batch_no': str(r.get('batch_no') or '').strip(),
            'qty': round(float(r.get('qty') or 0), _STORE_TRANSFER_STOCK_DECIMALS),
            'expiry_date': exp_s,
            'mfg_date': mfg_s,
            'lot_blocked': str(r.get('lot_blocked') or 'N').strip().upper() == 'Y',
        })
    return jsonify({'success': True, 'lots': lots})


