@bp.route('/purchase/stock-transfer/api/items')
def stock_transfer_items():
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    from_store = (request.args.get('from_store') or '').strip()
    search = (request.args.get('search') or '').strip()
    try:
        limit = int(request.args.get('limit') or 250)
    except Exception:
        limit = 250
    bulk = str(request.args.get('bulk') or '').strip().lower() in ('1', 'true', 'yes', 'y')
    if bulk:
        limit = min(max(limit, 1), 50)
    else:
        limit = min(max(limit, 50), 500)
    if not from_store:
        return jsonify({'success': True, 'items': []})
    exact_ic_raw = (request.args.get('exact_item_code') or '').strip()
    exact_bc_raw = (request.args.get('exact_barcode') or '').strip()
    exact_item_code = int(exact_ic_raw) if exact_ic_raw.isdigit() else None
    exact_barcode = exact_bc_raw if exact_bc_raw else None
    if exact_item_code is not None and exact_item_code > 0:
        rows = _get_transfer_items_for_store(from_store=from_store, search=None, limit=min(limit, 50), exact_item_code=exact_item_code)
    elif exact_barcode:
        rows = _get_transfer_items_for_store(from_store=from_store, search=None, limit=min(limit, 50), exact_barcode=exact_barcode)
    elif search:
        resolved_ic = None
        if len(search.split()) == 1:
            resolved_ic = _resolve_transfer_item_code_from_barcode(search.strip())
        if resolved_ic:
            rows = _get_transfer_items_for_store(
                from_store=from_store, search=None, limit=min(limit, 50), exact_item_code=resolved_ic,
            )
        else:
            rows = _get_transfer_items_for_store(from_store=from_store, search=search or None, limit=limit)
    else:
        rows = _get_transfer_items_for_store(from_store=from_store, search=search or None, limit=limit)
    return jsonify({'success': True, 'items': rows})

@bp.route('/purchase/stock-transfer/api/save', methods=['POST'])
def stock_transfer_save():
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    data = request.get_json(silent=True) or {}
    transfer_no = parse_transferno_from_request(data.get('transfer_no'))
    transfer_date = (data.get('transfer_date') or '').strip()
    from_store = (data.get('from_store') or '').strip()
    to_store = (data.get('to_store') or '').strip()
    remarks = (data.get('remarks') or '').strip()
    lines = data.get('lines') or []
    update_existing = bool(data.get('update_existing') or data.get('is_edit'))
    if not transfer_date:
        return jsonify({'success': False, 'error': 'Transfer date is required'}, 400)
    if not transferno_is_valid(transfer_no):
        transfer_no = _store_transfer_next_no()
    if not update_existing:
        _max_no_attempts = 500
        _n = 0
        while transferno_is_valid(transfer_no) and _store_transfer_header_exists(transfer_no) and (_n < _max_no_attempts):
            transfer_no = _store_transfer_next_no()
            _n += 1
        if _n >= _max_no_attempts and _store_transfer_header_exists(transfer_no):
            return jsonify({'success': False, 'error': 'Could not allocate a free transfer number. Try again.'}, 400)
    try:
        tdate = datetime.strptime(transfer_date[:10], '%Y-%m-%d').date()
    except Exception:
        return jsonify({'success': False, 'error': 'Invalid transfer date'}, 400)
    if tdate < datetime.now().date():
        return jsonify({'success': False, 'error': 'Previous date is not allowed'}, 400)
    if not lines:
        return jsonify({'success': False, 'error': 'Add at least one line.'}, 400)
    if not from_store or not to_store:
        return jsonify({'success': False, 'error': 'From Store and To Store are required.'}, 400)
    submitted = extract_submitted_save_nonce(request)
    if not verify_consume_save_nonce(GLOBAL_SAVE_NONCE_SESSION_KEY, submitted):
        return replay_blocked_response_global()
    err = _save_store_transfer_request(transfer_no, transfer_date, from_store, to_store, remarks, lines)
    if err:
        return json_response_rotate_global({'success': False, 'error': err}, 400)
    user = session.get('user') or ''
    list_url = url_for('purchase.stock_transfer', workflow=_resolve_store_transfer_workflow_filter(None, user))
    return json_response_rotate_global({'success': True, 'transfer_no': transfer_no, 'list_url': list_url, 'pdf_url': url_for('purchase.stock_transfer_pdf', transfer_no=transfer_no, copy=0)}, 200)

@bp.route('/purchase/stock-transfer/api/transfer/<path:transfer_no>', methods=['POST'])
def stock_transfer_transfer(transfer_no):
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    transfer_no = parse_transferno_from_request(transfer_no)
    err = _post_store_transfer_to_transit(transfer_no)
    if err:
        return jsonify({'success': False, 'error': err}, 400)
    user = session.get('user') or ''
    list_url = url_for('purchase.stock_transfer', workflow=_resolve_store_transfer_workflow_filter(None, user))
    return jsonify({'success': True, 'transfer_no': transfer_no, 'list_url': list_url})

@bp.route('/purchase/stock-transfer/api/approve/<path:transfer_no>', methods=['POST'])
def stock_transfer_approve(transfer_no):
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    transfer_no = parse_transferno_from_request(transfer_no)
    submitted = extract_submitted_save_nonce(request)
    if not verify_consume_save_nonce(GLOBAL_SAVE_NONCE_SESSION_KEY, submitted):
        return replay_blocked_response_global()
    if not _try_acquire_session_lock(_STOCK_TRANSFER_APPROVE_SESSION_LOCK_UNTIL):
        return json_response_rotate_global({
            'success': False,
            'error': 'A store transfer approval is already in progress for this session. Please wait until it completes.',
            'save_session_locked': True,
        }, 423)
    try:
        err = _approve_store_transfer(transfer_no)
        if err:
            return json_response_rotate_global({'success': False, 'error': err}, 400)
        user = session.get('user') or ''
        list_url = url_for('purchase.stock_transfer', workflow=_resolve_store_transfer_workflow_filter(None, user))
        return json_response_rotate_global({'success': True, 'transfer_no': transfer_no, 'list_url': list_url}, 200)
    finally:
        _release_session_lock(_STOCK_TRANSFER_APPROVE_SESSION_LOCK_UNTIL)

@bp.route('/purchase/stock-transfer/api/approve-selected', methods=['POST'])
def stock_transfer_approve_selected():
    """Bulk approve transferred store transfer requests in one DB transaction with session lock."""
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    if not _try_acquire_session_lock(_STOCK_TRANSFER_APPROVE_SESSION_LOCK_UNTIL):
        return jsonify({
            'success': False,
            'error': 'A store transfer approval is already in progress for this session. Please wait until it completes.',
            'save_session_locked': True,
        }, 423)
    try:
        _apply_db()
        data = request.get_json(silent=True) or {}
        raw_nos = data.get('transfer_nos') or []
        transfer_nos: List[int] = []
        for x in raw_nos:
            try:
                n = int(x)
            except (TypeError, ValueError):
                continue
            if n > 0 and n not in transfer_nos:
                transfer_nos.append(n)
        if not transfer_nos:
            return jsonify({'success': False, 'error': 'Select at least one transfer'}, 400)
        with _get_connection() as conn:
            _ensure_store_transfer_tables(conn)
            for tno in transfer_nos:
                try:
                    err = _approve_store_transfer(tno, conn=conn, commit=False)
                except Exception as ex:
                    print(f'[ERROR stock_transfer_approve_selected] transfer_no={tno}: {ex}')
                    traceback.print_exc()
                    conn.rollback()
                    return jsonify({'success': False, 'error': str(ex) or repr(ex), 'transfer_no': tno, 'approved_count': 0}, 500)
                if err:
                    conn.rollback()
                    return jsonify({'success': False, 'error': err, 'transfer_no': tno, 'approved_count': 0}, 400)
            conn.commit()
        user = session.get('user') or ''
        list_url = url_for('purchase.stock_transfer', workflow=_resolve_store_transfer_workflow_filter(None, user))
        msg = f'Approved {len(transfer_nos)} transfer(s).'
        return jsonify({'success': True, 'message': msg, 'approved_count': len(transfer_nos), 'approved_transfers': transfer_nos, 'failed_count': 0, 'failed': [], 'list_url': list_url})
    except Exception as ex:
        print(f'[ERROR stock_transfer_approve_selected] {ex}')
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(ex) or 'Server error', 'approved_count': 0}, 500)
    finally:
        _release_session_lock(_STOCK_TRANSFER_APPROVE_SESSION_LOCK_UNTIL)

