def _itemjournal_hdr_list_filters(
    *,
    search: Optional[str] = None,
    source_doc_filter: Optional[str] = None,
    transtype_filter: Optional[str] = None,
    date_from: Optional[str] = None,
    date_to: Optional[str] = None,
    prefix: str = 'h',
) -> Tuple[str, Dict[str, Any]]:
    where_parts = ['1=1']
    params: Dict[str, Any] = {'loc': _resolve_location_code()}
    where_parts.append(f'{prefix}.LOCATIONCODE = :loc')
    sd_f = str(source_doc_filter or '').strip()
    if sd_f:
        params['sd_f'] = sd_f.upper()
        where_parts.append(f"UPPER(TRIM(NVL({prefix}.SOURCE_DOC, ''))) = :sd_f")
    tt_f = str(transtype_filter or '').strip()
    if tt_f:
        params['tt_f'] = tt_f
        where_parts.append(f"NVL(TRIM(TO_CHAR({prefix}.TRANSTYPE)), '(none)') = :tt_f")
    if search and str(search).strip():
        params['s'] = f'%{str(search).strip()}%'
        where_parts.append(
            f"(UPPER(NVL({prefix}.SOURCE_DOC, '')) LIKE UPPER(:s)"
            f" OR TO_CHAR({prefix}.SOURCE_NO) LIKE :s"
            f" OR UPPER(NVL({prefix}.TRANSTYPE, '')) LIKE UPPER(:s)"
            f" OR UPPER(NVL({prefix}.CREATED_BY, '')) LIKE UPPER(:s))"
        )
    if date_from:
        where_parts.append(f"TRUNC({prefix}.POSTED_DATE) >= TO_DATE(:date_from, 'YYYY-MM-DD')")
        params['date_from'] = date_from[:10]
    if date_to:
        where_parts.append(f"TRUNC({prefix}.POSTED_DATE) <= TO_DATE(:date_to, 'YYYY-MM-DD')")
        params['date_to'] = date_to[:10]
    return ' AND '.join(where_parts), params


def _get_itemjournal_hdr_rows_from_journal(
    limit: int = 500,
    search: Optional[str] = None,
    source_doc_filter: Optional[str] = None,
    transtype_filter: Optional[str] = None,
    date_from: Optional[str] = None,
    date_to: Optional[str] = None,
) -> List[Dict[str, Any]]:
    tbl = _detect_table(['ITEMJOURNAL', 'itemjournal', 'ITEMJOURNEL', 'itemjournel'])
    if not tbl:
        return []
    loc_col = _detect_column(tbl, ['LOCATIONCODE', 'locationcode'])
    reset_col = _detect_column(tbl, ['RESETNO', 'resetno'])
    receipt_col = _detect_column(tbl, ['RECEIPTNO', 'receiptno'])
    source_doc_col = _detect_column(tbl, ['SOURCE_DOC', 'source_doc'])
    source_no_col = _detect_column(tbl, ['SOURCE_NO', 'source_no'])
    transtype_col = _detect_column(tbl, ['TRANSTYPE', 'transtype'])
    created_col = _detect_column(tbl, ['CREATEDDATE', 'createddate'])
    qty_col = _detect_column(tbl, ['QTY', 'quantity'])
    amount_col = _detect_column(tbl, ['AMOUNT', 'amount'])
    if not source_doc_col:
        return []
    where_parts = ['1=1']
    params: Dict[str, Any] = {'loc': _resolve_location_code()}
    if loc_col:
        where_parts.append(f'j.{loc_col} = :loc')
    where_parts.append(f"TRIM(NVL(j.{source_doc_col}, '')) IS NOT NULL")
    sd_f = str(source_doc_filter or '').strip()
    if sd_f:
        params['sd_f'] = sd_f.upper()
        where_parts.append(f"UPPER(TRIM(j.{source_doc_col})) = :sd_f")
    tt_f = str(transtype_filter or '').strip()
    if tt_f and transtype_col:
        params['tt_f'] = tt_f
        where_parts.append(f"NVL(TRIM(TO_CHAR(j.{transtype_col})), '(none)') = :tt_f")
    if search and str(search).strip():
        params['s'] = f'%{str(search).strip()}%'
        bits = [f"UPPER(NVL(j.{source_doc_col}, '')) LIKE UPPER(:s)", f'TO_CHAR(j.{source_no_col}) LIKE :s']
        if transtype_col:
            bits.append(f"UPPER(NVL(j.{transtype_col}, '')) LIKE UPPER(:s)")
        where_parts.append('(' + ' OR '.join(bits) + ')')
    if created_col and date_from:
        where_parts.append(f"TRUNC(j.{created_col}) >= TO_DATE(:date_from, 'YYYY-MM-DD')")
        params['date_from'] = date_from[:10]
    if created_col and date_to:
        where_parts.append(f"TRUNC(j.{created_col}) <= TO_DATE(:date_to, 'YYYY-MM-DD')")
        params['date_to'] = date_to[:10]
    where_sql = ' AND '.join(where_parts)
    group_bits = [
        f'j.{loc_col}' if loc_col else 'NULL',
        f'NVL(j.{reset_col}, 1)' if reset_col else '1',
        f'j.{source_doc_col}',
        f'j.{source_no_col}' if source_no_col else 'NULL',
    ]
    group_sql = ', '.join(group_bits)
    sum_qty = f'NVL(SUM(j.{qty_col}), 0)' if qty_col else '0'
    sum_amt = f'NVL(SUM(j.{amount_col}), 0)' if amount_col else '0'
    max_tt = f'MAX(j.{transtype_col})' if transtype_col else 'NULL'
    max_rc = f'MAX(j.{receipt_col})' if receipt_col else '0'
    max_dt = f"TO_CHAR(MAX(j.{created_col}), 'YYYY-MM-DD HH24:MI:SS')" if created_col else 'NULL'
    order_col = created_col or source_doc_col
    q = f"""
        SELECT NULL AS journal_hdr_id,
               {group_bits[0]} AS locationcode,
               {group_bits[1]} AS resetno,
               {max_rc} AS receiptno,
               j.{source_doc_col} AS source_doc,
               {f'j.{source_no_col}' if source_no_col else 'NULL'} AS source_no,
               {max_tt} AS transtype,
               COUNT(*) AS line_count,
               NULL AS created_by,
               {max_dt} AS posted_date,
               {max_dt} AS modified_date,
               {sum_qty} AS total_qty,
               {sum_amt} AS total_amount
        FROM {tbl} j
        WHERE {where_sql}
        GROUP BY {group_sql}
        ORDER BY MAX(j.{order_col}) DESC
    """
    try:
        _, rows = _fetch_rows(q, params)
        out: List[Dict[str, Any]] = []
        for r in rows or []:
            row = dict(r)
            row['line_count'] = int(row.get('line_count') or 0)
            row['total_qty'] = round(float(row.get('total_qty') or 0), 4)
            row['total_amount'] = round(float(row.get('total_amount') or 0), 4)
            out.append(row)
        return out[:max(1, min(int(limit or 500), 2000))]
    except Exception as e:
        print(f'[_get_itemjournal_hdr_rows_from_journal] {e}')
        return []


def _get_itemjournal_hdr_rows(
    limit: int = 500,
    search: Optional[str] = None,
    source_doc_filter: Optional[str] = None,
    transtype_filter: Optional[str] = None,
    date_from: Optional[str] = None,
    date_to: Optional[str] = None,
) -> List[Dict[str, Any]]:
    ensure_itemjournal_hdr_table()
    tbl = _detect_table([ITEMJOURNAL_HDR_TABLE, 'itemjournal_hdr'])
    ij_tbl = _detect_table(['ITEMJOURNAL', 'itemjournal', 'ITEMJOURNEL', 'itemjournel'])
    qty_col = _detect_column(ij_tbl, ['QTY', 'quantity']) if ij_tbl else None
    amount_col = _detect_column(ij_tbl, ['AMOUNT', 'amount']) if ij_tbl else None
    if tbl and _table_exists(tbl):
        where_sql, params = _itemjournal_hdr_list_filters(
            search=search, source_doc_filter=source_doc_filter, transtype_filter=transtype_filter,
            date_from=date_from, date_to=date_to, prefix='h',
        )
        qty_sub = amt_sub = '0'
        if ij_tbl and qty_col and amount_col:
            sd_match = (
                "UPPER(TRIM(NVL(j.SOURCE_DOC, ''))) = UPPER(TRIM(NVL(h.SOURCE_DOC, '')))"
                " AND TRIM(NVL(TO_CHAR(j.SOURCE_NO), '@')) = TRIM(NVL(TO_CHAR(h.SOURCE_NO), '@'))"
            )
            qty_sub = f"(SELECT NVL(SUM(j.{qty_col}), 0) FROM {ij_tbl} j WHERE j.LOCATIONCODE = h.LOCATIONCODE AND {sd_match})"
            amt_sub = f"(SELECT NVL(SUM(j.{amount_col}), 0) FROM {ij_tbl} j WHERE j.LOCATIONCODE = h.LOCATIONCODE AND {sd_match})"
        q = f"""
            SELECT h.JOURNAL_HDR_ID AS journal_hdr_id,
                   h.LOCATIONCODE AS locationcode,
                   h.RESETNO AS resetno,
                   h.RECEIPTNO AS receiptno,
                   h.SOURCE_DOC AS source_doc,
                   h.SOURCE_NO AS source_no,
                   h.TRANSTYPE AS transtype,
                   h.LINE_COUNT AS line_count,
                   h.CREATED_BY AS created_by,
                   TO_CHAR(h.POSTED_DATE, 'YYYY-MM-DD HH24:MI:SS') AS posted_date,
                   TO_CHAR(h.MODIFIED_DATE, 'YYYY-MM-DD HH24:MI:SS') AS modified_date,
                   {qty_sub} AS total_qty,
                   {amt_sub} AS total_amount
            FROM {tbl} h
            WHERE {where_sql}
            ORDER BY h.POSTED_DATE DESC
        """
        try:
            _, rows = _fetch_rows(q, params)
            if rows:
                out: List[Dict[str, Any]] = []
                for r in rows or []:
                    row = dict(r)
                    row['line_count'] = int(row.get('line_count') or 0)
                    row['total_qty'] = round(float(row.get('total_qty') or 0), 4)
                    row['total_amount'] = round(float(row.get('total_amount') or 0), 4)
                    out.append(row)
                return out[:max(1, min(int(limit or 500), 2000))]
        except Exception as e:
            print(f'[_get_itemjournal_hdr_rows] {e}')
    return _get_itemjournal_hdr_rows_from_journal(
        limit=limit, search=search, source_doc_filter=source_doc_filter,
        transtype_filter=transtype_filter, date_from=date_from, date_to=date_to,
    )


def _get_itemjournal_hdr_source_doc_summary() -> List[Dict[str, Any]]:
    rows = _get_itemjournal_hdr_rows(limit=5000)
    counts: Dict[str, int] = {}
    for r in rows:
        sd = str(r.get('source_doc') or '').strip() or '(none)'
        counts[sd] = counts.get(sd, 0) + 1
    return [{'source_doc': k, 'doc_count': v} for k, v in sorted(counts.items(), key=lambda x: x[0])]


def _get_itemjournal_hdr_list_totals(
    search: Optional[str] = None,
    source_doc_filter: Optional[str] = None,
    transtype_filter: Optional[str] = None,
    date_from: Optional[str] = None,
    date_to: Optional[str] = None,
) -> Dict[str, Any]:
    rows = _get_itemjournal_hdr_rows(
        limit=5000, search=search, source_doc_filter=source_doc_filter,
        transtype_filter=transtype_filter, date_from=date_from, date_to=date_to,
    )
    return {
        'doc_count': len(rows),
        'line_count': sum(int(r.get('line_count') or 0) for r in rows),
        'total_qty': round(sum(float(r.get('total_qty') or 0) for r in rows), 4),
        'total_amount': round(sum(float(r.get('total_amount') or 0) for r in rows), 4),
    }


