def _batch_lot_inquiry_enrich_rows(rows: Optional[List[Dict[str, Any]]]) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    """
    Annotate ITEM_LOT rows with expiry_status (ok | soon | expired | none) for UI.
    Summary: totals and counts for dashboard chips.
    """
    today = date.today()
    horizon = today + timedelta(days=30)
    total_qty = 0.0
    n_expired = 0
    n_soon = 0
    out: List[Dict[str, Any]] = []
    for raw in rows or []:
        r = dict(raw)
        try:
            total_qty += float(r.get('qty') or 0)
        except (TypeError, ValueError):
            pass
        dd: Optional[date] = None
        ed = r.get('expiry_date')
        if ed is not None:
            if isinstance(ed, datetime):
                dd = ed.date()
            elif isinstance(ed, date):
                dd = ed
            else:
                try:
                    dd = datetime.strptime(str(ed)[:10], '%Y-%m-%d').date()
                except Exception:
                    s = str(ed).strip()[:32]
                    for fmt in ('%d-%b-%Y', '%d-%b-%y', '%d/%m/%Y'):
                        try:
                            dd = datetime.strptime(s, fmt).date()
                            break
                        except Exception:
                            pass
        if dd is not None:
            r['_exp_iso'] = dd.isoformat()
            if dd < today:
                r['expiry_status'] = 'expired'
                n_expired += 1
            elif dd <= horizon:
                r['expiry_status'] = 'soon'
                n_soon += 1
            else:
                r['expiry_status'] = 'ok'
        else:
            r['expiry_status'] = 'none'
            r['_exp_iso'] = ''
        out.append(r)
    summary = {'lot_count': len(out), 'total_qty': round(total_qty, 4), 'expired_count': n_expired, 'soon_count': n_soon}
    return (out, summary)

@bp.route('/purchase/batch-lot')
def batch_lot_inquiry():
    if not session.get('user'):
        return redirect(url_for('auth.login'))
    _apply_db()
    loc = _resolve_location_code()
    try:
        ic = int(request.args.get('itemcode') or 0)
    except (TypeError, ValueError):
        ic = 0
    exp_days = request.args.get('expiring_days')
    try:
        ed = int(exp_days) if exp_days is not None and str(exp_days).strip() != '' else None
    except (TypeError, ValueError):
        ed = None
    wk_param = (request.args.get('wh_loc') or '').strip()
    sites = get_warehouse_location_sites() or []
    wk = ''
    if wk_param:
        for s in sites:
            if str(s.get('key', '')).strip() == wk_param:
                wk = wk_param
                break
    if not wk and sites:
        wk = str(sites[0].get('key', '')).strip()
    bin_rows: List[Dict[str, Any]] = []
    if wk:
        bin_rows = get_warehouse_storage_rows(wk, 'BIN') or []
    wh_site_label = ''
    if wk:
        for s in sites:
            sk = str(s.get('key', '') or '').strip()
            if sk == wk:
                nm = str(s.get('name') or '').strip()
                wh_site_label = f'{nm} — {wk}' if nm else wk
                break
        if not wh_site_label:
            wh_site_label = wk
    raw_lots = get_item_lot_stock_list(loc, itemcode=ic if ic > 0 else None, expiring_within_days=ed)
    lots, bl_summary = _batch_lot_inquiry_enrich_rows(raw_lots)
    return render_template('purchase/batch_lot_inquiry.html', lots=lots, bl_summary=bl_summary, session_location=loc, filter_itemcode=ic if ic > 0 else '', filter_expiring_days=ed if ed is not None else '', warehouse_sites=sites, default_wh_loc_key=wk, wh_site_label=wh_site_label, bin_rows=bin_rows)

