    date_to = (request.args.get('date_to') or '').strip()[:10] or None
    skip_count = (request.args.get('skip_count') or '').strip().lower() in ('1', 'true', 'yes')
    t_api = time.perf_counter()
    try:
        rows, total_count = _get_lpo_list_page(
            page=page,
            per_page=per_page,
            tab=tab,
            search=search,
            date_from=date_from,
            date_to=date_to,
            skip_count=skip_count,
        )
    except Exception as e:
        print(f'[api_lpo_list] {e}')
        return jsonify({'success': False, 'error': str(e)}, 500)
    total_pages = (total_count + per_page - 1) // per_page if total_count > 0 else 1
    elapsed_api = time.perf_counter() - t_api
    if elapsed_api >= 0.5:
        print(f'[api_lpo_list] {elapsed_api:.2f}s tab={tab} page={page} rows={len(rows or [])} total={total_count}')
    return jsonify({
        'success': True,
        'orders': rows,
        'total_count': total_count,
        'page': page,
        'items_per_page': per_page,
        'total_pages': total_pages,
        'count_approximate': bool(skip_count and total_count > 0),
    })

