@bp.route('/purchase/order/api/cart')
def api_lpo_cart_load():
    """Load temp LPO cart (TEMPLPOHDR/TEMPLPODTL) with FLAG=0. Returns templpono, header, lines."""
    if not session.get('user'):
        return jsonify({'error': 'Not authenticated'}, 401)
    _apply_db()
    loc = _resolve_location_code()
    templpono, header, lines = load_templpo_cart(loc)
    out_lines = []
    for ln in lines or []:
        out_lines.append({'itemcode': ln.get('itemcode'), 'barcode': ln.get('manufacturerid') or ln.get('barcode') or '', 'itemname': '', 'quantity': float(ln.get('quantity') or 0), 'rate': float(ln.get('rate') or 0), 'bonus': float(ln.get('bonus') or 0), 'discount': float(ln.get('discount') or 0), 'foc': ln.get('foc') in (1, '1', 'Y', 'y'), 'othercharge': float(ln.get('othercharge') or 0), 'amount': float(ln.get('amount') or 0), 'uom': (ln.get('unitofmeasurement') or 'NOS').strip() or 'NOS'})
    if header:
        header = dict(header)
        if header.get('lpodate'):
            d = header['lpodate']
            if hasattr(d, 'strftime'):
                header['lpodate'] = d.strftime('%Y-%m-%d')
