@bp.route('/purchase/order/api/save', methods=['POST'])
def api_lpo_save():
    if not session.get('user'):
        return jsonify({'error': 'Not authenticated'}, 401)
    _apply_db()
    ensure_lpono_varchar_columns()
    ensure_purchase_approval_docno_varchar()
    if not verify_consume_save_nonce(GLOBAL_SAVE_NONCE_SESSION_KEY, extract_submitted_save_nonce(request)):
        return replay_blocked_response_global()
    data = request.get_json(silent=True) or {}
    lpo_no = parse_lpono_from_request(data.get('lpono'))
    remarks = (data.get('remarks') or '').strip()
    templpono = int(data.get('templpono') or 0)
    approval_save_as = (data.get('approval_save_as') or 'draft').strip().lower()
    if approval_save_as not in ('draft', 'approved'):
        approval_save_as = 'draft'
    approval_only = bool(data.get('approval_only'))
    if lpono_is_valid(lpo_no) and _get_po_approval_status(lpo_no) == 'CANCELLED':
        return json_response_rotate_global({'success': False, 'error': 'This purchase order is canceled and cannot be changed.'}, 400)
    if approval_only:
        if not lpono_is_valid(lpo_no):
            return json_response_rotate_global({'success': False, 'error': 'LPO No is required'}, 400)
        hdr = _get_lpo_header(lpo_no)
        if not hdr:
            return json_response_rotate_global({'success': False, 'error': 'PO not found. Open this order from the list and try again.'}, 400)
        if approval_save_as == 'approved':
            _set_po_approval_status(lpo_no, 'APPROVED', 'SAVE_APPROVED', remarks or 'Saved as approved')
            approval_out = 'APPROVED'
        else:
            _set_po_approval_status(lpo_no, 'DRAFT', 'SAVE_DRAFT', remarks or 'Saved as draft')
            approval_out = 'DRAFT'
        if templpono:
            set_templpo_saved(_resolve_location_code(), templpono, lpono=lpo_no)
        return json_response_rotate_global({'success': True, 'next_lpono': _lpo_next_no(), 'pdf_url': url_for('purchase.api_lpo_pdf', lpo_no=lpo_no), 'approval_status': approval_out, 'approval_only': True})
    lpo_date = (data.get('lpodate') or '')[:10]
    open_date, txn_err = _enforce_purchase_open_date(lpo_date, 'purchase')
    if txn_err:
        return json_response_rotate_global(
            {'success': False, 'error': txn_err, 'transaction_date_blocked': True},
            400,
        )
    lpo_date = open_date or lpo_date
    supplier_code = int(data.get('suppliercode') or 0)
    discount = float(data.get('discount') or 0)
    other_charge = float(data.get('othercharge') or 0)
    wh_raw = data.get('warehouse_id')
    warehouse_id: Optional[int] = None
    if wh_raw not in (None, ''):
        try:
            warehouse_id = int(wh_raw)
            if warehouse_id <= 0:
                warehouse_id = None
        except (TypeError, ValueError):
            warehouse_id = None
    lines = data.get('lines') or []
    if not lpono_is_valid(lpo_no) or not lpo_date or (not supplier_code):
        return json_response_rotate_global({'success': False, 'error': 'LPO No, Date and Supplier are required'}, 400)
    requested_no = lpo_no
    lpo_no, lpo_reassigned = _resolve_lpo_no_for_save(requested_no)
    lpo_existed = not lpo_reassigned and lpono_is_valid(requested_no) and _get_lpo_header(requested_no) is not None
    before_snap = _audit_lpo_snapshot(_get_lpo_header(requested_no), _get_lpo_details(requested_no)) if lpo_existed else None
    err: Optional[str] = None
    for _dup_try in range(8):
        try:
            err = _save_lpo(lpo_no, lpo_date, supplier_code, discount, other_charge, remarks, lines, warehouse_id=warehouse_id)
        except Exception as e:
            msg = str(e or '')
            if 'ORA-00001' in msg and 'PK_LPOHDR' in msg.upper():
                err = msg
            else:
                return json_response_rotate_global({'success': False, 'error': msg or 'Save failed'}, 400)
        if not err:
            break
        if not _is_duplicate_doc_key_error(err):
            break
        retry_no = _allocate_next_free_lpo_no(lpo_no)
        if lpono_equal(retry_no, lpo_no):
            try:
                retry_no = coerce_lpono(billno_numeric_part(lpo_no) + 1)
            except Exception:
                pass
        if lpono_equal(retry_no, lpo_no):
            break
        lpo_no = retry_no
        lpo_reassigned = True
    if err:
        dup_key = _is_duplicate_doc_key_error(err)
        body: Dict[str, Any] = {'success': False, 'error': err}
        if dup_key:
            body['duplicate_lpo'] = True
            body['duplicate_doc_key'] = True
            body['next_lpono'] = _allocate_next_free_lpo_no(lpo_no)
            body['suggested_lpono'] = body['next_lpono']
        return json_response_rotate_global(body, 409 if dup_key else 400)
    if lpo_existed:
        after_snap = _audit_lpo_snapshot_from_save(lpo_date, supplier_code, discount, other_charge, remarks, lines)
        _log_purchase_change(
            'LPO', lpo_no, 'EDIT',
            remarks or 'Purchase order updated',
            before=before_snap,
            after=after_snap,
        )
    if approval_save_as == 'approved':
        _set_po_approval_status(lpo_no, 'APPROVED', 'SAVE_APPROVED', remarks or 'Saved as approved')
        approval_out = 'APPROVED'
    else:
        _set_po_approval_status(lpo_no, 'DRAFT', 'SAVE_DRAFT', remarks or 'Saved as draft')
        approval_out = 'DRAFT'
    if templpono:
        set_templpo_saved(_resolve_location_code(), templpono, lpono=lpo_no)
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                from addons.document_numbering.document_numbering_db import advance_document_series_after_save_cur
                advance_document_series_after_save_cur(
                    cur, DOC_TYPE_LPO, lpo_no,
                    location_code=_resolve_location_code(),
                    reset_no=RESET_NO,
                    user=str(session.get('user') or 'web'),
                )
            conn.commit()
    except Exception:
        pass
    msg = 'Saved' + (f' ({approval_out})' if approval_out else '')
    if lpo_reassigned:
        msg = f'LPO number {requested_no} was already in use. Saved as LPO {lpo_no}.' + (f' ({approval_out})' if approval_out else '')
    return json_response_rotate_global({
        'success': True,
        'lpono': lpo_no,
        'requested_lpono': requested_no,
        'lpono_reassigned': lpo_reassigned,
        'next_lpono': _lpo_next_no(),
        'pdf_url': url_for('purchase.api_lpo_pdf', lpo_no=lpo_no),
        'approval_status': approval_out,
        'message': msg,
    })

@bp.route('/purchase/order/api/cancel', methods=['POST'])
def api_lpo_cancel():
    if not session.get('user'):
        return jsonify({'error': 'Not authenticated'}, 401)
    _apply_db()
    if not verify_consume_save_nonce(GLOBAL_SAVE_NONCE_SESSION_KEY, extract_submitted_save_nonce(request)):
        return replay_blocked_response_global()
    data = request.get_json(silent=True) or {}
    lpo_no = parse_lpono_from_request(data.get('lpono'))
    remarks = (data.get('remarks') or '').strip()[:500]
    if not lpono_is_valid(lpo_no):
        return json_response_rotate_global({'success': False, 'error': 'LPO No is required'}, 400)
    if not _get_lpo_header(lpo_no):
        return json_response_rotate_global({'success': False, 'error': 'PO not found.'}, 400)
    if _get_po_approval_status(lpo_no) == 'CANCELLED':
        return json_response_rotate_global({'success': False, 'error': 'PO is already canceled.'}, 400)
    if _po_has_receipt_for_lpo(lpo_no):
        return json_response_rotate_global({'success': False, 'error': 'Cannot cancel: a goods receipt exists for this PO.'}, 400)
    before_snap = _audit_lpo_snapshot(_get_lpo_header(lpo_no), _get_lpo_details(lpo_no))
    _set_po_approval_status(lpo_no, 'CANCELLED', 'CANCEL', remarks or 'Purchase order canceled')
    _log_purchase_change('LPO', lpo_no, 'CANCEL', remarks or 'Purchase order canceled', before=before_snap)
    return json_response_rotate_global({'success': True, 'approval_status': 'CANCELLED'})

