@bp.route('/purchase/order/api/submit', methods=['POST'])
def api_lpo_submit():
    if not session.get('user'):
        return jsonify({'error': 'Not authenticated'}, 401)
    _apply_db()
    data = request.get_json(silent=True) or {}
    lpo_no = parse_lpono_from_request(data.get('lpono'))
    remarks = (data.get('remarks') or '').strip()
    if not lpono_is_valid(lpo_no):
        return jsonify({'success': False, 'error': 'LPO No is required'}, 400)
    current_status = _get_po_approval_status(lpo_no)
    if current_status == 'APPROVED':
        return jsonify({'success': False, 'error': 'LPO already approved'}, 400)
    if current_status == 'SUBMITTED':
        return jsonify({'success': False, 'error': 'LPO already submitted'}, 400)
    _set_po_approval_status(lpo_no, 'SUBMITTED', 'SUBMIT', remarks or 'Submitted for approval')
    try:
        from addons.approval_workflow.approval_workflow_engine import sync_lpo_submit
        hdr = _get_lpo_header(lpo_no)
        amt = float((hdr or {}).get('lpoamount') or 0)
        sync_lpo_submit(lpo_no, amt, session.get('user') or 'web', _resolve_location_code())
    except Exception:
        pass
    return jsonify({'success': True, 'status': 'SUBMITTED'})

