@bp.route('/purchase/receipt/api/list', methods=['GET'])
def api_grn_list():
    """Paginated GRN list: pending approved PO / draft / posted / reversed GRN."""
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Unauthorized'}, 401)
    _apply_db()
    try:
        page = max(1, int(request.args.get('page') or 1))
    except (TypeError, ValueError):
        page = 1
    try:
        per_page = max(20, min(int(request.args.get('per_page') or 50), 200))
    except (TypeError, ValueError):
        per_page = 50
    tab = (request.args.get('tab') or 'pending').strip().lower()
    if tab == 'completed':
        tab = 'posted'
    if tab not in ('pending', 'posted', 'draft', 'reversed'):
        tab = 'pending'
    search = (request.args.get('search') or '').strip() or None
    date_from = (request.args.get('date_from') or '').strip()[:10] or None
    date_to = (request.args.get('date_to') or '').strip()[:10] or None
    t_api = time.perf_counter()
    try:
        if tab == 'posted':
            rows, total_count = _get_receipt_list_page(
                page=page, per_page=per_page, search=search, date_from=date_from, date_to=date_to,
                inventory_tab='posted',
            )
        elif tab == 'draft':
            rows, total_count = _get_receipt_list_page(
                page=page, per_page=per_page, search=search, date_from=date_from, date_to=date_to,
                inventory_tab='draft',
            )
        elif tab == 'reversed':
            rows, total_count = _get_receipt_list_page(
                page=page, per_page=per_page, search=search, date_from=date_from, date_to=date_to,
                inventory_tab='reversed',
            )
        else:
            rows, total_count = _get_pending_po_for_grn_page(
                page=page, per_page=per_page, search=search, date_from=date_from, date_to=date_to,
            )
    except Exception as e:
        print(f'[api_grn_list] {e}')
        return jsonify({'success': False, 'error': str(e)}, 500)
    total_pages = (total_count + per_page - 1) // per_page if total_count > 0 else 1
    elapsed_api = time.perf_counter() - t_api
    if elapsed_api >= 0.5:
        print(f'[api_grn_list] {elapsed_api:.2f}s tab={tab} page={page} rows={len(rows or [])} total={total_count}')
    return jsonify({
        'success': True,
        'tab': tab,
        'rows': rows,
        'total_count': total_count,
        'page': page,
        'items_per_page': per_page,
        'total_pages': total_pages,
    })

@bp.route('/purchase/receipt/summary-pdf')
def grn_summary_pdf():
    if not session.get('user'):
        return redirect(url_for('auth.login'))
    _apply_db()
    date_from = (request.args.get('date_from') or '').strip()
    date_to = (request.args.get('date_to') or '').strip()
    search = (request.args.get('search') or '').strip().lower()
    rows = _get_receipt_list()
    filtered = []
    for r in rows:
        d = str(r.get('receiptdate') or '')[:10]
        if date_from and d < date_from:
            continue
        if date_to and d > date_to:
            continue
        if search:
            haystack = (str(r.get('receiptno') or '') + ' ' + str(r.get('suppliercode') or '') + ' ' + str(r.get('suppliername') or '')).lower()
            if search not in haystack:
                continue
        filtered.append(r)
    pdf_bytes, err = _build_grn_summary_pdf(filtered, date_from, date_to)
    if err:
        return (err, 500)
    return send_file(io.BytesIO(pdf_bytes), mimetype='application/pdf', as_attachment=False, download_name='GRN_Summary.pdf')

def _build_grn_summary_pdf(rows, date_from: str, date_to: str) -> tuple:
    if not REPORTLAB_AVAILABLE:
        return (None, 'PDF library (reportlab) is not available.')
    company = _get_company_profile()
    company_name = str(company.get('name') or session.get('location_name') or '')
    company_address = str(company.get('address') or '')
    company_phone = str(company.get('phone') or '')
    company_email = str(company.get('email') or '')
    tenant_logo_abs = ''
    try:
        tid = str(session.get('tenant_id') or '').strip()
        if tid:
            t = get_tenant_by_id(tid) or {}
            logo_rel = str(t.get('logo_path') or '').strip()
            if logo_rel:
                candidate = os.path.abspath(os.path.join(bp.root_path, '..', 'static', logo_rel))
                if os.path.exists(candidate):
                    tenant_logo_abs = candidate
    except Exception:
        pass
    styles = getSampleStyleSheet()
    BLUE = colors.HexColor('#1a56a4')
    BLUE_LIGHT = colors.HexColor('#e8f0fb')
    BORDER = colors.HexColor('#b0b8c4')
    GRAY_ROW = colors.HexColor('#f7f8fa')
    TEXT = colors.HexColor('#1a1a1a')
    PAD = 5

    def _s(name, **kw):
        base = kw.pop('parent', styles['Normal'])
        kw.setdefault('textColor', TEXT)
        return ParagraphStyle(name, parent=base, **kw)
    N8 = _s('gn8', fontSize=8, leading=11)
    N9 = _s('gn9', fontSize=9, leading=12)
    N9R = _s('gn9r', fontSize=9, leading=12, alignment=TA_RIGHT)
    N9C = _s('gn9c', fontSize=9, leading=12, alignment=TA_CENTER)
    N10 = _s('gn10', fontSize=10, leading=14)
    N10B = _s('gn10b', fontSize=10, leading=14, fontName='Helvetica-Bold')
    LBL = _s('glbl', fontSize=8, leading=11, textColor=colors.HexColor('#555f6b'))
    HDR = _s('ghdr', fontSize=15, leading=18, alignment=TA_CENTER, textColor=BLUE, fontName='Helvetica-Bold')
    SUB = _s('gsub', fontSize=9, leading=12, alignment=TA_CENTER, textColor=colors.HexColor('#555f6b'))
    WHT = _s('gwht', fontSize=9, leading=12, alignment=TA_CENTER, textColor=colors.white, fontName='Helvetica-Bold')
    FOOT = _s('gft', fontSize=7.5, leading=10, textColor=colors.HexColor('#888'), alignment=TA_CENTER)
    WHT_R = _s('gwhtR', fontSize=9, leading=12, alignment=TA_RIGHT, textColor=colors.white, fontName='Helvetica-Bold')
    TOT_L = _s('gtotL', fontSize=9, leading=12, fontName='Helvetica-Bold', alignment=TA_RIGHT)
    TOT_R = _s('gtotR', fontSize=9, leading=12, fontName='Helvetica-Bold', alignment=TA_RIGHT)
    TITLE = _s('gtitle', fontSize=12, leading=16, alignment=TA_CENTER, textColor=BLUE, fontName='Helvetica-Bold')
    PAGE_W = 7.27 * inch
    buffer = io.BytesIO()
    doc = SimpleDocTemplate(buffer, pagesize=A4, topMargin=0.45 * inch, bottomMargin=0.4 * inch, leftMargin=0.5 * inch, rightMargin=0.5 * inch)
    elements = []
    logo_cell: Any = ''
    if tenant_logo_abs:
        try:
            logo_cell = RLImage(tenant_logo_abs, width=1.2 * inch, height=0.55 * inch)
            logo_cell.hAlign = 'LEFT'
        except Exception:
            logo_cell = ''
    co_lines = [Paragraph(company_name or 'Company', HDR)]
    if company_address:
        co_lines.append(Paragraph(company_address, SUB))
    if company_phone:
        co_lines.append(Paragraph(f'Tel: {company_phone}', SUB))
    if company_email:
        co_lines.append(Paragraph(f'Email: {company_email}', SUB))
    hdr_data = [[logo_cell, co_lines, '']]
    hdr_tbl = Table(hdr_data, colWidths=[1.3 * inch, PAGE_W - 2.6 * inch, 1.3 * inch])
    hdr_tbl.setStyle(TableStyle([('VALIGN', (0, 0), (-1, -1), 'MIDDLE'), ('ALIGN', (1, 0), (1, 0), 'CENTER'), ('BOTTOMPADDING', (0, 0), (-1, -1), 8)]))
    hdr_tbl.hAlign = 'LEFT'
    elements.append(hdr_tbl)
    rule = Table([['']], colWidths=[PAGE_W])
    rule.setStyle(TableStyle([('LINEBELOW', (0, 0), (0, 0), 1.5, BLUE), ('TOPPADDING', (0, 0), (0, 0), 0), ('BOTTOMPADDING', (0, 0), (0, 0), 4)]))
    rule.hAlign = 'LEFT'
    elements.append(rule)
    elements.append(Spacer(1, 6))
    title_para = Paragraph('Goods Receipt Note — Summary Report', TITLE)
    elements.append(title_para)
    elements.append(Spacer(1, 4))
    date_range_parts = []
    if date_from:
        date_range_parts.append(f'From: {date_from}')
    if date_to:
        date_range_parts.append(f'To: {date_to}')
    if not date_range_parts:
        date_range_parts.append('All Dates')
    generated_on = datetime.now().strftime('%d-%m-%Y %H:%M')
    info_text = '  |  '.join(date_range_parts) + f'  |  Generated: {generated_on}  |  Records: {len(rows)}'
    elements.append(Paragraph(info_text, SUB))
    elements.append(Spacer(1, 10))
    _fixed_w = (0.45 + 0.85 + 0.9 + 1.1 + 0.75 + 1.0) * inch
    COL_WIDTHS = [0.45 * inch, 0.85 * inch, 0.9 * inch, 1.1 * inch, PAGE_W - _fixed_w, 0.75 * inch, 1.0 * inch]
    tbl_header = [Paragraph('Sl.No', WHT), Paragraph('Receipt No', WHT), Paragraph('Date', WHT), Paragraph('Supplier Code', WHT), Paragraph('Supplier Name', WHT), Paragraph('Discount', WHT_R), Paragraph('Amount', WHT_R)]
    table_data = [tbl_header]
    grand_total = 0.0
    grand_disc = 0.0
    for idx, r in enumerate(rows, 1):
        amt = float(r.get('amount') or 0)
        disc = float(r.get('discount') or 0)
        grand_total += amt
        grand_disc += disc
        d = str(r.get('receiptdate') or '')[:10]
        row_bg = GRAY_ROW if idx % 2 == 0 else colors.white
        table_data.append([Paragraph(str(idx), N9C), Paragraph(str(r.get('receiptno') or '-'), N9), Paragraph(d or '-', N9), Paragraph(str(r.get('suppliercode') or '-'), N9), Paragraph(str(r.get('suppliername') or '-'), N9), Paragraph(f'{disc:,.2f}', N9R), Paragraph(f'{amt:,.2f}', N9R)])
    table_data.append([Paragraph('', N9), Paragraph('', N9), Paragraph('', N9), Paragraph('', N9), Paragraph('Total', TOT_L), Paragraph(f'{grand_disc:,.2f}', TOT_R), Paragraph(f'{grand_total:,.2f}', TOT_R)])
    dt = Table(table_data, colWidths=COL_WIDTHS, repeatRows=1)
    tbl_style = [('BACKGROUND', (0, 0), (-1, 0), BLUE), ('TEXTCOLOR', (0, 0), (-1, 0), colors.white), ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'), ('FONTSIZE', (0, 0), (-1, 0), 9), ('ROWBACKGROUND', (0, 1), (-1, -2), [colors.white, GRAY_ROW]), ('BACKGROUND', (0, -1), (-1, -1), BLUE_LIGHT), ('FONTNAME', (0, -1), (-1, -1), 'Helvetica-Bold'), ('LINEABOVE', (0, -1), (-1, -1), 1.0, BLUE), ('GRID', (0, 0), (-1, -1), 0.4, BORDER), ('LINEBELOW', (0, 0), (-1, 0), 1.0, BLUE), ('TOPPADDING', (0, 0), (-1, -1), PAD), ('BOTTOMPADDING', (0, 0), (-1, -1), PAD), ('LEFTPADDING', (0, 0), (-1, -1), PAD), ('RIGHTPADDING', (0, 0), (-1, -1), PAD), ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'), ('ALIGN', (0, 0), (0, -1), 'CENTER'), ('ALIGN', (5, 0), (6, -1), 'RIGHT')]
    dt.setStyle(TableStyle(tbl_style))
    dt.hAlign = 'LEFT'
    elements.append(dt)

    def add_page_footer(canvas, doc):
        canvas.saveState()
        canvas.setFont('Helvetica', 7.5)
        canvas.setFillColor(colors.HexColor('#888888'))
        w, h = A4
        canvas.drawCentredString(w / 2, 0.25 * inch, f'GRN Summary Report  —  {company_name}  —  Page {doc.page}')
        canvas.restoreState()
    doc.build(elements, onFirstPage=add_page_footer, onLaterPages=add_page_footer)
    return (buffer.getvalue(), None)

def _get_purchase_return_summary_list(return_type: Optional[str]='P') -> List[Dict[str, Any]]:
    """All saved purchase returns (RETURNHDR) for summary PDF — includes GL posted and unposted."""
    rows = _get_posted_purchase_return_list(return_type=return_type, require_posting_row=None) or []
    out: List[Dict[str, Any]] = []
    for r in rows:
        d = r.get('returndate')
        if d is not None and hasattr(d, 'strftime'):
            d_s = d.strftime('%Y-%m-%d')
        else:
            d_s = str(d or '')[:10]
        try:
            amt = float(r.get('returnamount') or 0)
        except (TypeError, ValueError):
            amt = 0.0
        try:
            disc = float(r.get('discount') or 0)
        except (TypeError, ValueError):
            disc = 0.0
        out.append({
            'goodsreturnno': r.get('goodsreturnno'),
            'returndate': d_s,
            'suppliercode': r.get('suppliercode'),
            'suppliername': r.get('suppliername') or '',
            'amount': amt,
            'discount': disc,
        })
    return out

