@bp.route('/purchase/receipt/api/adjacent-posted', methods=['GET'])
def api_receipt_adjacent_posted():
    """Prev/next inventory-posted GRN receipt numbers for keyboard / button navigation."""
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    receipt_no = parse_receiptno_from_request(request.args.get('receiptno'))
    direction = (request.args.get('direction') or '').strip().lower()
    loc = _resolve_location_code()
    # New GRN screen (receiptno = next # or 0): prev → latest posted below; next → none (client opens new).
    nav_receipt_no = receipt_no if receiptno_is_valid(receipt_no) else 2147483647
    if direction in ('prev', 'next'):
        adjacent = _get_adjacent_posted_grn_receipt_no(nav_receipt_no, direction, location_code=loc)
        return jsonify({
            'success': True,
            'receiptno': adjacent,
            'direction': direction,
            'has_adjacent': adjacent is not None,
        })
    prev_no = _get_adjacent_posted_grn_receipt_no(nav_receipt_no, 'prev', location_code=loc)
    next_no = _get_adjacent_posted_grn_receipt_no(nav_receipt_no, 'next', location_code=loc)
    return jsonify({
        'success': True,
        'receiptno': receipt_no,
        'prev': prev_no,
        'next': next_no,
        'has_prev': prev_no is not None,
        'has_next': next_no is not None,
    })

@bp.route('/purchase/receipt/query/<path:receipt_no>')
def goods_receipt_query(receipt_no):
    if not session.get('user'):
        return redirect(url_for('auth.login'))
    _apply_db()
    t0 = time.perf_counter()
    header = _get_receipt_header_for_posting(receipt_no)
    details = _get_receipt_details(receipt_no)
    elapsed = time.perf_counter() - t0
    if elapsed >= 0.5:
        print(f'[goods_receipt_query] {elapsed:.2f}s receipt={receipt_no} lines={len(details or [])}')
    if not header:
        flash(f'GRN / invoice {receipt_no} was not found for this branch.', 'error')
        # Prefer returning to Purchase Invoice posting when opened from there.
        ref = (request.headers.get('Referer') or '').lower()
        if '/purchase/invoice' in ref:
            return redirect(url_for('purchase.purchase_invoice_list'))
        return redirect(url_for('purchase.goods_receipt_list'))
    account_posted = _grn_is_account_posted(receipt_no)
    inv_flag = str((header or {}).get('inventory_posted') or 'N').strip().upper()
    if inv_flag in ('Y', '1', 'YES', 'TRUE'):
        inventory_posted = True
    elif inv_flag in ('N', '0', 'NO', 'FALSE'):
        inventory_posted = _grn_receipt_has_item_journal(receipt_no)
    else:
        inventory_posted = _grn_is_inventory_posted(receipt_no)
    view_param = (request.args.get('view') or '').strip().lower() in ('1', 'true', 'yes')
    readonly = bool(account_posted or inventory_posted or view_param)
    grn_lines_readonly = readonly
    grn_edit_mode = bool(header) and not readonly
    return render_template(
        'purchase/goods_receipt_form.html',
        **_grn_form_template_kwargs(
            next_receiptno=receipt_no,
            transaction_date=header.get('receiptdate') or '',
            suppliers=[],
            items=[],
            load_header=header,
            load_details=details,
            query_mode=readonly,
            account_posted=account_posted,
            inventory_posted=inventory_posted,
            can_post_inventory=False,
            grn_edit_mode=grn_edit_mode,
            grn_lines_readonly=grn_lines_readonly,
            approval_status=_get_grn_approval_status(receipt_no),
        ),
    )

def _verify_current_user_password(password: Any, *, required_msg: str = 'Password is required.') -> Optional[str]:
    """Return error message if password invalid; None if OK."""
    pwd = str(password or '').strip()
    if not pwd:
        return required_msg
    username = str(session.get('user') or '').strip()
    if not username:
        return 'Not authenticated.'
    if verify_user(username, pwd):
        return None
    resolved = get_username_by_employeecode(username)
    if resolved and verify_user(resolved, pwd):
        return None
    return 'Invalid password.'


def _verify_grn_delete_user_password(password: Any) -> Optional[str]:
    return _verify_current_user_password(password, required_msg='Password is required to delete.')

@bp.route('/purchase/receipt/api/delete', methods=['POST'])
def api_receipt_delete():
    if not session.get('user'):
        return jsonify({'error': 'Not authenticated'}, 401)
    _apply_db()
    if not _grn_receipt_try_acquire_session_lock():
        return json_response_keep_global_nonce({
            'success': False,
            'error': 'A GRN operation is already in progress for this session. Please wait.',
            'save_session_locked': True,
        }, 423)
    try:
        submitted_nonce = extract_submitted_save_nonce(request)
        if not reject_invalid_form_save_nonce(submitted_nonce, session_key=GLOBAL_SAVE_NONCE_SESSION_KEY):
            return replay_blocked_response_global()
        data = request.get_json(silent=True) or {}
        try:
            receipt_no = parse_receiptno_from_request(data.get('receiptno'))
        except (TypeError, ValueError):
            receipt_no = 0
        if receipt_no <= 0:
            return json_response_keep_global_nonce({'success': False, 'error': 'Receipt No is required'}, 400)
        pwd_err = _verify_grn_delete_user_password(data.get('password'))
        if pwd_err:
            return json_response_keep_global_nonce({'success': False, 'error': pwd_err}, 403)
        before_snap = _audit_grn_snapshot(
            _get_receipt_header_for_posting(receipt_no),
            _get_receipt_details(receipt_no),
        )
        _grn_save_audit('DELETE attempt receipt_no=%s | %s', receipt_no, _grn_save_audit_ctx())
        err = _delete_receipt(receipt_no)
        if err:
            _grn_save_audit('DELETE fail receipt_no=%s err=%r | %s', receipt_no, err, _grn_save_audit_ctx())
            return json_response_keep_global_nonce({'success': False, 'error': err}, 400)
        if not commit_form_save_nonce(submitted_nonce, session_key=GLOBAL_SAVE_NONCE_SESSION_KEY):
            return replay_blocked_response_global()
        _grn_save_audit('DELETE ok receipt_no=%s | %s', receipt_no, _grn_save_audit_ctx())
        _lpo_list_count_cache_invalidate_grn_lists(_resolve_location_code())
        _log_purchase_change('GRN', receipt_no, 'DELETE', 'Draft GRN deleted.', before=before_snap)
        return json_response_rotate_global({
            'success': True,
            'receiptno': receipt_no,
            'message': f'GRN {receipt_no} deleted.',
        })
    except Exception as ex:
        _grn_save_audit('DELETE unhandled_exception %s: %s | %s', type(ex).__name__, ex, _grn_save_audit_ctx())
        raise
    finally:
        _grn_receipt_release_session_lock()


