def _grn_quick_item_units_from_table(location_code: int) -> List[Dict[str, Any]]:
    """Unit codes for GRN quick-item — UNITOFMEASUREMENT only (branch-scoped when table has LOCATIONCODE)."""
    try:
        from db import get_units_for_itemmaster_dropdown
        rows = get_units_for_itemmaster_dropdown(int(location_code)) or []
    except Exception:
        rows = []
    out: List[Dict[str, Any]] = []
    for u in rows:
        code = str(u.get('code') or '').strip()
        if not code:
            continue
        out.append({'code': code, 'name': str(u.get('name') or '').strip()})
    return out


def _grn_quick_item_resolve_uom(uom_hint: str, location_code: int) -> str:
    """Map invoice UOM text to a code that exists in UNITOFMEASUREMENT (no invented codes)."""
    raw = str(uom_hint or '').strip()
    if not raw:
        return ''
    u = raw.upper()
    loc = int(location_code)
    for unit in _grn_quick_item_units_from_table(loc):
        c = str(unit.get('code') or '').strip().upper()
        n = str(unit.get('name') or '').strip().upper()
        if c == u or n == u:
            return str(unit.get('code') or '').strip()
    try:
        from db import uom_code_exists_for_location
        code_try = raw.upper()[:30]
        if uom_code_exists_for_location(code_try, loc):
            return code_try
    except Exception:
        pass
    return ''


def _grn_quick_item_barcode_lookup(barcode: str, location_code: int) -> Optional[Dict[str, Any]]:
    """Return item row if barcode exists on ITEMALTERNATEUOMMAP or ITEMMASTER."""
    hit = _grn_lookup_item_row_by_barcode(barcode, location_code)
    if hit and hit.get('code') is not None:
        return _grn_import_item_from_barcode_row(hit)
    return None


def _grn_quick_item_barcode_already_saved(barcode: str, location_code: int) -> Optional[str]:
    """Return existing item code if barcode is already on ITEMMASTER or alternate UOM map."""
    row = _grn_quick_item_barcode_lookup(barcode, location_code)
    if row:
        return str(row.get('code') or '').strip() or None
    return None


def _grn_quick_item_validate_uom(uom_hint: str, location_code: int) -> Tuple[str, Optional[str]]:
    """Resolve UOM code and ensure it exists in UNITOFMEASUREMENT. Returns (code, error)."""
    raw = str(uom_hint or '').strip()
    if not raw:
        return '', 'Base UOM is required.'
    code = _grn_quick_item_resolve_uom(raw, location_code)
    if not code:
        return '', 'Base UOM is required.'
    try:
        from db import uom_code_exists_for_location
        if not uom_code_exists_for_location(code, int(location_code)):
            return code, (
                f'Unit "{code}" is not in the UNITOFMEASUREMENT table for this branch. '
                'Add it under Inventory → Unit of measurement.'
            )
    except Exception:
        pass
    return code, None

def _grn_quick_item_default_gl_accounts() -> Dict[str, str]:
    return {'sales_account': '4100', 'purchase_account': '5001', 'inventory_account': '1300', 'cogs_account': '5100'}

def _grn_quick_item_category_options(rows: Optional[List[Dict[str, Any]]]) -> List[Dict[str, Any]]:
    out: List[Dict[str, Any]] = []
    for r in rows or []:
        try:
            code = int(float(r.get('code')))
        except (TypeError, ValueError):
            continue
        pid: Optional[int] = None
        try:
            if r.get('id') is not None and str(r.get('id')).strip() != '':
                pid = int(float(r.get('id')))
        except (TypeError, ValueError):
            pid = None
        out.append({'code': code, 'name': str(r.get('name') or '').strip(), 'parent_id': pid})
    return out

def _grn_quick_item_int_code(val: Any) -> int:
    try:
        return int(float(str(val or 0)))
    except (TypeError, ValueError):
        return 0


def _grn_quick_item_category_rows(flag: str, location_code: int) -> List[Dict[str, Any]]:
    """CATEGORY rows for GRN quick-item (branch-scoped, fallback when branch has no rows)."""
    fl = (flag or 'C').strip().upper()[:1]
    loc = int(location_code)
    try:
        from db import get_categories
        rows = get_categories(fl, location_code=loc) or []
        if not rows:
            rows = get_categories(fl) or []
        return rows
    except Exception:
        return []


def _grn_quick_item_category_lookups(location_code: int) -> Dict[str, List[Dict[str, Any]]]:
    """Main / dept / micro from category tree; brands from CATEGORY (same as Item Master)."""
    loc = int(location_code)
    mains: List[Dict[str, Any]] = []
    depts: List[Dict[str, Any]] = []
    micros: List[Dict[str, Any]] = []
    try:
        from db import get_category_master_tree
        tree = get_category_master_tree(location_code=loc) or []
    except Exception:
        tree = []
    for main in tree:
        try:
            mc = int(float(main.get('code')))
        except (TypeError, ValueError):
            continue
        mains.append({
            'code': mc,
            'name': str(main.get('name') or '').strip(),
            'parent_id': None,
        })
        for cat in main.get('children') or []:
            try:
                dc = int(float(cat.get('code')))
            except (TypeError, ValueError):
                continue
            depts.append({
                'code': dc,
                'name': str(cat.get('name') or '').strip(),
                'parent_id': mc,
            })
            for micro in cat.get('children') or []:
                try:
                    mic = int(float(micro.get('code')))
                except (TypeError, ValueError):
                    continue
                micros.append({
                    'code': mic,
                    'name': str(micro.get('name') or '').strip(),
                    'parent_id': dc,
                })
    brand_rows = _grn_quick_item_category_options(_grn_quick_item_category_rows('B', loc))
    return {
        'main_categories': mains,
        'categories': depts,
        'micro_categories': micros,
        'brands': brand_rows,
    }


@bp.route('/purchase/receipt/api/grn-quick-item-barcode-check', methods=['GET'])
def api_receipt_grn_quick_item_barcode_check():
    """Check barcode against ITEMALTERNATEUOMMAP then ITEMMASTER (same as invoice import)."""
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    loc_code = _resolve_location_code()
    barcode = str(request.args.get('barcode') or request.args.get('manufacturer_id') or '').strip()
    if not barcode:
        return jsonify({'success': False, 'error': 'Barcode is required'}, 400)
    row = _grn_quick_item_barcode_lookup(barcode, loc_code)
    if not row:
        return jsonify({'success': True, 'exists': False})
    return jsonify({
        'success': True,
        'exists': True,
        'itemcode': row.get('code'),
        'itemname': row.get('name') or row.get('itemname'),
        'barcode': row.get('barcode'),
        'uom': row.get('uom'),
        'barcode_source': row.get('barcode_source') or 'master',
    })


@bp.route('/purchase/receipt/api/grn-quick-item-uom', methods=['POST'])
def api_receipt_grn_quick_item_uom():
    """Create a unit in UNITOFMEASUREMENT from GRN quick-item modal (no full Unit Master page)."""
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    loc_code = _resolve_location_code()
    data = request.get_json(silent=True) or {}
    code = str(data.get('code') or data.get('uom') or '').strip().upper()
    name = str(data.get('name') or '').strip() or code
    if not code:
        return jsonify({'success': False, 'error': 'Unit code is required.'}, 400)
    try:
        from db import insert_unit_of_measurement, uom_code_exists_for_location
        if uom_code_exists_for_location(code, loc_code):
            return jsonify({
                'success': True,
                'code': code,
                'name': name,
                'already_exists': True,
            })
        ok, err = insert_unit_of_measurement(code, name)
        if not ok:
            return jsonify({'success': False, 'error': err or 'Could not create unit.'}, 400)
        return jsonify({'success': True, 'code': code, 'name': name})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)[:500]}, 500)


@bp.route('/purchase/receipt/api/grn-quick-item', methods=['GET', 'POST'])
def api_receipt_grn_quick_item():
    """Quick-create item from GRN (modal): important fields only, no full Item Master page."""
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    loc_code = _resolve_location_code()
    if request.method == 'GET':
        try:
            from db import get_next_item_code, get_units_for_itemmaster_dropdown, get_units
            next_code = get_next_item_code(loc_code)
        except Exception:
            next_code = None
        units = _grn_quick_item_units_from_table(loc_code)[:200]
        cat_lookups = _grn_quick_item_category_lookups(loc_code)
        suppliers = []
        for s in (_get_suppliers() or [])[:500]:
            try:
                code = int(float(s.get('code')))
            except (TypeError, ValueError):
                continue
            suppliers.append({
                'code': code,
                'name': str(s.get('name') or '').strip(),
                'parent_id': None,
            })
        return jsonify({
            'success': True,
            'next_item_code': next_code,
            'units': units,
            'units_source': 'UNITOFMEASUREMENT',
            'default_accounts': _grn_quick_item_default_gl_accounts(),
            'main_categories': cat_lookups['main_categories'],
            'categories': cat_lookups['categories'],
            'micro_categories': cat_lookups['micro_categories'],
            'brands': cat_lookups['brands'],
            'suppliers': suppliers,
        })
    data = request.get_json(silent=True) or {}
    barcode = str(data.get('barcode') or data.get('manufacturer_id') or '').strip()
    item_name = str(data.get('item_name') or data.get('itemname') or '').strip()
    if not barcode:
        return jsonify({'success': False, 'error': 'Barcode is required'}, 400)
    if not item_name:
        return jsonify({'success': False, 'error': 'Item name is required'}, 400)
    description = str(data.get('description') or item_name).strip()[:500]
    item_name_ara = str(data.get('item_name_ara') or data.get('itemnameara') or '').strip()[:500]
    base_uom, uom_err = _grn_quick_item_validate_uom(str(data.get('base_uom') or data.get('uom') or ''), loc_code)
    if uom_err:
        return jsonify({'success': False, 'error': uom_err}, 400)
    try:
        cost_price = float(data.get('cost_price') if data.get('cost_price') is not None else data.get('cost') or 0)
    except (TypeError, ValueError):
        cost_price = 0.0
    try:
        retail_price = float(data.get('retail_price') if data.get('retail_price') is not None else data.get('retail') or 0)
    except (TypeError, ValueError):
        retail_price = 0.0
    existing = _grn_quick_item_barcode_lookup(barcode, loc_code)
    if existing:
        code_s = str(existing.get('code') or '').strip()
        return jsonify({
            'success': True,
            'itemcode': code_s,
            'itemname': existing.get('name') or item_name,
            'barcode': barcode,
            'uom': existing.get('uom') or base_uom,
            'retail': retail_price,
            'cost': cost_price,
            'already_existed': True,
            'barcode_source': existing.get('barcode_source') or 'master',
        })
    if retail_price <= 0:
        return jsonify({'success': False, 'error': 'Please set retail price.'}, 400)
    try:
        sup_code = int(float(data.get('sup_code') or data.get('suppliercode') or 0))
    except (TypeError, ValueError):
        sup_code = 0
    main_category = _grn_quick_item_int_code(data.get('main_category'))
    department_code = _grn_quick_item_int_code(data.get('department_code'))
    category_code = _grn_quick_item_int_code(data.get('category_code') or data.get('micro_category'))
    brand_code = _grn_quick_item_int_code(data.get('brand_code'))
    try:
        vat_percent = float(data.get('vat_percent') if data.get('vat_percent') is not None else data.get('vat') or 0)
    except (TypeError, ValueError):
        vat_percent = 0.0
    gl = _grn_quick_item_default_gl_accounts()
    try:
        from db import save_grn_quick_item_new
        item_data = {
            'location_code': loc_code,
            'manufacturer_id': barcode,
            'item_name': item_name.upper(),
            'item_name_ara': item_name_ara,
            'description': description,
            'base_uom': base_uom,
            'sup_code': sup_code if sup_code > 0 else 0,
            'cost_price': cost_price,
            'retail_price': retail_price,
            'wholesale_price': 0,
            'third_price': 0,
            'branch_price': 0,
            'maximum_level': 0,
            'reorder_level': 0,
            'vat_percent': vat_percent,
            'discount_flag': 'N',
            'item_flag': 'Y',
            'main_category': main_category,
            'department_code': department_code,
            'category_code': category_code,
            'brand_code': brand_code,
            'size_code': 0,
            'color_code': 0,
            'sales_account': gl['sales_account'],
            'purchase_account': gl['purchase_account'],
            'inventory_account': gl['inventory_account'],
            'cogs_account': gl['cogs_account'],
        }
        saved_code, txn_err, already_existed = save_grn_quick_item_new(item_data)
        if txn_err:
            return jsonify({'success': False, 'error': txn_err}, 400)
        if not saved_code:
            return jsonify({'success': False, 'error': 'Failed to save item.'}, 500)
        code_s = str(saved_code).strip()
        return jsonify({
            'success': True,
            'itemcode': code_s,
            'itemname': item_name,
            'barcode': barcode,
            'uom': base_uom,
            'retail': retail_price,
            'cost': cost_price,
            'already_existed': bool(already_existed),
        })
    except ValueError as e:
        return jsonify({'success': False, 'error': str(e)}, 400)
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)[:500]}, 500)

@bp.route('/purchase/receipt/api/ai-invoice-extract', methods=['POST'])
def api_receipt_ai_invoice_extract():
    """Upload supplier invoice PDF and/or images (multi-page); OpenAI extract + match supplier/items."""
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    step = (request.form.get('grn_ai_step') or '').strip().lower()
    if step == 'prepare':
        return _grn_ai_invoice_step_prepare()
    if step == 'page':
        return _grn_ai_invoice_step_page()
    if step == 'recover':
        return _grn_ai_invoice_step_recover()
    incremental_import = step == 'finalize'
    if step and not incremental_import:
        return jsonify({'success': False, 'error': f'Unknown step: {step}'}, 400)

    incremental_job: Optional[Dict[str, Any]] = None
    if incremental_import:
        job_id = (request.form.get('job_id') or '').strip()
        try:
            incremental_job = _grn_ai_invoice_job_require(job_id)
        except ValueError as e:
            return jsonify({'success': False, 'error': str(e)}, 400)
        pages_done = incremental_job.get('pages_done') or set()
        n_pages = int(incremental_job.get('n_pages') or 0)
        if n_pages > 0 and len(pages_done) < n_pages:
            return jsonify({
                'success': False,
                'error': f'Not all pages read yet ({len(pages_done)}/{n_pages}). Finish page extract first.',
            }, 400)
        file_blobs = list(incremental_job.get('file_blobs') or [])
        text = incremental_job.get('text')
        image_parts = list(incremental_job.get('image_parts') or [])
        collect_warn = list(incremental_job.get('collect_warn') or [])
        prebuilt_table_map = dict(incremental_job.get('table_row_map') or {})
        fill_from_job = int(incremental_job.get('fill_max_hint') or 0)
        header_from_job = dict(incremental_job.get('header') or {})
        lines_from_job = list(incremental_job.get('all_lines') or [])
        lines_from_job = _grn_fixup_job_all_lines_serials(
            lines_from_job, n_pages, fill_from_job, text,
        )
        _fixed_table_map = _grn_table_row_map_from_lines(lines_from_job)
        if _fixed_table_map:
            prebuilt_table_map = _fixed_table_map
        extracted: Dict[str, Any] = {
            **header_from_job,
            'lines': lines_from_job,
            '__lines_count__': len(lines_from_job),
            '__finish_reason__': '',
            '__fast_multipage__': True,
            '__fill_max_hint__': fill_from_job,
            '__incremental_import__': True,
        }
        t_extract0 = time.time() - float(incremental_job.get('extract_sec') or 0)
    else:
        file_blobs, upload_err = _grn_ai_invoice_read_upload_blobs()
        if upload_err:
            return jsonify({'success': False, 'error': upload_err}, 400)
        text, image_parts, collect_warn = _grn_collect_invoice_extract_payload(file_blobs)
        prebuilt_table_map = {}
        extracted = {}
        t_extract0 = time.time()

    tp = (text or '').strip()
    if not incremental_import and not image_parts and len(tp) < 20:
        return jsonify({'success': False, 'error': 'Could not read invoice file(s). Use PDF, PNG, JPG, or WEBP — for scans, ensure all pages are included.'}, 400)
    ai_model = _grn_ai_invoice_openai_model()
    text_row_map_pre = _grn_parse_quotation_table_rows_from_text(tp) if tp else {}
    text_serial_pre = len(text_row_map_pre)
    if not incremental_import:
        use_text_dominant = _grn_should_use_text_dominant_extract(tp, text_serial_pre, len(image_parts))
        use_fast_mp = (
            _grn_ai_fast_multipage_enabled()
            and len(image_parts) > 1
            and not use_text_dominant
        )
        use_text_primary = (len(image_parts) == 0 and len(tp) >= 400) or use_text_dominant
    try:
        if incremental_import:
            pass
        elif use_text_primary:
            extracted = _grn_openai_extract_invoice_header_from_text(tp)
            map_lines = _grn_invoice_lines_from_text_row_map(text_row_map_pre)
            extracted['lines'] = map_lines
            extracted['__lines_count__'] = len(map_lines)
            extracted['__finish_reason__'] = ''
            if use_text_dominant:
                extracted['__text_dominant__'] = True
        elif use_fast_mp:
            extracted = _grn_openai_extract_invoice_fast_multipage(text, image_parts)
            prebuilt_table_map = dict(extracted.pop('__table_row_map__', {}) or {})
        else:
            extracted = _grn_openai_extract_invoice(text, image_parts)
    except json.JSONDecodeError as e:
        _LOG_GRN_AI.warning('ai-invoice-extract invalid JSON model=%s pages=%s: %s', ai_model, len(image_parts), e)
        return jsonify({'success': False, 'error': f'AI returned invalid JSON: {e}'}, 502)
    except Exception as e:
        err = str(e)
        _LOG_GRN_AI.exception('ai-invoice-extract openai failed model=%s pages=%s', ai_model, len(image_parts))
        if 'OPENAI_API_KEY' in err or 'api key' in err.lower():
            return jsonify({'success': False, 'error': 'OPENAI_API_KEY is not configured.'}, 503)
        hint = ''
        low = err.lower()
        if any(x in low for x in ('timeout', 'timed out', '524', '504', '502', 'gateway')):
            hint = ' Try a smaller PDF, fewer pages, or set OPENAI_GRN_INVOICE_MODEL=gpt-4o-mini in .env.'
        return jsonify({'success': False, 'error': (err[:500] + hint).strip()}, 502)
    extract_sec = round(time.time() - t_extract0, 1)
    warnings: List[str] = list(collect_warn or [])
    text_dominant_done = bool(extracted.pop('__text_dominant__', False))
    if text_dominant_done:
        warnings.append(
            f'PDF text mode: {text_serial_pre} serial(s) read from document text '
            f'(skipped vision line extract; header from text, {extract_sec}s).'
        )
    if len(image_parts) >= 4 and 'mini' not in ai_model.lower() and not text_dominant_done:
        warnings.append(
            f'Vision model {ai_model} with {len(image_parts)} page image(s) can take 1–3+ minutes. '
            'Set OPENAI_GRN_INVOICE_MODEL=gpt-4o-mini in .env for faster GRN import.'
        )
    suppliers = _get_suppliers() or []
    items = _get_items_with_alternate_uoms_filtered(search=None, limit=3000) or _get_items_for_location() or []
    barcode_index = _grn_items_barcode_index(items)
    barcode_sql_cache: Dict[str, Optional[Dict[str, Any]]] = {}
    item_location_cache: Dict[str, str] = {}
    resolve_line_locs = _grn_ai_import_resolve_line_locations()
    t_match0 = time.time()
    sup_name = str(extracted.get('supplier_name') or '').strip()
    sup_row, sup_sc, sup_kind = _grn_match_supplier_name(sup_name, suppliers)
    supplier_strong = sup_row is not None and sup_kind == 'matched'
    inv_no = str(extracted.get('invoice_no') or '').strip()
    inv_date = str(extracted.get('invoice_date') or '').strip()[:10]
    disc_total = _grn_float_from_invoice_cell(extracted.get('discount_total'))
    total_inv = _grn_float_from_invoice_cell(extracted.get('total'))
    if total_inv <= 0:
        sub = _grn_float_from_invoice_cell(extracted.get('subtotal'))
        tax = _grn_float_from_invoice_cell(extracted.get('tax_amount'))
        total_inv = sub + tax if sub + tax > 0 else total_inv
    fast_mp_done = bool(extracted.pop('__fast_multipage__', False))
    ai_finish_reason = str(extracted.pop('__finish_reason__', '') or '').strip()
    ai_lines_count_first = int(extracted.pop('__lines_count__', 0) or 0)
    lines_in = extracted.get('lines') or []
    if not isinstance(lines_in, list):
        lines_in = []
    lines_in = [dict(x) for x in lines_in if isinstance(x, dict)]
    line_count_initial = len(lines_in)
    if incremental_import and prebuilt_table_map:
        table_lines = _grn_rebuild_lines_from_table_row_map(prebuilt_table_map)
        if table_lines:
            lines_in = table_lines
            warnings.append(
                f'Printed S. No. from invoice table: {len(table_lines)} line(s) (Ser. from vision table read).'
            )
        else:
            lines_in = _grn_correct_serials_using_table_map(lines_in, prebuilt_table_map, tp)
    text_row_map = text_row_map_pre if text_row_map_pre else (_grn_parse_quotation_table_rows_from_text(tp) if tp else {})
    text_serial_count = len(text_row_map)
    need_text_line_boost = (
        len(tp) >= 400
        and text_serial_count >= 5
        and len(lines_in) < max(text_serial_count, int(text_serial_count * 0.88))
    )
    if need_text_line_boost:
        try:
            t_text_ai0 = time.time()
            text_ai_lines = _grn_openai_extract_lines_from_text_only(tp)
            if text_ai_lines:
                before = len(lines_in)
                lines_in = _grn_merge_ai_invoice_line_lists(lines_in, text_ai_lines)
                warnings.append(
                    f'PDF text line extract: {before} → {len(lines_in)} unique Ser. '
                    f'(+{len(text_ai_lines)} from text AI, {round(time.time() - t_text_ai0, 1)}s).'
                )
        except Exception:
            _LOG_GRN_AI.exception('text-only line supplement failed')
    paged_lines: List[Dict[str, Any]] = []
    need_paged_lines = (
        not incremental_import
        and not fast_mp_done
        and _grn_ai_paged_line_extract_enabled()
        and len(image_parts) > 1
    )
    if need_paged_lines:
        t_paged0 = time.time()
        try:
            paged_lines = _grn_openai_extract_invoice_lines_paged(text, image_parts)
            if paged_lines:
                lines_in = _grn_merge_ai_invoice_line_lists(lines_in, paged_lines)
                warnings.append(
                    f'Per-page line read: {len(paged_lines)} raw row(s) → {len(lines_in)} unique Ser. '
                    f'({round(time.time() - t_paged0, 1)}s).'
                )
        except Exception:
            _LOG_GRN_AI.exception('paged line extract failed pages=%s', len(image_parts))
            warnings.append('Per-page line read failed; re-import or add missing rows manually.')
    elif ai_finish_reason == 'length' and image_parts:
        try:
            paged_lines = _grn_openai_extract_invoice_lines_paged(text, image_parts)
            if paged_lines:
                lines_in = _grn_merge_ai_invoice_line_lists(lines_in, paged_lines)
        except Exception:
            pass
    printed_by_serial: Dict[int, str] = {}
    serial_source: Dict[int, str] = {}
    for ser_k, row in text_row_map.items():
        bc_v = str(row.get('printed_barcode') or row.get('barcode') or '').strip()
        if bc_v:
            printed_by_serial[ser_k] = bc_v
            serial_source[ser_k] = 'pdf_text_serial'
    serial_desc: Dict[int, str] = {
        ser: str(row.get('description') or '').strip()[:200]
        for ser, row in text_row_map.items()
        if str(row.get('description') or '').strip()
    }
    table_row_map: Dict[int, Dict[str, Any]] = dict(prebuilt_table_map)
    if image_parts and not fast_mp_done:
        t_extract_table0 = time.time()
        table_codes, table_desc, table_row_map = _grn_ai_extract_printed_item_table(image_parts, tp or text)
        if table_codes:
            for ser_k, bc_v in table_codes.items():
                printed_by_serial[ser_k] = bc_v
                serial_source[ser_k] = 'table_vision'
            warnings.append(
                f'Read {len(table_codes)} barcode(s) from printed table ({round(time.time() - t_extract_table0, 1)}s).'
            )
        for ser_k, desc_v in (table_desc or {}).items():
            if desc_v and not serial_desc.get(ser_k):
                serial_desc[ser_k] = desc_v
    elif fast_mp_done and table_row_map:
        for ser_k, row in table_row_map.items():
            bc_v = str(row.get('printed_barcode') or row.get('barcode') or '').strip()
            if bc_v:
                printed_by_serial[ser_k] = bc_v
                serial_source[ser_k] = 'table_vision'
            desc_v = str(row.get('description') or '').strip()
            if desc_v and not serial_desc.get(ser_k):
                serial_desc[ser_k] = desc_v[:200]
        if incremental_import:
            warnings.append(
                f'Page-by-page import: {len(table_row_map)} line(s) from {len(image_parts)} page(s) '
                f'({round(time.time() - t_extract0, 1)}s vision).'
            )
        else:
            warnings.append(
                f'Fast multi-page read: {len(table_row_map)} line(s) from {len(image_parts)} page(s) in parallel '
                f'({round(time.time() - t_extract0, 1)}s).'
            )
    fill_max_hint = _grn_infer_quotation_fill_max(
        tp, text_row_map, table_row_map, lines_in, n_pages=len(image_parts),
    )
    if fast_mp_done and isinstance(extracted, dict):
        mp_fill = int(extracted.get('__fill_max_hint__') or 0)
        if mp_fill > fill_max_hint:
            fill_max_hint = mp_fill
    canon_before = len(lines_in)
    lines_in, canon_warns = _grn_canonicalize_invoice_lines_from_sources(
        lines_in,
        printed_by_serial,
        serial_desc,
        text_row_map,
        table_row_map,
        fill_max_hint=fill_max_hint,
    )
    warnings.extend(canon_warns[:20])
    if fill_max_hint > len(lines_in):
        try:
            t_gap0 = time.time()
            gap_sources: List[Dict[str, Any]] = []
            text_ai_lines = _grn_openai_extract_lines_from_text_only(tp)
            if text_ai_lines:
                gap_sources.extend(text_ai_lines)
            if image_parts and not fast_mp_done and not incremental_import:
                mp_extra = _grn_openai_extract_invoice_fast_multipage(text, image_parts)
                mp_lines = mp_extra.get('lines') if isinstance(mp_extra, dict) else None
                if isinstance(mp_lines, list) and mp_lines:
                    gap_sources.extend(mp_lines)
                    for ser_k, row in (mp_extra.get('__table_row_map__') or {}).items():
                        if isinstance(row, dict):
                            table_row_map[int(ser_k)] = _grn_merge_row_fields(
                                table_row_map.get(int(ser_k), {}), row,
                            )
            if gap_sources:
                lines_in = _grn_merge_ai_invoice_line_lists(lines_in, gap_sources)
                lines_in, canon_warns2 = _grn_canonicalize_invoice_lines_from_sources(
                    lines_in,
                    printed_by_serial,
                    serial_desc,
                    text_row_map,
                    table_row_map,
                    fill_max_hint=fill_max_hint,
                )
                warnings.extend(canon_warns2[:10])
                warnings.append(
                    f'Gap-fill to Ser. 1–{fill_max_hint}: {len(lines_in)} line(s) '
                    f'({round(time.time() - t_gap0, 1)}s).'
                )
        except Exception:
            _LOG_GRN_AI.exception('gap-fill extract failed fill_max=%s', fill_max_hint)
    if image_parts and _grn_ai_page_recovery_enabled() and fill_max_hint >= 5 and not incremental_import:
        present_serials = {
            _grn_line_serial_from_row(r, 0)
            for r in lines_in
            if isinstance(r, dict) and _grn_row_has_explicit_serial(r)
        }
        missing_final = [s for s in range(1, fill_max_hint + 1) if s not in present_serials]
        if missing_final and len(missing_final) <= max(50, int(fill_max_hint * 0.65)):
            try:
                t_post_rec = time.time()
                rec_lines, rec_map = _grn_recover_missing_invoice_serials(
                    image_parts, tp, missing_final, fill_max_hint,
                )
                if rec_lines or rec_map:
                    lines_in = _grn_merge_ai_invoice_line_lists(lines_in, rec_lines)
                    for ser_k, row in rec_map.items():
                        table_row_map[int(ser_k)] = _grn_merge_row_fields(
                            table_row_map.get(int(ser_k), {}), row,
                        )
                        bc_v = str(row.get('printed_barcode') or row.get('barcode') or '').strip()
                        if bc_v:
                            printed_by_serial[int(ser_k)] = bc_v
                            serial_source[int(ser_k)] = 'table_vision'
                        desc_v = str(row.get('description') or '').strip()
                        if desc_v and not serial_desc.get(int(ser_k)):
                            serial_desc[int(ser_k)] = desc_v[:200]
                    lines_in, canon_warns3 = _grn_canonicalize_invoice_lines_from_sources(
                        lines_in,
                        printed_by_serial,
                        serial_desc,
                        text_row_map,
                        table_row_map,
                        fill_max_hint=fill_max_hint,
                    )
                    warnings.extend(canon_warns3[:10])
                    still_missing = [
                        s for s in range(1, fill_max_hint + 1)
                        if s not in {
                            _grn_line_serial_from_row(r, 0)
                            for r in lines_in
                            if isinstance(r, dict) and _grn_row_has_explicit_serial(r)
                        }
                    ]
                    recovered_n = len(missing_final) - len(still_missing)
                    warnings.append(
                        f'Missing S. No. recovery: {recovered_n}/{len(missing_final)} '
                        f'(Ser. 1–{fill_max_hint}, {round(time.time() - t_post_rec, 1)}s).'
                    )
                    if still_missing:
                        warnings.append(
                            f'Still missing S. No.: {still_missing[:25]}'
                            + ('…' if len(still_missing) > 25 else '')
                            + ' — add manually or re-import.'
                        )
            except Exception:
                _LOG_GRN_AI.exception('post-canonicalize serial recovery failed fill_max=%s', fill_max_hint)
    if len(lines_in) != canon_before:
        warnings.append(
            f'Canonical import: {len(lines_in)} unique line(s) by Ser. '
            f'(AI passes {line_count_initial}, PDF text {text_serial_count}, table {len(table_row_map)}, '
            f'fill_max {fill_max_hint}).'
        )
    lines_in.sort(
        key=lambda r: _grn_line_serial_from_row(r, 99999) if isinstance(r, dict) else 99999,
    )
    for row in lines_in:
        if isinstance(row, dict):
            ser = _grn_serial_from_invoice_row(row)
            if ser > 0:
                row['serial'] = ser
    extracted = {**extracted, 'lines': lines_in}
    lines_in = _grn_enrich_ai_invoice_lines_from_source_text(
        lines_in, tp, printed_by_serial, serial_source,
    )
    lines_in = _grn_apply_printed_item_codes_by_serial(
        lines_in, printed_by_serial, serial_desc, serial_source,
    )
    if _grn_ai_repair_barcodes_enabled() and not fast_mp_done:
        lines_in = _grn_ai_repair_line_item_codes(lines_in, image_parts, tp)
    missing_printed = sum(
        1 for row in lines_in
        if isinstance(row, dict) and not _grn_printed_barcode_from_row(row)
    )
    if missing_printed and image_parts:
        warnings.append(
            f'{missing_printed} line(s): printed barcode not read — re-import or enter barcode manually.'
        )
    extracted = {**extracted, 'lines': lines_in}
    raw_lines_after_merge = len(lines_in)
    if text_serial_count >= 20 and raw_lines_after_merge < int(text_serial_count * 0.6):
        warnings.append(
            f'Only {raw_lines_after_merge} line(s) imported vs ~{text_serial_count} serials in PDF text — '
            'verify all pages were included or re-import.'
        )
    raw_lines_for_brands: List[Dict[str, Any]] = [dict(x) for x in lines_in if isinstance(x, dict)]
    out_lines: List[Dict[str, Any]] = []
    unmatched_lines: List[Dict[str, Any]] = []
    loc_code = _resolve_location_code()
    brand_rows = get_categories('B', location_code=loc_code) or get_categories('B') or []
    unmatched_brand_map: Dict[str, Dict[str, str]] = {}

    def _grn_register_unmatched_brand_for_line(label: str, source: str) -> None:
        t = (label or '').strip()
        if not t:
            return
        nk = _grn_normalize_name(t)
        if not nk or nk in unmatched_brand_map:
            return
        unmatched_brand_map[nk] = {'name': t[:120], 'source': source}
        warnings.append(f'Brand on invoice not in master: {t[:80]}' if source == 'invoice' else f'AI-suggested brand not in master: {t[:80]}')
    enriched_lines: List[Dict[str, Any]] = []
    for row in lines_in:
        if not isinstance(row, dict):
            continue
        erow = dict(row)
        b_raw = str(erow.get('brand') or '').strip()
        b_sug = str(erow.get('suggested_brand') or '').strip()
        cands: List[Tuple[str, str]] = []
        if b_raw:
            cands.append((b_raw, 'invoice'))
        if b_sug and (not b_raw or _grn_normalize_name(b_sug) != _grn_normalize_name(b_raw)):
            cands.append((b_sug, 'suggested'))
        tried: Set[str] = set()
        b_rec: Optional[Dict[str, Any]] = None
        match_source: Optional[str] = None
        for ctext, msrc in cands:
            cn = _grn_normalize_name(ctext)
            if not cn or cn in tried:
                continue
            tried.add(cn)
            br, _, _ = _grn_match_brand_name(ctext, brand_rows)
            if br:
                b_rec, match_source = (br, msrc)
                break
        if b_rec:
            erow['brand_matched'] = True
            erow['brand_master_name'] = str(b_rec.get('name') or '').strip()
            try:
                erow['brand_master_code'] = int(float(b_rec.get('code')))
            except (TypeError, ValueError):
                erow['brand_master_code'] = b_rec.get('code')
            if match_source == 'suggested':
                erow['brand_matched_from_suggested'] = True
        elif cands:
            erow['brand_matched'] = False
            for ctext, msrc in cands:
                _grn_register_unmatched_brand_for_line(ctext, msrc)
        else:
            erow['brand_matched'] = None
        enriched_lines.append(_grn_normalize_ai_invoice_line(erow))
    lines_in = enriched_lines
    extracted = {**extracted, 'lines': lines_in}
    # Photo imports rely on image OCR; kept only as an informational note (no blanking).
    has_reliable_text = bool(tp) and len(tp) >= 40
    photo_only_import = bool(image_parts) and not has_reliable_text
    # Guard against two different products collapsing onto the same item (OCR/barcode collision):
    # an item code already used by an earlier line may only repeat for a clearly-similar product.
    used_item_codes: Dict[str, str] = {}
    code_to_ser = _grn_build_item_code_serial_index(
        table_row_map, text_row_map, prebuilt_table_map, text=tp,
    )
    desc_to_ser = _grn_build_description_serial_index(
        table_row_map, text_row_map, prebuilt_table_map,
    )
    for row_idx, row in enumerate(lines_in):
        if not isinstance(row, dict):
            continue
        desc = str(row.get('description') or '').strip()
        ic = row.get('item_code')
        qty = float(row.get('quantity') or 0) or 0.0
        uom = str(row.get('uom') or 'NOS').strip() or 'NOS'
        unit_p = float(row.get('unit_price') or 0) or 0.0
        line_disc = float(row.get('line_discount') or 0) or 0.0
        line_tot = float(row.get('line_total') or 0) or 0.0
        is_foc = bool(row.get('is_foc'))
        inv_ser = _grn_resolve_line_invoice_serial(row, code_to_ser, desc_to_ser, row_idx + 1)
        if (
            qty <= 0 and line_tot <= 0 and (not desc)
            and not inv_ser and not _grn_printed_barcode_from_row(row)
        ):
            continue
        it, msc = _grn_resolve_item_for_ai_import(
            row, items, loc_code, supplier_strong, barcode_index, barcode_sql_cache,
        )
        # Reject a duplicate match: same item already taken by an earlier line whose product
        # name is clearly different (likely a misread barcode shared across two products).
        if it:
            cand_code = str(it.get('code') or '').strip()
            prev_desc = used_item_codes.get(cand_code)
            if cand_code and prev_desc is not None:
                a = _grn_normalize_name(prev_desc)
                b = _grn_normalize_name(desc)
                sim = SequenceMatcher(None, a, b).ratio() if (a and b) else 0.0
                if sim < 0.6:
                    warnings.append(
                        f"Duplicate item match ignored: '{desc[:60] or '(empty)'}' resolved to the same "
                        f"item as '{prev_desc[:60]}' — left unmatched (check the barcode)."
                    )
                    it, msc = None, 0.0
        inv_bc_u = _grn_printed_barcode_from_row(row)
        inv_code_str = ''
        amt = line_tot if line_tot > 0 else 0.0 if is_foc else max(0.0, qty * unit_p - line_disc)
        rq = qty if qty > 0 else 0.0
        if rq <= 0 and amt > 0 and (unit_p > 0):
            rq = amt / unit_p
        inv_batch = str(row.get('batch_no') or row.get('batch') or row.get('batch_number') or row.get('lot') or '').strip()
        inv_mfg = str(row.get('mfg_date') or row.get('mfg') or row.get('manufacturing_date') or '').strip()
        inv_exp = str(row.get('expiry_date') or row.get('expiry') or row.get('exp') or '').strip()
        if inv_mfg and len(inv_mfg) >= 10:
            inv_mfg = inv_mfg[:10]
        else:
            inv_mfg = ''
        if inv_exp and len(inv_exp) >= 10:
            inv_exp = inv_exp[:10]
        else:
            inv_exp = ''
        if not it:
            urow: Dict[str, Any] = {
                'serial': inv_ser,
                'description': desc, 'quantity': qty, 'uom': uom, 'unit_price': unit_p,
                'line_discount': line_disc, 'line_total': line_tot, 'is_foc': is_foc,
            }
            if inv_bc_u:
                urow['barcode'] = inv_bc_u
                urow['printed_barcode'] = inv_bc_u
            b_inv = str(row.get('brand') or '').strip()
            if b_inv:
                urow['brand'] = b_inv
            b_sug_u = str(row.get('suggested_brand') or '').strip()
            if b_sug_u:
                urow['suggested_brand'] = b_sug_u
            unmatched_lines.append(urow)
            if inv_bc_u:
                warnings.append(f"No item for printed code {inv_bc_u}: {desc[:80] or '(empty)'}")
            elif supplier_strong:
                warnings.append(f"No item match (code or ≥{int(GRN_AI_ITEM_NAME_STRONG_MIN * 100)}% name vs item master): {desc[:80] or '(empty)'}")
            else:
                warnings.append(f"No item match for line: {desc[:80] or '(empty)'}")
            # Not a 100% Item Code match: leave barcode blank; show Item Code read as hint only.
            read_bc = _grn_grid_barcode_from_invoice(row, '')
            display_name = desc or read_bc
            line_obj_um: Dict[str, Any] = {
                'serial': inv_ser,
                'invoice_serial': inv_ser,
                'itemcode': '',
                'itemname': display_name,
                'invoice_description': desc[:500] if desc else '',
                'barcode': '',
                'printed_barcode': None,
                'ai_read_barcode': read_bc or None,
                'printed_barcode_source': str(row.get('printed_barcode_source') or '').strip() or None,
                'uom': uom,
                'qty': qty,
                'receivedqty': rq,
                'rate': unit_p,
                'discount': line_disc,
                'foc': is_foc,
                'amount': amt,
                'othercharge': 0.0,
                'location': '',
                'match_score': 0.0,
                'item_not_in_master': True,
                'name_candidates': _grn_name_candidates(desc, items, 8),
                'batch_no': inv_batch,
                'mfg_date': inv_mfg,
                'expiry_date': inv_exp,
            }
            out_lines.append(line_obj_um)
            continue
        code_s = str(it.get('code') or '').strip()
        iname = str(it.get('name') or '').strip()
        master_bc = str(it.get('barcode') or '').strip()
        inv_bc_u = _grn_printed_barcode_from_row(row) or inv_bc_u
        matched_by_barcode = (str(it.get('__match_kind__') or '') == 'barcode')
        if matched_by_barcode:
            # Exact MANUFACTURERID hit: show the printed code we fetched (it equals the match).
            barcode = inv_bc_u or master_bc
        else:
            # Matched by name/near: the printed code is an unreliable OCR read — show the
            # authoritative item-master barcode so the grid is correct (e.g. photo misreads).
            barcode = master_bc or inv_bc_u
        uom = (str(it.get('uom') or '').strip() or 'NOS')
        master_retail = float(it.get('retail') or 0)
        display_name = iname or barcode
        if not str(row.get('brand') or '').strip() and row.get('brand_matched') is None:
            b_hit = _grn_find_brand_name_in_text(f'{iname} {desc}', brand_rows)
            if b_hit:
                row['brand_matched'] = True
                row['brand_master_name'] = str(b_hit.get('name') or '').strip()
                try:
                    row['brand_master_code'] = int(float(b_hit.get('code')))
                except (TypeError, ValueError):
                    row['brand_master_code'] = b_hit.get('code')
                row['brand_from_item_name'] = True
        loc = ''
        if resolve_line_locs:
            if code_s in item_location_cache:
                loc = item_location_cache[code_s]
            else:
                locs, _ = _get_receive_locations_for_item(code_s, location_code=loc_code)
                if locs:
                    loc = str(locs[0].get('code') or '').strip()
                item_location_cache[code_s] = loc
        match_method = 'barcode_db' if matched_by_barcode else ('name' if msc > 0 else '')
        line_obj: Dict[str, Any] = {
            'serial': inv_ser,
            'invoice_serial': inv_ser,
            'itemcode': code_s, 'itemname': display_name, 'barcode': barcode, 'uom': uom,
            'retail': master_retail, 'qty': qty, 'receivedqty': rq, 'rate': unit_p,
            'discount': line_disc, 'foc': is_foc, 'amount': amt, 'othercharge': 0.0, 'location': loc,
            'match_score': round(msc, 3), 'match_method': match_method,
            'batch_no': inv_batch, 'mfg_date': inv_mfg, 'expiry_date': inv_exp,
        }
        # Grid shows `barcode` (printed code on a barcode hit; item-master barcode on a name hit).
        line_obj['printed_barcode'] = barcode
        if inv_bc_u and inv_bc_u != barcode:
            line_obj['ocr_barcode'] = inv_bc_u
        bsrc = str(row.get('printed_barcode_source') or '').strip()
        if bsrc:
            line_obj['printed_barcode_source'] = bsrc
        if master_bc:
            line_obj['master_barcode'] = master_bc
        if desc and iname and _grn_normalize_name(desc) != _grn_normalize_name(iname):
            line_obj['invoice_description'] = desc[:500]
        out_lines.append(line_obj)
        if code_s:
            used_item_codes.setdefault(code_s, desc)
    if photo_only_import:
        warnings.append(
            'Photo import: barcodes are read by image OCR. The grid shows the printed code exactly as read — '
            'verify it against the product before saving.'
        )
    next_grn_no = _receipt_next_no()
    trans_dt_str = (_get_transaction_date_receipt() or '')[:10]
    exp_default = ''
    if trans_dt_str and len(trans_dt_str) >= 10:
        try:
            d0 = datetime.strptime(trans_dt_str[:10], '%Y-%m-%d') + timedelta(days=365)
            exp_default = d0.strftime('%Y-%m-%d')
        except Exception:
            exp_default = ''
    for idx, ln in enumerate(out_lines, start=1):
        if ln.get('item_not_in_master'):
            continue
        try:
            ic = int(float(str(ln.get('itemcode') or '').strip()))
        except (TypeError, ValueError):
            continue
        if str(ln.get('batch_no') or '').strip():
            continue
        if not is_item_batch_tracked(ic, loc_code):
            continue
        ln['batch_no'] = f'AUTO-G{next_grn_no}-L{idx}-I{ic}'[:80]
        if exp_default and (not str(ln.get('expiry_date') or '').strip()):
            ln['expiry_date'] = exp_default
    if out_lines:
        out_lines.sort(
            key=lambda ln: int(ln.get('invoice_serial') or ln.get('serial') or 0),
        )
    if out_lines and fill_max_hint >= 20:
        ser_vals = [int(ln.get('invoice_serial') or ln.get('serial') or 0) for ln in out_lines]
        ser_vals = [s for s in ser_vals if s > 0]
        if ser_vals and max(ser_vals) <= len(ser_vals) + 2 and min(ser_vals) <= 3:
            warnings.append(
                'Printed S. No. may still be wrong (showing 1,2,3…) — re-import all pages in order '
                'or check import report Ser. column.'
            )
    if sup_row is None and sup_name:
        warnings.append(f'Supplier not matched automatically: {sup_name[:120]}. Please select manually.')
    sup_tax = str(extracted.get('supplier_tax_id') or '').strip()
    buyer_on_inv = str(extracted.get('buyer_name') or '').strip()
    sup_master_name = str(sup_row.get('name') or '').strip() if sup_row else ''
    n_sup_inv = _grn_normalize_name(sup_name)
    n_sup_mst = _grn_normalize_name(sup_master_name)
    supplier_name_exact_match = bool(sup_row and n_sup_inv and n_sup_mst and (n_sup_inv == n_sup_mst))
    upload_names = ', '.join((fn or 'upload') for _, fn in file_blobs[:5])
    if len(file_blobs) > 5:
        upload_names += f' (+{len(file_blobs) - 5} more)'
    match_sec = round(time.time() - t_match0, 1)
    barcode_audit: List[Dict[str, Any]] = []
    for idx, row in enumerate(lines_in):
        if not isinstance(row, dict):
            continue
        ser = _grn_line_serial_from_row(row, idx + 1)
        bc_row = _grn_printed_barcode_from_row(row)
        barcode_audit.append({
            'grid_slno': idx + 1,
            'serial': ser,
            'barcode': bc_row,
            'source': str(row.get('printed_barcode_source') or '').strip(),
            'from_table_serial': printed_by_serial.get(ser) or '',
            'table_source': serial_source.get(ser) or '',
            'description': str(row.get('description') or '')[:80],
        })
    import_report: Dict[str, Any] = {
        'barcode_audit': barcode_audit,
        'photo_only_import': photo_only_import,
        'printed_barcodes_by_serial': {str(k): v for k, v in sorted(printed_by_serial.items())},
        'supplier_matched': sup_row is not None, 'supplier_strong': supplier_strong,
        'supplier_match_threshold': GRN_AI_SUPPLIER_STRONG_THRESHOLD,
        'item_name_match_threshold': GRN_AI_ITEM_NAME_STRONG_MIN,
        'extracted_supplier_name': sup_name, 'extracted_buyer_name': buyer_on_inv,
        'extracted_supplier_tax_id': sup_tax, 'matched_supplier_master_name': sup_master_name,
        'supplier_name_exact_match': supplier_name_exact_match,
        'unmatched_lines': unmatched_lines, 'matched_lines_count': len(out_lines),
        'unmatched_lines_count': len(unmatched_lines),
        'unmatched_brands': [unmatched_brand_map[k] for k in sorted(unmatched_brand_map.keys(), key=str.lower)],
        'brand_match_threshold': GRN_AI_SUPPLIER_STRONG_THRESHOLD,
        'suggested_brands_unique': _grn_unique_nonempty_line_strings(raw_lines_for_brands, 'suggested_brand'),
        'invoice_brands_unique': _grn_unique_nonempty_line_strings(raw_lines_for_brands, 'brand'),
        'invoice_files_count': len(file_blobs), 'invoice_pages_sent_to_ai': len(image_parts),
        'invoice_max_pages': _grn_ai_invoice_max_pages(),
        'ai_lines_first_pass': line_count_initial,
        'ai_lines_after_merge': raw_lines_after_merge,
        'text_serials_detected': text_serial_count,
        'quotation_fill_max': fill_max_hint,
        'text_dominant_extract': text_dominant_done,
        'table_rows_detected': len(table_row_map),
        'unique_serials_imported': raw_lines_after_merge,
        'ai_finish_reason': ai_finish_reason or None,
        'ai_model': ai_model, 'ai_extract_seconds': extract_sec, 'match_seconds': match_sec,
        'total_seconds': round(extract_sec + match_sec, 1),
    }
    sup_code_val: Optional[int] = None
    if sup_row and sup_row.get('code') is not None:
        try:
            sup_code_val = int(float(sup_row.get('code')))
        except (TypeError, ValueError):
            sup_code_val = None
    if sup_row and sup_kind == 'fuzzy' and sup_name:
        sup_disp = f'{sup_code_val} - {sup_name}' if sup_code_val is not None else f"{sup_row.get('code')} - {sup_name}"
    else:
        sup_disp = f'{sup_code_val} - {sup_master_name}' if sup_row and sup_code_val is not None else f"{sup_row.get('code')} - {sup_master_name}" if sup_row else ''
    header = {'suppliercode': sup_code_val, 'supplier_display': sup_disp, 'supplier_name_master': sup_master_name if sup_kind == 'fuzzy' and sup_master_name else None, 'supplier_match': sup_kind, 'supplier_match_score': round(sup_sc, 3) if sup_row else None, 'buyer_name_on_invoice': buyer_on_inv or None, 'invoiceno': inv_no, 'invoicedate': inv_date, 'discount': disc_total, 'invoiceamount': total_inv, 'remarks': f'AI import from supplier invoice ({upload_names})'[:500]}
    invoice_preview_images = _grn_invoice_preview_payload_from_uploads(file_blobs)
    if incremental_import:
        job_id_fin = (request.form.get('job_id') or '').strip()
        with _GRN_AI_INVOICE_JOBS_LOCK:
            _GRN_AI_INVOICE_JOBS.pop(job_id_fin, None)
    return jsonify({'success': True, 'extracted': extracted, 'header': header, 'lines': out_lines, 'warnings': warnings, 'import_report': import_report, 'invoice_preview_images': invoice_preview_images})

@bp.route('/purchase/receipt/api/refresh-save-nonce', methods=['GET'])
def api_receipt_refresh_save_nonce():
    """Issue a fresh global save token (e.g. after stale tab / replay-blocked GRN save)."""
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    return jsonify({'success': True, 'save_nonce': issue_save_nonce(GLOBAL_SAVE_NONCE_SESSION_KEY)})

@bp.route('/purchase/receipt/api/save', methods=['POST'])
def api_receipt_save():
    if not session.get('user'):
        _grn_save_audit('SAVE deny_not_authenticated')
        return jsonify({'error': 'Not authenticated'}, 401)
    _apply_db()
    ensure_receiptno_varchar_columns()
    ensure_purchase_approval_docno_varchar()
    if not _grn_receipt_try_acquire_session_lock():
        _grn_save_audit('SAVE blocked_session_lock_busy | %s', _grn_save_audit_ctx())
        return json_response_keep_global_nonce({'success': False, 'error': 'A GRN save is already in progress for this session. Please wait until it completes.', 'save_session_locked': True}, 423)
    try:
        submitted_nonce = extract_submitted_save_nonce(request)
        if not reject_invalid_form_save_nonce(submitted_nonce, session_key=GLOBAL_SAVE_NONCE_SESSION_KEY):
            _grn_save_audit('SAVE blocked_replay_or_bad_nonce | %s', _grn_save_audit_ctx())
            return replay_blocked_response_global()
        data = request.get_json(silent=True) or {}
        receipt_no = parse_receiptno_from_request(data.get('receiptno'))
        receipt_date = (data.get('receiptdate') or '')[:10]
        posting_date = (data.get('postingdate') or data.get('posting_date') or receipt_date or '')[:10]
        open_date, txn_err = _enforce_purchase_open_date(receipt_date, 'grn')
        if txn_err:
            _grn_save_audit('SAVE blocked_no_open_txn_date | %s', _grn_save_audit_ctx())
            return json_response_keep_global_nonce(
                {'success': False, 'error': txn_err, 'transaction_date_blocked': True},
                400,
            )
        receipt_date = open_date or receipt_date
        if posting_date:
            open_pd, pd_err = _enforce_purchase_open_date(posting_date, 'grn')
            if pd_err:
                return json_response_keep_global_nonce(
                    {'success': False, 'error': f'Posting date: {pd_err}', 'transaction_date_blocked': True},
                    400,
                )
            posting_date = open_pd or posting_date
        else:
            posting_date = receipt_date
        supplier_code = int(data.get('suppliercode') or 0)
        invoice_no = (data.get('invoiceno') or '').strip()
        invoice_date = (data.get('invoicedate') or '')[:10]
        discount = float(data.get('discount') or 0)
        invoice_amount = float(data.get('invoiceamount') or 0)
        header_other_charge = float(data.get('othercharge') or 0)
        remarks = (data.get('remarks') or '').strip()
        save_mode = (data.get('save_mode') or 'grn_invoice_posting').strip().lower()
        if save_mode not in ('grn_only', 'grn_draft', 'grn_invoice_posting'):
            save_mode = 'grn_invoice_posting'
        post_inventory_raw = data.get('post_inventory')
        if post_inventory_raw is not None:
            if isinstance(post_inventory_raw, str):
                post_inventory = post_inventory_raw.strip().lower() not in ('0', 'false', 'no', '')
            else:
                post_inventory = bool(post_inventory_raw)
        elif save_mode == 'grn_draft':
            post_inventory = False
        elif save_mode == 'grn_invoice_posting':
            post_inventory = True
        else:
            post_inventory = True
        lpo_no = data.get('lpono')
        if lpo_no is not None and str(lpo_no).strip() != '':
            lpo_no = parse_lpono_from_request(lpo_no)
            if not lpono_is_valid(lpo_no):
                    lpo_no = None
        else:
                lpo_no = None
        lines = data.get('lines') or []
        wh_raw = data.get('warehouse_id')
        warehouse_id: Optional[int] = None
        if wh_raw not in (None, ''):
            try:
                warehouse_id = int(wh_raw)
                if warehouse_id <= 0:
                    warehouse_id = None
            except (TypeError, ValueError):
                warehouse_id = None
        invoice_snapshot_json: Optional[str] = None
        snap_payload = data.get('invoice_snapshot_pages')
        if isinstance(snap_payload, list) and snap_payload:
            try:
                invoice_snapshot_json = json.dumps(snap_payload, ensure_ascii=False)
            except Exception:
                invoice_snapshot_json = None
        elif isinstance(snap_payload, str) and snap_payload.strip():
            invoice_snapshot_json = snap_payload.strip()
        if invoice_snapshot_json and len(invoice_snapshot_json) > 11800000:
            invoice_snapshot_json = invoice_snapshot_json[:11800000]
        if not receiptno_is_valid(receipt_no) or not receipt_date or (not supplier_code):
            _grn_save_audit('SAVE fail_validation receipt_no/supplier/date | receipt_no=%s supplier=%s | %s', receipt_no, supplier_code, _grn_save_audit_ctx())
            return json_response_keep_global_nonce({'success': False, 'error': 'Receipt No, Date and Supplier are required'}, 400)
        if not invoice_no or not invoice_date:
            _grn_save_audit('SAVE fail_validation invoice receipt_no=%s supplier=%s | %s', receipt_no, supplier_code, _grn_save_audit_ctx())
            return json_response_keep_global_nonce({'success': False, 'error': 'Invoice No and Date are required'}, 400)
        for idx, ln in enumerate(lines, 1):
            item_raw = ln.get('itemcode') or ln.get('item_code')
            if str(item_raw or '').strip() and _coerce_grn_item_code(item_raw) is None:
                _grn_save_audit('SAVE fail_validation invalid_item line=%s receipt_no=%s | %s', idx, receipt_no, _grn_save_audit_ctx())
                return json_response_keep_global_nonce({'success': False, 'error': f'Line {idx}: invalid item code ({item_raw!r}). Enter a numeric item code.'}, 400)
        if not _grn_valid_save_lines(lines):
            _grn_save_audit('SAVE fail_validation no_lines receipt_no=%s supplier=%s | %s', receipt_no, supplier_code, _grn_save_audit_ctx())
            return json_response_keep_global_nonce({'success': False, 'error': 'Add at least one GRN line with a valid item code before saving.'}, 400)
        for idx, ln in enumerate(lines, 1):
            inv_loc = _line_warehouse_code_from_payload(ln, warehouse_id)
            if not inv_loc:
                _grn_save_audit('SAVE fail_validation missing_inv_location line=%s receipt_no=%s | %s', idx, receipt_no, _grn_save_audit_ctx())
                return json_response_keep_global_nonce({'success': False, 'error': f'Inventory Location required at line {idx}. Select header Warehouse (F1) or set receive store on the line.'}, 400)
            ln['location'] = inv_loc
            ln['warehouse_code'] = inv_loc
            if not ln.get('inventorylocation'):
                ln['inventorylocation'] = inv_loc
        requested_no = receipt_no
        receipt_no, receipt_reassigned = _resolve_receipt_no_for_save(requested_no, supplier_code, invoice_no, invoice_date)
        if not receipt_reassigned and receiptno_is_valid(requested_no) and _receipt_no_exists_in_hdr(requested_no):
            if _grn_is_account_posted(requested_no):
                _grn_save_audit('SAVE blocked_account_posted receipt_no=%s | %s', requested_no, _grn_save_audit_ctx())
                return json_response_keep_global_nonce({
                    'success': False,
                    'error': 'This GRN is posted to accounts (Purchase Invoice). It cannot be changed.',
                    'account_posted': True,
                }, 400)
            if _grn_is_inventory_posted(requested_no):
                _grn_save_audit('SAVE blocked_inventory_posted receipt_no=%s | %s', requested_no, _grn_save_audit_ctx())
                return json_response_keep_global_nonce({
                    'success': False,
                    'error': 'This GRN is posted to stock. Only draft GRNs can be edited.',
                    'inventory_posted': True,
                }, 400)
        editing_existing = (
            not receipt_reassigned
            and receiptno_is_valid(requested_no)
        )
        existing_header = _get_receipt_header_for_posting(requested_no) if editing_existing else None
        editing_existing = editing_existing and existing_header is not None
        before_snap = None
        if editing_existing:
            before_snap = _audit_grn_snapshot(
                existing_header,
                _get_receipt_details(requested_no),
            )
        dup_no = None
        if not editing_existing or receipt_reassigned:
            dup_extras = [requested_no] if (receiptno_is_valid(requested_no) and not receiptno_equal(requested_no, receipt_no)) else None
            dup_no = _receipt_find_duplicate_supplier_invoice(
                supplier_code, invoice_no, receipt_no, also_except=dup_extras,
            )
        if dup_no is not None:
            _grn_save_audit('SAVE fail_duplicate_invoice dup_grn=%s receipt_no=%s supplier=%s invoice=%r | %s', dup_no, receipt_no, supplier_code, invoice_no, _grn_save_audit_ctx())
            return json_response_keep_global_nonce({'success': False, 'error': f'The same invoice number is already saved for this supplier (GRN {dup_no}).', 'duplicate_receiptno': dup_no}, 400)
        ai_snap = bool(invoice_snapshot_json and str(invoice_snapshot_json).strip())
        _grn_save_audit(
            'SAVE attempt receipt_no=%s requested_no=%s supplier=%s invoice=%r date=%s lines=%d amt=%s lpo=%s ai_snap=%s | %s',
            receipt_no, requested_no, supplier_code, invoice_no, invoice_date[:10], len(lines), invoice_amount, lpo_no, ai_snap, _grn_save_audit_ctx(),
        )
        effective_save_mode = 'grn_draft' if not post_inventory else save_mode
        err: Optional[str] = None
        for _dup_try in range(8):
            err = _save_receipt(
                receipt_no, receipt_date, supplier_code, invoice_no, invoice_date, discount, invoice_amount,
                remarks, lpo_no, lines, save_mode=effective_save_mode, approve_mode=save_mode,
                invoice_snapshot_json=invoice_snapshot_json, warehouse_id=warehouse_id,
                header_other_charge=header_other_charge, post_inventory=post_inventory,
                posting_date=posting_date,
            )
            if not err:
                break
            err_l = str(err).lower()
            if 'duplicate key' not in err_l and 'pk_receipthdr' not in err_l and 'already in use' not in err_l:
                break
            retry_no = _allocate_next_free_receipt_no(receipt_no)
            if billno_numeric_part(retry_no) <= billno_numeric_part(receipt_no):
                retry_no = coerce_receiptno(billno_numeric_part(receipt_no) + 1)
                while _receipt_no_exists_in_hdr(retry_no) and billno_numeric_part(retry_no) < billno_numeric_part(receipt_no) + 100:
                    retry_no = coerce_receiptno(billno_numeric_part(retry_no) + 1)
            if retry_no == receipt_no or receiptno_equal(retry_no, receipt_no):
                break
            _grn_save_audit(
                'SAVE retry_after_dup receipt_no=%s -> %s supplier=%s | %s',
                receipt_no, retry_no, supplier_code, _grn_save_audit_ctx(),
            )
            receipt_no = retry_no
            receipt_reassigned = True
        if err:
            _grn_save_audit('SAVE fail_db receipt_no=%s supplier=%s err=%r | %s', receipt_no, supplier_code, err, _grn_save_audit_ctx())
            dup_key = 'duplicate key' in str(err).lower()
            body: Dict[str, Any] = {'success': False, 'error': err}
            if dup_key:
                body['duplicate_receipt_key'] = True
                body['next_receiptno'] = _receipt_next_no()
                body['suggested_receiptno'] = _allocate_next_free_receipt_no(receipt_no)
            return json_response_keep_global_nonce(body, 400)
        if not commit_form_save_nonce(submitted_nonce, session_key=GLOBAL_SAVE_NONCE_SESSION_KEY):
            _grn_save_audit('SAVE blocked_replay_or_bad_nonce_at_commit | %s', _grn_save_audit_ctx())
            return replay_blocked_response_global()
        upd_counts = getattr(_save_receipt, '_last_update_counts', {}) or {}
        im_upd = int(upd_counts.get('itemmaster_rows') or 0)
        alt_upd = int(upd_counts.get('alt_uom_rows') or 0)
        if post_inventory:
            if save_mode == 'grn_invoice_posting':
                msg = 'GRN saved and posted (stock + purchase invoice / AP).'
                if receipt_reassigned:
                    msg = f'GRN number {requested_no} was already in use. Saved as GRN {receipt_no} and posted (stock + purchase invoice / AP).'
            else:
                msg = 'GRN saved. Stock and item journal updated. Use purchase invoice for accounting when needed.'
                if receipt_reassigned:
                    msg = f'GRN number {requested_no} was already in use. Saved as GRN {receipt_no}. Stock and item journal updated. Use purchase invoice for accounting when needed.'
        else:
            msg = 'GRN saved as draft. Stock is not posted yet — open the GRN and choose Approve & post Inventory Only or POST inventory and Accounts when ready.'
            if receipt_reassigned:
                msg = f'GRN number {requested_no} was already in use. Saved as GRN {receipt_no} (draft). Stock is not posted yet.'
        _grn_save_audit(
            'SAVE ok receipt_no=%s requested_no=%s reassigned=%s supplier=%s invoice=%r amt=%s lines=%d itemmaster_updates=%s alt_uom_updates=%s | %s',
            receipt_no, requested_no, receipt_reassigned, supplier_code, invoice_no, invoice_amount, len(lines), im_upd, alt_upd, _grn_save_audit_ctx(),
        )
        _lpo_list_count_cache_invalidate_grn_lists(_resolve_location_code())
        try:
            with _get_connection() as conn:
                with conn.cursor() as cur:
                    from addons.document_numbering.document_numbering_db import advance_document_series_after_save_cur
                    advance_document_series_after_save_cur(
                        cur, DOC_TYPE_GRN, receipt_no,
                        location_code=_resolve_location_code(),
                        reset_no=RESET_NO,
                        user=str(session.get('user') or 'web'),
                    )
                conn.commit()
        except Exception:
            pass
        if editing_existing and not receipt_reassigned:
            after_snap = _audit_grn_snapshot_from_save(
                receipt_date, supplier_code, invoice_no, invoice_date, invoice_amount, discount, remarks, lines,
                other_charge=header_other_charge, lpo_no=lpo_no, warehouse_id=warehouse_id,
            )
            _log_purchase_change(
                'GRN', receipt_no, 'EDIT',
                remarks or 'GRN updated',
                before=before_snap,
                after=after_snap,
            )
        return json_response_rotate_global({
            'success': True,
            'receiptno': receipt_no,
            'requested_receiptno': requested_no,
            'receiptno_reassigned': receipt_reassigned,
            'next_receiptno': _receipt_next_no(),
            'message': msg,
            'save_mode': effective_save_mode,
            'inventory_posted': bool(post_inventory),
            'update_counts': {'itemmaster_rows': im_upd, 'alt_uom_rows': alt_upd},
            'account_postings': getattr(_save_receipt, '_last_posting_summary', None),
            'pdf_url': url_for('purchase.api_receipt_pdf', receipt_no=receipt_no),
        })
    except Exception as ex:
        _grn_save_audit('SAVE unhandled_exception %s: %s | %s', type(ex).__name__, ex, _grn_save_audit_ctx())
        raise
    finally:
        _grn_receipt_release_session_lock()

@bp.route('/purchase/receipt/api/post-inventory', methods=['POST'])
def api_receipt_post_inventory():
    """Post stock, lots, and item journal for an existing draft GRN."""
    if not session.get('user'):
        return jsonify({'error': 'Not authenticated'}, 401)
    _apply_db()
    ensure_receiptno_varchar_columns()
    ensure_purchase_approval_docno_varchar()
    if not _grn_receipt_try_acquire_session_lock():
        return json_response_keep_global_nonce({
            'success': False,
            'error': 'A GRN operation is already in progress for this session. Please wait.',
            'save_session_locked': True,
        }, 423)
    try:
        submitted_nonce = extract_submitted_save_nonce(request)
        if not reject_invalid_form_save_nonce(submitted_nonce, session_key=GLOBAL_SAVE_NONCE_SESSION_KEY):
            return replay_blocked_response_global()
        data = request.get_json(silent=True) or {}
        receipt_no = parse_receiptno_from_request(data.get('receiptno'))
        if not receiptno_is_valid(receipt_no):
            return json_response_keep_global_nonce({'success': False, 'error': 'Receipt No is required'}, 400)
        if _grn_is_account_posted(receipt_no):
            return json_response_keep_global_nonce({
                'success': False,
                'error': 'This GRN is posted to accounts and cannot be changed.',
                'account_posted': True,
            }, 400)
        if _grn_is_inventory_posted(receipt_no):
            return json_response_keep_global_nonce({
                'success': False,
                'error': 'Inventory is already posted for this GRN.',
                'inventory_posted': True,
            }, 400)
        hdr = _get_receipt_header_for_posting(receipt_no)
        if not hdr:
            return json_response_keep_global_nonce({'success': False, 'error': 'GRN not found'}, 404)
        body_lines = data.get('lines')
        if isinstance(body_lines, list) and body_lines:
            lines = body_lines
            for idx, ln in enumerate(lines, 1):
                wh_raw = data.get('warehouse_id')
                wh_id: Optional[int] = None
                if wh_raw not in (None, ''):
                    try:
                        wh_id = int(wh_raw)
                        if wh_id <= 0:
                            wh_id = None
                    except (TypeError, ValueError):
                        wh_id = None
                inv_loc = _line_warehouse_code_from_payload(ln, wh_id)
                if not inv_loc:
                    return json_response_keep_global_nonce({
                        'success': False,
                        'error': f'Inventory Location required at line {idx}.',
                    }, 400)
                ln['location'] = inv_loc
                ln['warehouse_code'] = inv_loc
                if not ln.get('inventorylocation'):
                    ln['inventorylocation'] = inv_loc
            receipt_date = (data.get('receiptdate') or hdr.get('receiptdate') or '')[:10]
            supplier_code = int(data.get('suppliercode') or hdr.get('suppliercode') or 0)
            invoice_no = (data.get('invoiceno') or hdr.get('invoiceno') or '').strip()
            invoice_date = (data.get('invoicedate') or hdr.get('invoicedate') or '')[:10]
            discount = float(data.get('discount') if data.get('discount') is not None else hdr.get('discount') or 0)
            invoice_amount = float(data.get('invoiceamount') if data.get('invoiceamount') is not None else hdr.get('invoiceamount') or 0)
            remarks = (data.get('remarks') if data.get('remarks') is not None else hdr.get('remarks') or '').strip()
            lpo_no = data.get('lpono') if data.get('lpono') is not None else hdr.get('lpono')
            if lpo_no is not None:
                lpo_no = parse_lpono_from_request(lpo_no)
                if not lpono_is_valid(lpo_no):
                    lpo_no = None
            header_other_charge = float(data.get('othercharge') if data.get('othercharge') is not None else hdr.get('othercharge') or 0)
            wh_raw = data.get('warehouse_id')
            warehouse_id: Optional[int] = None
            if wh_raw not in (None, ''):
                try:
                    warehouse_id = int(wh_raw)
                    if warehouse_id <= 0:
                        warehouse_id = None
                except (TypeError, ValueError):
                    warehouse_id = None
            if warehouse_id is None and hdr.get('warehouse_id') not in (None, ''):
                try:
                    warehouse_id = int(hdr.get('warehouse_id'))
                    if warehouse_id <= 0:
                        warehouse_id = None
                except (TypeError, ValueError):
                    warehouse_id = None
        else:
            details = _get_receipt_details(receipt_no)
            if not details:
                return json_response_keep_global_nonce({'success': False, 'error': 'GRN has no lines'}, 400)
            lines = _grn_lines_payload_from_details(details)
            receipt_date = str(hdr.get('receiptdate') or '')[:10]
            supplier_code = int(hdr.get('suppliercode') or 0)
            invoice_no = str(hdr.get('invoiceno') or '').strip()
            invoice_date = str(hdr.get('invoicedate') or '')[:10]
            discount = float(hdr.get('discount') or 0)
            invoice_amount = float(hdr.get('invoiceamount') or 0)
            remarks = str(hdr.get('remarks') or '').strip()
            lpo_no = hdr.get('lpono')
            if lpo_no is not None:
                lpo_no = parse_lpono_from_request(lpo_no)
                if not lpono_is_valid(lpo_no):
                    lpo_no = None
            header_other_charge = float(hdr.get('othercharge') or 0)
            warehouse_id = None
            if hdr.get('warehouse_id') not in (None, ''):
                try:
                    warehouse_id = int(hdr.get('warehouse_id'))
                    if warehouse_id <= 0:
                        warehouse_id = None
                except (TypeError, ValueError):
                    warehouse_id = None
        if not receipt_date or not supplier_code or not invoice_no or not invoice_date:
            return json_response_keep_global_nonce({'success': False, 'error': 'Receipt header is incomplete'}, 400)
        before_snap = _audit_grn_snapshot(hdr, lines)
        _grn_save_audit('POST_INVENTORY attempt receipt_no=%s lines=%d | %s', receipt_no, len(lines), _grn_save_audit_ctx())
        err = _save_receipt(
            receipt_no, receipt_date, supplier_code, invoice_no, invoice_date,
            discount, invoice_amount, remarks, lpo_no, lines,
            save_mode='grn_only', approve_mode='grn_only',
            warehouse_id=warehouse_id, header_other_charge=header_other_charge,
            post_inventory=True,
        )
        if err:
            _grn_save_audit('POST_INVENTORY fail receipt_no=%s err=%r | %s', receipt_no, err, _grn_save_audit_ctx())
            return json_response_keep_global_nonce({'success': False, 'error': err}, 400)
        if not commit_form_save_nonce(submitted_nonce, session_key=GLOBAL_SAVE_NONCE_SESSION_KEY):
            return replay_blocked_response_global()
        _lpo_list_count_cache_invalidate_grn_lists(_resolve_location_code())
        after_snap = _audit_grn_snapshot(
            _get_receipt_header_for_posting(receipt_no),
            _get_receipt_details(receipt_no),
        )
        _log_purchase_change(
            'GRN', receipt_no, 'POST_INVENTORY',
            remarks or 'Inventory posted',
            before=before_snap,
            after=after_snap,
        )
        _grn_save_audit('POST_INVENTORY ok receipt_no=%s | %s', receipt_no, _grn_save_audit_ctx())
        return json_response_rotate_global({
            'success': True,
            'receiptno': receipt_no,
            'message': f'GRN {receipt_no}: inventory posted. Stock and item journal updated.',
            'inventory_posted': True,
            'account_postings': getattr(_save_receipt, '_last_posting_summary', None),
            'pdf_url': url_for('purchase.api_receipt_pdf', receipt_no=receipt_no),
        })
    except Exception as ex:
        _grn_save_audit('POST_INVENTORY unhandled_exception %s: %s | %s', type(ex).__name__, ex, _grn_save_audit_ctx())
        raise
    finally:
        _grn_receipt_release_session_lock()

@bp.route('/purchase/receipt/api/approval-status/<path:receipt_no>')
def api_receipt_approval_status(receipt_no):
    if not session.get('user'):
        return jsonify({'error': 'Not authenticated'}, 401)
    _apply_db()
    return jsonify({'success': True, 'status': _get_grn_approval_status(receipt_no)})

@bp.route('/purchase/receipt/api/submit', methods=['POST'])
def api_receipt_submit():
    if not session.get('user'):
        return jsonify({'error': 'Not authenticated'}, 401)
    _apply_db()
    data = request.get_json(silent=True) or {}
    receipt_no = parse_receiptno_from_request(data.get('receiptno'))
    remarks = (data.get('remarks') or '').strip()
    if not receiptno_is_valid(receipt_no):
        return jsonify({'success': False, 'error': 'Receipt No is required'}, 400)
    current_status = _get_grn_approval_status(receipt_no)
    if current_status == 'APPROVED':
        return jsonify({'success': False, 'error': 'GRN already approved'}, 400)
    if current_status == 'SUBMITTED':
        return jsonify({'success': False, 'error': 'GRN already submitted'}, 400)
    _set_grn_approval_status(receipt_no, 'SUBMITTED', 'SUBMIT', remarks or 'Submitted for approval')
    try:
        from addons.approval_workflow.approval_workflow_engine import sync_grn_submit
        hdr = _get_receipt_header_for_posting(receipt_no)
        amt = float((hdr or {}).get('invoiceamount') or 0)
        sync_grn_submit(receipt_no, amt, session.get('user') or 'web', _resolve_location_code())
    except Exception:
        pass
    return jsonify({'success': True, 'status': 'SUBMITTED'})

@bp.route('/purchase/receipt/api/approve', methods=['POST'])
def api_receipt_approve():
    if not session.get('user'):
        return jsonify({'error': 'Not authenticated'}, 401)
    _apply_db()
    data = request.get_json(silent=True) or {}
    receipt_no = parse_receiptno_from_request(data.get('receiptno'))
    remarks = (data.get('remarks') or '').strip()
    if not receiptno_is_valid(receipt_no):
        return jsonify({'success': False, 'error': 'Receipt No is required'}, 400)
    current_status = _get_grn_approval_status(receipt_no)
    if current_status != 'SUBMITTED':
        return jsonify({'success': False, 'error': 'Only submitted GRN can be approved'}, 400)
    hdr = _get_receipt_header_for_posting(receipt_no)
    if not hdr:
        return jsonify({'success': False, 'error': 'Saved GRN data not found'}, 400)
    lines = _get_receipt_details(receipt_no)
    if not lines:
        return jsonify({'success': False, 'error': 'Saved GRN has no lines'}, 400)
    sup_ap = int(hdr.get('suppliercode') or 0)
    inv_ap = str(hdr.get('invoiceno') or '')
    _grn_save_audit(
        'APPROVE attempt receipt_no=%s supplier=%s invoice=%r lines=%s | %s',
        receipt_no, sup_ap, inv_ap, len(lines), _grn_save_audit_ctx(),
    )
    _set_grn_approval_status(receipt_no, 'APPROVED', 'APPROVE', remarks or 'Approved')
    _grn_save_audit('APPROVE ok receipt_no=%s supplier=%s | %s', receipt_no, sup_ap, _grn_save_audit_ctx())
    return jsonify({'success': True, 'status': 'APPROVED'})

