@bp.route('/purchase/return/api/item-lots/<int:itemcode>')
def api_purchase_return_item_lots(itemcode: int):
    """Open lots with qty > 0 for a return line (for lot picker dropdown)."""
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    loc_code = _resolve_location_code()
    if not _table_exists(ITEM_LOT_TABLE):
        return jsonify({'success': True, 'lots': []})
    try:
        _, rows = _fetch_rows(
            f"""
            SELECT l.LOT_ID, l.BATCH_NO,
                   NVL(l.EXPIRY_DATE, NULL) AS expiry_date,
                   NVL(b.QTY, 0)            AS qty
            FROM {ITEM_LOT_TABLE} l
            LEFT JOIN ITEM_LOT_BALANCE b ON b.LOT_ID = l.LOT_ID
            WHERE l.LOCATIONCODE = :loc AND l.ITEMCODE = :ic
              AND NVL(b.QTY, 0) > 0
              AND UPPER(NVL(TRIM(l.LOT_BLOCKED), 'N')) <> 'Y'
            ORDER BY l.EXPIRY_DATE NULLS LAST, l.LOT_ID
            """,
            {'loc': loc_code, 'ic': itemcode}
        )
        lots = []
        for r in (rows or []):
            exp = r.get('expiry_date')
            exp_str = exp.strftime('%Y-%m-%d') if exp and hasattr(exp, 'strftime') else (str(exp)[:10] if exp else '')
            lots.append({'lot_id': r.get('lot_id'), 'batch_no': r.get('batch_no') or '', 'expiry_date': exp_str, 'qty': float(r.get('qty') or 0)})
        return jsonify({'success': True, 'lots': lots})
    except Exception as exc:
        return jsonify({'success': True, 'lots': [], 'warning': str(exc)})


@bp.route('/purchase/receipt/api/load-from-lpo/<path:lpo_no>')
def api_receipt_load_from_lpo(lpo_no: str):
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    lpo_key = parse_lpono_from_request(lpo_no)
    t0 = time.perf_counter()
    try:
        details = _get_lpo_details(lpo_key)
        header = _get_lpo_header(lpo_key) or {}
        _lpo_resolve_header_warehouse(header, lpo_key, lines=details)
        if not header.get('lpoamount'):
            total = 0.0
            for line in details:
                qty = float(line.get('inquantity') or line.get('inquanttity') or line.get('INQUANTITY') or line.get('INQUANTTITY') or 0)
                rate = float(line.get('rate') or 0)
                disc = float(line.get('discount') or 0)
                foc = line.get('foc') in (True, 1, '1', 'Y', 'y')
                total += 0.0 if foc else max(0.0, qty * rate - disc)
            header['lpoamount'] = round(total, 2)
        elapsed = time.perf_counter() - t0
        if elapsed >= 0.5:
            print(f'[api_receipt_load_from_lpo] {elapsed:.2f}s lpo={lpo_no} lines={len(details or [])}')
        return jsonify({'success': True, 'header': header, 'lines': details})
    except Exception as exc:
        return jsonify({'success': False, 'error': str(exc) or 'LPO load failed'}, 500)

@bp.route('/purchase/receipt/api/warehouse-bins')
def api_grn_warehouse_bins():
    """BIN + STAGING rows for the warehouse selected on GRN header or line."""
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    wh_raw = (request.args.get('wh') or request.args.get('warehouse_id') or '').strip()
    if not wh_raw:
        return jsonify({'success': True, 'warehouse_id': '', 'bins': []})
    wh_ids = [w.strip() for w in wh_raw.split(',') if w.strip()]
    if len(wh_ids) <= 1:
        wh = wh_ids[0] if wh_ids else ''
        try:
            rows = list_warehouse_picker_bins(wh) or []
        except Exception as exc:
            return jsonify({'success': False, 'error': str(exc)}, 500)
        bins: List[Dict[str, Any]] = []
        for row in rows:
            if not row:
                continue
            sid = row.get('storage_id')
            code = str(row.get('code') or '').strip()
            if sid is None or not code:
                continue
            bins.append({
                'storage_id': sid,
                'code': code,
                'name': str(row.get('name') or '').strip(),
                'warehouse_id': str(row.get('warehouse_id') or row.get('loc_key') or wh).strip(),
                'storage_type': str(row.get('storage_type') or '').strip(),
            })
        return jsonify({'success': True, 'warehouse_id': wh, 'bins': bins})
    by_wh: Dict[str, List[Dict[str, Any]]] = {}
    for wh in wh_ids:
        try:
            rows = list_warehouse_picker_bins(wh) or []
        except Exception as exc:
            return jsonify({'success': False, 'error': str(exc)}, 500)
        bins: List[Dict[str, Any]] = []
        for row in rows:
            if not row:
                continue
            sid = row.get('storage_id')
            code = str(row.get('code') or '').strip()
            if sid is None or not code:
                continue
            bins.append({
                'storage_id': sid,
                'code': code,
                'name': str(row.get('name') or '').strip(),
                'warehouse_id': str(row.get('warehouse_id') or row.get('loc_key') or wh).strip(),
                'storage_type': str(row.get('storage_type') or '').strip(),
            })
        by_wh[str(wh)] = bins
    return jsonify({'success': True, 'warehouses': by_wh})


