@bp.route('/purchase/return/api/receive-locations/<itemcode>')
def api_purchase_return_receive_locations(itemcode: str):
    """Prefer ITEMMASTER store; otherwise STOREINVENTORYNEW. Rows with stock > 0 only."""
    if not session.get('user'):
        return jsonify({'error': 'Not authenticated'}, 401)
    if request.args.get('locationcode'):
        try:
            session['location_code'] = int(request.args.get('locationcode'))
        except (ValueError, TypeError):
            pass
    _apply_db()
    loc_code = _resolve_location_code()
    itemcode_txt = str(itemcode or '').strip()
    if not itemcode_txt:
        return jsonify({'success': True, 'locations': [], 'from_itemstore': False})
    try:
        item_int = int(itemcode_txt)
    except (TypeError, ValueError):
        return jsonify({'success': True, 'locations': [], 'from_itemstore': False})
    rows = get_item_store_rows_from_itemmaster(item_int, loc_code) or []
    if not rows:
        rows = get_item_store_inventory(loc_code, item_int) or []
    locs: List[Dict[str, Any]] = []
    for row in rows:
        code = str(row.get('store') or row.get('STORE') or row.get('code') or '').strip()
        if not code:
            continue
        try:
            stock = float(row.get('stock') or row.get('STOCK') or 0)
        except (TypeError, ValueError):
            stock = 0.0
        if stock > 0:
            locs.append({'code': code, 'stock': stock})
    return jsonify({'success': True, 'locations': locs, 'from_itemstore': bool(locs)})

