_GRN_RECEIPT_SAVE_SESSION_LOCK_UNTIL = '_grn_receipt_save_session_lock_until'


def _grn_receipt_try_acquire_session_lock(lock_seconds: float=180.0) -> bool:
    """Best-effort session lock: one GRN save at a time per browser session (expires if handler crashes)."""
    now = time.time()
    raw = session.get(_GRN_RECEIPT_SAVE_SESSION_LOCK_UNTIL)
    try:
        until = float(raw)
        if until > now:
            return False
    except (TypeError, ValueError):
        pass
    session[_GRN_RECEIPT_SAVE_SESSION_LOCK_UNTIL] = now + float(lock_seconds)
    session.modified = True
    return True


def _grn_receipt_release_session_lock() -> None:
    session.pop(_GRN_RECEIPT_SAVE_SESSION_LOCK_UNTIL, None)
    session.modified = True


_PR_REQUEST_SAVE_SESSION_LOCK_UNTIL = '_pr_request_save_session_lock_until'
_PR_SAVE_SESSION_LOCK_UNTIL = '_pr_save_session_lock_until'
_PDN_SAVE_SESSION_LOCK_UNTIL = '_pdn_save_session_lock_until'
_DNREQ_SAVE_SESSION_LOCK_UNTIL = '_dnreq_save_session_lock_until'
_STOCK_ADJUSTMENT_SAVE_SESSION_LOCK_UNTIL = '_stock_adjustment_save_session_lock_until'
_REPACKING_SAVE_SESSION_LOCK_UNTIL = '_repacking_save_session_lock_until'
_STOCK_TRANSFER_APPROVE_SESSION_LOCK_UNTIL = '_stock_transfer_approve_session_lock_until'


def _try_acquire_session_lock(lock_key: str, lock_seconds: float=180.0) -> bool:
    """Best-effort per-browser-session save lock with expiry if the handler crashes."""
    now = time.time()
    raw = session.get(lock_key)
    try:
        until = float(raw)
        if until > now:
            return False
    except (TypeError, ValueError):
        pass
    session[lock_key] = now + float(lock_seconds)
    session.modified = True
    return True


def _release_session_lock(lock_key: str) -> None:
    session.pop(lock_key, None)
    session.modified = True


_PI_BULK_POST_SESSION_LOCK_UNTIL = '_pi_bulk_post_session_lock_until'

def _pi_bulk_post_try_acquire_session_lock(lock_seconds: float=120.0) -> bool:
    """Best-effort session lock so one bulk post runs at a time per browser session."""
    now = time.time()
    raw = session.get(_PI_BULK_POST_SESSION_LOCK_UNTIL)
    try:
        until = float(raw)
        if until > now:
            return False
    except (TypeError, ValueError):
        pass
    session[_PI_BULK_POST_SESSION_LOCK_UNTIL] = now + float(lock_seconds)
    session.modified = True
    return True

def _pi_bulk_post_release_session_lock() -> None:
    session.pop(_PI_BULK_POST_SESSION_LOCK_UNTIL, None)
    session.modified = True

@bp.route('/purchase/invoice/api/post-selected', methods=['POST'])
def api_pi_post_selected():
    if not session.get('user'):
        return jsonify({'error': 'Not authenticated'}, 401)
    _apply_db()
    data = request.get_json(silent=True) or {}
    raw_receipts = data.get('receipt_nos') or []
    receipt_nos: List[Any] = []
    for x in raw_receipts:
        rno = parse_receiptno_from_request(x)
        if receiptno_is_valid(rno) and not any(receiptno_equal(rno, existing) for existing in receipt_nos):
            receipt_nos.append(rno)
    if not receipt_nos:
        return jsonify({'success': False, 'error': 'Select at least one receipt'}, 400)
    if not _pi_bulk_post_try_acquire_session_lock():
        cur_nonce = session.get(GLOBAL_SAVE_NONCE_SESSION_KEY)
        if not cur_nonce:
            cur_nonce = issue_save_nonce(GLOBAL_SAVE_NONCE_SESSION_KEY)
        return jsonify({'success': False, 'error': 'A purchase invoice post is already in progress for this session. Please wait until it completes.', 'busy': True, 'save_nonce': cur_nonce}, 409)
    try:
        submitted = extract_submitted_save_nonce(request)
        if not verify_consume_save_nonce(GLOBAL_SAVE_NONCE_SESSION_KEY, submitted):
            return replay_blocked_response_global()
        posted: List[Any] = []
        failed: List[Dict[str, Any]] = []
        for rno in receipt_nos:
            err = _post_grn_from_saved_receipt(rno, force_posting=True)
            if err:
                failed.append({'receipt_no': rno, 'error': err})
            else:
                posted.append(rno)
        ok = len(failed) == 0
        msg = f'Posted {len(posted)} invoice(s).' if ok else f'Posted {len(posted)} invoice(s), failed {len(failed)}.'
        return json_response_rotate_global({'success': ok, 'message': msg, 'posted_count': len(posted), 'posted_receipts': posted, 'failed_count': len(failed), 'failed': failed}, 200)
    finally:
        _pi_bulk_post_release_session_lock()


@bp.route('/purchase/invoice/api/reverse', methods=['POST'])
def api_pi_reverse_posting():
    """Reverse (unpost) Purchase Invoice AP posting for a GRN. Stock stays posted."""
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    data = request.get_json(silent=True) or {}
    receipt_no = parse_receiptno_from_request(data.get('receipt_no') or data.get('receiptno'))
    if not receiptno_is_valid(receipt_no):
        return json_response_keep_global_nonce({'success': False, 'error': 'GRN number is required.'}, 400)
    pwd_err = _verify_current_user_password(
        data.get('password'),
        required_msg='Password is required to reverse posting.',
    )
    if pwd_err:
        return json_response_keep_global_nonce({'success': False, 'error': pwd_err}, 403)
    if not verify_consume_save_nonce(GLOBAL_SAVE_NONCE_SESSION_KEY, extract_submitted_save_nonce(request)):
        return replay_blocked_response_global()
    ok, err, vno = _reverse_pi_grn_account_posting(receipt_no)
    if not ok:
        return json_response_rotate_global({'success': False, 'error': err or 'Reverse failed.'}, 400)
    return json_response_rotate_global({
        'success': True,
        'message': f'Posting reversed for GRN #{receipt_no}. Voucher {vno} removed; GRN is back in Posting Pending.',
        'receipt_no': receipt_no,
        'voucher_no': vno,
    }, 200)


@bp.route('/purchase/invoice/api/reverse-pending', methods=['POST'])
def api_pi_reverse_pending_grn():
    """Reverse a Posting Pending GRN: undo stock posting and remove the GRN."""
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    if not _grn_receipt_try_acquire_session_lock():
        return json_response_keep_global_nonce({
            'success': False,
            'error': 'A GRN operation is already in progress for this session. Please wait.',
            'save_session_locked': True,
        }, 423)
    try:
        data = request.get_json(silent=True) or {}
        receipt_no = parse_receiptno_from_request(data.get('receipt_no') or data.get('receiptno'))
        if not receiptno_is_valid(receipt_no):
            return json_response_keep_global_nonce({'success': False, 'error': 'GRN number is required.'}, 400)
        pwd_err = _verify_current_user_password(
            data.get('password'),
            required_msg='Password is required to reverse this GRN.',
        )
        if pwd_err:
            return json_response_keep_global_nonce({'success': False, 'error': pwd_err}, 403)
        if not verify_consume_save_nonce(GLOBAL_SAVE_NONCE_SESSION_KEY, extract_submitted_save_nonce(request)):
            return replay_blocked_response_global()
        ok, err = _reverse_pi_pending_grn(receipt_no)
        if not ok:
            return json_response_rotate_global({'success': False, 'error': err or 'Reverse failed.'}, 400)
        return json_response_rotate_global({
            'success': True,
            'message': (
                f'GRN #{receipt_no} reversed: stock undone. '
                'ITEMJOURNAL kept original lines and added reverse (REVERSAL) entries. '
                f'Number #{receipt_no} is reserved — next GRN will use a new number.'
            ),
            'receipt_no': receipt_no,
            'number_reserved': True,
        }, 200)
    finally:
        _grn_receipt_release_session_lock()


@bp.route('/purchase/invoice/api/change-date', methods=['POST'])
def api_pi_change_posting_date():
    """Change GRN date and (if posted) voucher / posting header dates."""
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    data = request.get_json(silent=True) or {}
    receipt_no = parse_receiptno_from_request(data.get('receipt_no') or data.get('receiptno'))
    new_date = (data.get('new_date') or data.get('receiptdate') or data.get('posting_date') or '').strip()
    if not receiptno_is_valid(receipt_no):
        return json_response_keep_global_nonce({'success': False, 'error': 'GRN number is required.'}, 400)
    if not new_date:
        return json_response_keep_global_nonce({'success': False, 'error': 'New date is required.'}, 400)
    pwd_err = _verify_current_user_password(
        data.get('password'),
        required_msg='Password is required to change posting date.',
    )
    if pwd_err:
        return json_response_keep_global_nonce({'success': False, 'error': pwd_err}, 403)
    if not verify_consume_save_nonce(GLOBAL_SAVE_NONCE_SESSION_KEY, extract_submitted_save_nonce(request)):
        return replay_blocked_response_global()
    also_receipt = bool(data.get('also_change_receipt_date') or data.get('change_receipt_date'))
    ok, err = _change_pi_grn_posting_date(
        receipt_no, new_date, also_change_receipt_date=also_receipt,
    )
    if not ok:
        return json_response_rotate_global({'success': False, 'error': err or 'Date change failed.'}, 400)
    return json_response_rotate_global({
        'success': True,
        'message': (
            f'GRN #{receipt_no} posting date updated to {new_date[:10]}'
            + (' (receipt date also updated).' if also_receipt else '.')
        ),
        'receipt_no': receipt_no,
        'new_date': new_date[:10],
        'posting_date': new_date[:10],
    }, 200)


@bp.route('/purchase/receipt/api/change-posting-date', methods=['POST'])
def api_receipt_change_posting_date():
    """Change GRN posting date from the Goods Receipt screen (password required)."""
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    data = request.get_json(silent=True) or {}
    receipt_no = parse_receiptno_from_request(data.get('receipt_no') or data.get('receiptno'))
    new_date = (data.get('new_date') or data.get('posting_date') or data.get('postingdate') or '').strip()
    if not receiptno_is_valid(receipt_no):
        return json_response_keep_global_nonce({'success': False, 'error': 'GRN number is required.'}, 400)
    if not new_date:
        return json_response_keep_global_nonce({'success': False, 'error': 'New posting date is required.'}, 400)
    pwd_err = _verify_current_user_password(
        data.get('password'),
        required_msg='Password is required to change posting date.',
    )
    if pwd_err:
        return json_response_keep_global_nonce({'success': False, 'error': pwd_err}, 403)
    if not verify_consume_save_nonce(GLOBAL_SAVE_NONCE_SESSION_KEY, extract_submitted_save_nonce(request)):
        return replay_blocked_response_global()
    also_receipt = bool(data.get('also_change_receipt_date') or data.get('change_receipt_date'))
    ok, err = _change_pi_grn_posting_date(
        receipt_no, new_date, also_change_receipt_date=also_receipt,
    )
    if not ok:
        return json_response_rotate_global({'success': False, 'error': err or 'Date change failed.'}, 400)
    return json_response_rotate_global({
        'success': True,
        'message': f'Posting date updated to {new_date[:10]} for GRN #{receipt_no}.',
        'receipt_no': receipt_no,
        'posting_date': new_date[:10],
    }, 200)


@bp.route('/purchase/return/api/reverse-pending', methods=['POST'])
def api_pr_reverse_pending():
    """Reverse a Posting Pending purchase return: undo stock and remove the return document."""
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    if not _try_acquire_session_lock(_PR_SAVE_SESSION_LOCK_UNTIL):
        return json_response_keep_global_nonce({
            'success': False,
            'error': 'A purchase return operation is already in progress for this session. Please wait.',
            'save_session_locked': True,
        }, 423)
    try:
        data = request.get_json(silent=True) or {}
        try:
            goods_return_no = parse_goodsreturnno_from_request(
                data.get('goods_return_no') or data.get('goodsreturnno')
            )
        except (TypeError, ValueError):
            goods_return_no = parse_goodsreturnno_from_request(0)
        if not returnhdr_goodsreturnno_is_valid_match(goods_return_no):
            return json_response_keep_global_nonce({'success': False, 'error': 'Return number is required.'}, 400)
        pwd_err = _verify_current_user_password(
            data.get('password'),
            required_msg='Password is required to reverse this purchase return.',
        )
        if pwd_err:
            return json_response_keep_global_nonce({'success': False, 'error': pwd_err}, 403)
        if not verify_consume_save_nonce(GLOBAL_SAVE_NONCE_SESSION_KEY, extract_submitted_save_nonce(request)):
            return replay_blocked_response_global()
        ok, err = _reverse_pr_pending(goods_return_no)
        if not ok:
            return json_response_rotate_global({'success': False, 'error': err or 'Reverse failed.'}, 400)
        return json_response_rotate_global({
            'success': True,
            'message': (
                f'Purchase return #{goods_return_no} reversed: stock undone. '
                'ITEMJOURNAL kept original lines and added reverse (REVERSAL) entries. '
                f'Number #{goods_return_no} is reserved — next return will use a new number.'
            ),
            'goodsreturnno': goods_return_no,
            'number_reserved': True,
        }, 200)
    finally:
        _release_session_lock(_PR_SAVE_SESSION_LOCK_UNTIL)


@bp.route('/purchase/return/api/change-posting-date', methods=['POST'])
def api_pr_change_posting_date():
    """Change purchase return posting date (password required)."""
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    data = request.get_json(silent=True) or {}
    try:
        goods_return_no = int(data.get('goods_return_no') or data.get('goodsreturnno') or 0)
    except (TypeError, ValueError):
        goods_return_no = 0
    new_date = (data.get('new_date') or data.get('posting_date') or data.get('postingdate') or '').strip()
    if goods_return_no <= 0:
        return json_response_keep_global_nonce({'success': False, 'error': 'Return number is required.'}, 400)
    if not new_date:
        return json_response_keep_global_nonce({'success': False, 'error': 'New posting date is required.'}, 400)
    pwd_err = _verify_current_user_password(
        data.get('password'),
        required_msg='Password is required to change posting date.',
    )
    if pwd_err:
        return json_response_keep_global_nonce({'success': False, 'error': pwd_err}, 403)
    if not verify_consume_save_nonce(GLOBAL_SAVE_NONCE_SESSION_KEY, extract_submitted_save_nonce(request)):
        return replay_blocked_response_global()
    also_return = bool(data.get('also_change_return_date') or data.get('change_return_date'))
    ok, err = _change_pr_posting_date(
        goods_return_no, new_date, also_change_return_date=also_return,
    )
    if not ok:
        return json_response_rotate_global({'success': False, 'error': err or 'Date change failed.'}, 400)
    return json_response_rotate_global({
        'success': True,
        'message': f'Posting date updated to {new_date[:10]} for return #{goods_return_no}.',
        'goodsreturnno': goods_return_no,
        'posting_date': new_date[:10],
    }, 200)


