@bp.route('/purchase/return-order/api/save', methods=['POST'])
def api_return_order_save():
    if not session.get('user'):
        return jsonify({'error': 'Not authenticated'}, 401)
    _apply_db()
    ensure_goodsreturnno_varchar_columns()
    data = request.get_json(silent=True) or {}
    is_debit_note_request_early = str((data.get('returntype') or 'P')[:1]).strip().upper() == 'D'
    lock_key = _DNREQ_SAVE_SESSION_LOCK_UNTIL if is_debit_note_request_early else _PR_REQUEST_SAVE_SESSION_LOCK_UNTIL
    lock_busy_msg = (
        'A debit note request save is already in progress for this session. Please wait until it completes.'
        if is_debit_note_request_early
        else 'A purchase return request save is already in progress for this session. Please wait until it completes.'
    )
    if not _try_acquire_session_lock(lock_key):
        return json_response_rotate_global({'success': False, 'error': lock_busy_msg, 'save_session_locked': True}, 423)
    try:
        submitted_nonce = extract_submitted_save_nonce(request)
        if is_debit_note_request_early:
            if not reject_invalid_form_save_nonce(submitted_nonce, session_key=GLOBAL_SAVE_NONCE_SESSION_KEY):
                return replay_blocked_response_global()
        elif not verify_consume_save_nonce(GLOBAL_SAVE_NONCE_SESSION_KEY, submitted_nonce):
            return replay_blocked_response_global()
        goods_return_no = parse_goodsreturnno_from_request(data.get('goodsreturnno'))
        return_date = (data.get('returndate') or '')[:10]
        open_date, txn_err = _enforce_purchase_open_date(return_date, 'purchase_return')
        if txn_err:
            return json_response_rotate_global(
                {'success': False, 'error': txn_err, 'transaction_date_blocked': True},
                400,
            )
        return_date = open_date or return_date
        posting_date = (data.get('postingdate') or data.get('posting_date') or return_date or '')[:10]
        if posting_date:
            open_pd, pd_err = _enforce_purchase_open_date(posting_date, 'purchase_return')
            if pd_err:
                return json_response_rotate_global(
                    {'success': False, 'error': pd_err, 'transaction_date_blocked': True},
                    400,
                )
            posting_date = open_pd or posting_date
        else:
            posting_date = return_date
        supplier_code = int(data.get('suppliercode') or 0)
        receipt_raw = data.get('receiptno')
        if receipt_raw not in (None, '', 0, '0'):
            receipt_no = parse_receiptno_from_request(receipt_raw)
            if not receiptno_is_valid(receipt_no):
                receipt_no = None
        else:
            receipt_no = None
        return_type = (data.get('returntype') or 'P')[:1]
        remarks = (data.get('remarks') or '').strip()
        return_amount = float(data.get('returnamount') or 0)
        lines = data.get('lines') or []
        if not goodsreturnno_is_valid(goods_return_no) or not return_date or (not supplier_code):
            err_resp = json_response_keep_global_nonce if is_debit_note_request_early else json_response_rotate_global
            return err_resp({'success': False, 'error': 'Return No, Date and Supplier are required'}, 400)
        if not lines:
            err_resp = json_response_keep_global_nonce if is_debit_note_request_early else json_response_rotate_global
            return err_resp({'success': False, 'error': 'Add at least one return line'}, 400)
        pr_line_err = _validate_purchase_doc_save_lines(lines, doc_label='purchase return request')
        if pr_line_err:
            err_resp = json_response_keep_global_nonce if is_debit_note_request_early else json_response_rotate_global
            return err_resp({'success': False, 'error': pr_line_err}, 400)
        header_wh_raw = data.get('warehouse_id')
        header_warehouse_id: Optional[int] = None
        if header_wh_raw not in (None, ''):
            try:
                header_warehouse_id = int(header_wh_raw)
                if header_warehouse_id <= 0:
                    header_warehouse_id = None
            except (TypeError, ValueError):
                header_warehouse_id = None
        wh_err = _validate_purchase_return_warehouse_lines(
            lines, header_warehouse_id=header_warehouse_id, doc_label='purchase return request',
        )
        if wh_err:
            err_resp = json_response_keep_global_nonce if is_debit_note_request_early else json_response_rotate_global
            return err_resp({'success': False, 'error': wh_err}, 400)
        header_discount = float(data.get('discount') or 0)
        lines = _apply_pr_header_discount_to_lines(list(lines), header_discount)
        requested_no = goods_return_no
        goods_return_no, req_reassigned = _resolve_return_order_no_for_save(requested_no)
        current_status = _get_return_request_approval_status(goods_return_no)
        if not req_reassigned and goodsreturnno_is_valid(requested_no) and current_status == 'CANCELLED':
            err_resp = json_response_keep_global_nonce if is_debit_note_request_early else json_response_rotate_global
            return err_resp({'success': False, 'error': 'Cancelled return request cannot be saved'}, 400)
        if req_reassigned and current_status == 'CANCELLED':
            current_status = 'DRAFT'
        is_debit_note_request = str(return_type or '').strip().upper() == 'D'
        list_url = url_for('purchase.purchase_debit_note_list') if is_debit_note_request else url_for('purchase.purchase_return_list')
        pdf_url = url_for('purchase.api_debit_note_request_pdf', goods_return_no=goods_return_no) if is_debit_note_request else url_for('purchase.api_return_order_pdf', goods_return_no=goods_return_no)
        if is_debit_note_request:
            err: Optional[str] = None
            for _dup_try in range(8):
                err = _save_debit_note_request(
                    dnreq_no=goods_return_no,
                    dnreq_date=return_date,
                    supplier_code=supplier_code,
                    receipt_no=receipt_no,
                    dnreq_amount=return_amount,
                    remarks=remarks,
                    lines=lines,
                )
                if not err:
                    break
                if not _is_duplicate_doc_key_error(err):
                    break
                retry_no = _allocate_next_free_return_order_no(goods_return_no)
                if billno_numeric_part(retry_no) <= billno_numeric_part(goods_return_no):
                    retry_no = coerce_goodsreturnno(billno_numeric_part(goods_return_no) + 1)
                    while (
                        _temp_return_order_exists(retry_no)
                        and billno_numeric_part(retry_no) < billno_numeric_part(goods_return_no) + 100
                    ):
                        retry_no = coerce_goodsreturnno(billno_numeric_part(retry_no) + 1)
                if retry_no == goods_return_no or goodsreturnno_equal(retry_no, goods_return_no):
                    break
                goods_return_no = retry_no
                req_reassigned = True
            if err:
                body = {'success': False, 'error': err}
                if _is_duplicate_doc_key_error(err):
                    body['duplicate_doc_key'] = True
                    body['suggested_goodsreturnno'] = _allocate_next_free_return_order_no(goods_return_no)
                return json_response_keep_global_nonce(body, 400)
            approval_save_as = str(data.get('approval_save_as') or 'draft').strip().lower()
            if approval_save_as not in ('draft', 'approved'):
                approval_save_as = 'draft'
            status = 'APPROVED' if approval_save_as == 'approved' else 'DRAFT'
            _set_return_request_approval_status(goods_return_no, status, f'SAVE_{status}', remarks)
            if not commit_form_save_nonce(submitted_nonce, session_key=GLOBAL_SAVE_NONCE_SESSION_KEY):
                return replay_blocked_response_global()
            msg = 'Debit note request saved.'
            if req_reassigned:
                msg = f'Request number {requested_no} was already in use. Saved as request {goods_return_no}.'
            return json_response_rotate_global({
                'success': True,
                'goodsreturnno': goods_return_no,
                'requested_goodsreturnno': requested_no,
                'goodsreturnno_reassigned': req_reassigned,
                'approval_status': status,
                'posted': False,
                'message': msg,
                'next_goodsreturnno': _debit_note_request_next_no(),
                'pdf_url': pdf_url,
                'list_url': list_url,
            })
        req_existed = not req_reassigned and goodsreturnno_is_valid(requested_no) and _get_purchase_return_header(requested_no) is not None
        before_snap = _audit_pr_snapshot(
            _get_purchase_return_header(requested_no),
            _get_purchase_return_details(requested_no),
        ) if req_existed else None
        err = None
        for _dup_try in range(8):
            err = _save_purchase_return_order(
                goods_return_no=goods_return_no,
                return_date=return_date,
                supplier_code=supplier_code,
                receipt_no=receipt_no,
                return_amount=return_amount,
                return_type=return_type,
                remarks=remarks,
                lines=lines,
                posting_date=posting_date,
                discount=header_discount,
            )
            if not err:
                break
            if not _is_duplicate_doc_key_error(err):
                break
            retry_no = _allocate_next_free_return_order_no(goods_return_no)
            if billno_numeric_part(retry_no) <= billno_numeric_part(goods_return_no):
                retry_no = coerce_goodsreturnno(billno_numeric_part(goods_return_no) + 1)
                while (
                    _temp_return_order_exists(retry_no)
                    and billno_numeric_part(retry_no) < billno_numeric_part(goods_return_no) + 100
                ):
                    retry_no = coerce_goodsreturnno(billno_numeric_part(retry_no) + 1)
            if retry_no == goods_return_no or goodsreturnno_equal(retry_no, goods_return_no):
                break
            goods_return_no = retry_no
            req_reassigned = True
        if err:
            body = {'success': False, 'error': err}
            if _is_duplicate_doc_key_error(err):
                body['duplicate_doc_key'] = True
                body['suggested_goodsreturnno'] = _allocate_next_free_return_order_no(goods_return_no)
            return json_response_rotate_global(body, 400)

        def _log_pr_req_edit() -> None:
            if not req_existed:
                return
            after_snap = _audit_pr_snapshot_from_payload(data)
            _log_purchase_change(
                'PR_REQ', goods_return_no, 'EDIT',
                remarks or 'Return request updated',
                before=before_snap,
                after=after_snap,
            )

        approval_save_as = str(data.get('approval_save_as') or 'approved').strip().lower()
        if approval_save_as in ('inventory_only', 'post'):
            approval_save_as = 'approved'
        post_accounts = approval_save_as == 'inventory_accounts'
        if approval_save_as not in ('draft', 'approved', 'inventory_accounts'):
            approval_save_as = 'approved'
        if approval_save_as in ('approved', 'inventory_accounts'):
            action = 'SAVE_INVENTORY_ACCOUNTS' if post_accounts else 'SAVE_APPROVED'
            post_err, posted_return_no, approval_status = _approve_return_order_and_post_stock(
                goods_return_no, remarks, approval_action=action,
            )
            if post_err:
                return json_response_rotate_global({'success': False, 'error': post_err}, 400)
            accounts_posted = False
            if post_accounts and posted_return_no:
                acct_err = _post_saved_purchase_return(
                    posted_return_no, source_return_order_no=goods_return_no,
                )
                if acct_err:
                    return json_response_rotate_global({
                        'success': False,
                        'error': (
                            f'Stock posted as Purchase Return #{posted_return_no}, '
                            f'but accounts posting failed: {acct_err}'
                        ),
                        'posted_return_no': posted_return_no,
                        'inventory_posted': True,
                        'accounts_posted': False,
                    }, 400)
                accounts_posted = True
            _log_pr_req_edit()
            try:
                with _get_connection() as conn:
                    with conn.cursor() as cur:
                        from addons.document_numbering.document_numbering_db import advance_document_series_after_save_cur
                        advance_document_series_after_save_cur(
                            cur, DOC_TYPE_RETURN_ORDER, goods_return_no,
                            location_code=_resolve_location_code(),
                            reset_no=RESET_NO,
                            user=str(session.get('user') or 'web'),
                        )
                    conn.commit()
            except Exception:
                pass
            if accounts_posted and posted_return_no:
                msg = f'Saved and posted (stock + GL) as Purchase Return #{posted_return_no}.'
            elif posted_return_no:
                msg = f'Saved and posted stock as Purchase Return #{posted_return_no}. Use Accounts Posting for GL when needed.'
            else:
                msg = 'Saved and approved.'
            if req_reassigned:
                msg = f'Request number {requested_no} was already in use. Saved as request {goods_return_no}.' + (
                    f' Posted as Purchase Return #{posted_return_no}.' if posted_return_no else ' Saved and approved.'
                )
            return json_response_rotate_global({
                'success': True,
                'goodsreturnno': goods_return_no,
                'requested_goodsreturnno': requested_no,
                'goodsreturnno_reassigned': req_reassigned,
                'approval_status': approval_status,
                'posted': bool(posted_return_no),
                'posted_return_no': posted_return_no,
                'posted_return_url': url_for('purchase.purchase_return_query', goods_return_no=posted_return_no) if posted_return_no else None,
                'inventory_posted': bool(posted_return_no),
                'accounts_posted': accounts_posted,
                'message': msg,
                'next_goodsreturnno': _return_order_next_no(),
                'pdf_url': pdf_url,
                'list_url': list_url,
            })
        status = 'DRAFT'
        _set_return_request_approval_status(goods_return_no, status, 'SAVE_DRAFT', remarks)
        _log_pr_req_edit()
        try:
            with _get_connection() as conn:
                with conn.cursor() as cur:
                    from addons.document_numbering.document_numbering_db import advance_document_series_after_save_cur
                    advance_document_series_after_save_cur(
                        cur, DOC_TYPE_RETURN_ORDER, goods_return_no,
                        location_code=_resolve_location_code(),
                        reset_no=RESET_NO,
                        user=str(session.get('user') or 'web'),
                    )
                conn.commit()
        except Exception:
            pass
        draft_msg = 'Saved as draft.'
        if req_reassigned:
            draft_msg = f'Request number {requested_no} was already in use. Saved as request {goods_return_no} (draft).'
        return json_response_rotate_global({
            'success': True,
            'goodsreturnno': goods_return_no,
            'requested_goodsreturnno': requested_no,
            'goodsreturnno_reassigned': req_reassigned,
            'approval_status': status,
            'posted': False,
            'message': draft_msg,
            'next_goodsreturnno': _return_order_next_no(),
            'pdf_url': pdf_url,
            'list_url': list_url,
        })
    finally:
        _release_session_lock(lock_key)

@bp.route('/purchase/return-order/api/post-stock', methods=['POST'])
def api_return_order_post_stock():
    """Retry stock post for an approved request (or complete approve+post for legacy APPROVED rows)."""
    if not session.get('user'):
        return jsonify({'error': 'Not authenticated'}, 401)
    _apply_db()
    data = request.get_json(silent=True) or {}
    goods_return_no = parse_goodsreturnno_from_request(data.get('goodsreturnno'))
    if not goodsreturnno_is_valid(goods_return_no):
        return jsonify({'success': False, 'error': 'Return request no is required'}), 400
    if not _get_purchase_return_header(goods_return_no):
        return jsonify({'success': False, 'error': 'Return request not found'}), 404
    if _get_return_request_approval_status(goods_return_no) == 'CANCELLED':
        return jsonify({'success': False, 'error': 'Cancelled return request cannot be posted'}), 400
    already = _return_order_posted_stock_no(goods_return_no)
    if already:
        return jsonify({
            'success': True,
            'posted_return_no': already,
            'posted_return_url': url_for('purchase.purchase_return_query', goods_return_no=already),
            'message': f'Stock already posted as Purchase Return #{already}.',
        })
    post_err, posted_no = _post_purchase_return_order_stock(goods_return_no)
    if post_err:
        return jsonify({'success': False, 'error': post_err}), 400
    if str(_get_return_request_approval_status(goods_return_no) or '').upper() != 'APPROVED':
        _set_return_request_approval_status(goods_return_no, 'APPROVED', 'POST_STOCK_RETRY', (data.get('remarks') or '').strip())
    return jsonify({
        'success': True,
        'posted_return_no': posted_no,
        'posted_return_url': url_for('purchase.purchase_return_query', goods_return_no=posted_no) if posted_no else None,
        'message': f'Posted stock as Purchase Return #{posted_no}.' if posted_no else 'Posted stock.',
    })

@bp.route('/purchase/return-order/api/approve', methods=['POST'])
def api_return_order_approve():
    if not session.get('user'):
        return jsonify({'error': 'Not authenticated'}), 401
    _apply_db()
    data = request.get_json(silent=True) or {}
    goods_return_no = parse_goodsreturnno_from_request(data.get('goodsreturnno'))
    remarks = (data.get('remarks') or '').strip()
    if not goodsreturnno_is_valid(goods_return_no):
        return jsonify({'success': False, 'error': 'Return request no is required'}), 400
    if not _get_purchase_return_header(goods_return_no):
        return jsonify({'success': False, 'error': 'Return request not found'}), 404
    if _get_return_request_approval_status(goods_return_no) == 'CANCELLED':
        return jsonify({'success': False, 'error': 'Cancelled return request cannot be approved'}), 400
    post_err, posted_return_no, approval_status = _approve_return_order_and_post_stock(
        goods_return_no, remarks, approval_action='APPROVE',
    )
    if post_err:
        return jsonify({'success': False, 'error': post_err}), 400
    body: Dict[str, Any] = {
        'success': True,
        'approval_status': approval_status,
        'posted': bool(posted_return_no),
        'posted_return_no': posted_return_no,
    }
    if posted_return_no:
        body['posted_return_url'] = url_for('purchase.purchase_return_query', goods_return_no=posted_return_no)
        body['message'] = f'Approved and posted stock as Purchase Return #{posted_return_no}.'
    else:
        body['message'] = 'Approved.'
    return jsonify(body)

@bp.route('/purchase/return-order/api/cancel', methods=['POST'])
def api_return_order_cancel():
    if not session.get('user'):
        return jsonify({'error': 'Not authenticated'}), 401
    _apply_db()
    data = request.get_json(silent=True) or {}
    goods_return_no = parse_goodsreturnno_from_request(data.get('goodsreturnno'))
    remarks = (data.get('remarks') or '').strip()
    if not goodsreturnno_is_valid(goods_return_no):
        return jsonify({'success': False, 'error': 'Return request no is required'}), 400
    if not _get_purchase_return_header(goods_return_no):
        return jsonify({'success': False, 'error': 'Return request not found'}), 404
    if _get_return_request_approval_status(goods_return_no) == 'CANCELLED':
        return jsonify({'success': False, 'error': 'Return request is already cancelled'}), 400
    before_snap = _audit_pr_snapshot(
        _get_purchase_return_header(goods_return_no),
        _get_purchase_return_details(goods_return_no),
    )
    _set_return_request_approval_status(goods_return_no, 'CANCELLED', 'CANCEL', remarks)
    _log_purchase_change('PR_REQ', goods_return_no, 'CANCEL', remarks or 'Return request canceled', before=before_snap)
    return jsonify({'success': True, 'approval_status': 'CANCELLED'})

