@bp.route('/purchase/return/api/list', methods=['GET'])
def api_purchase_return_list():
    """Paginated purchase return list (all / draft / posted / pending)."""
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Unauthorized'}, 401)
    _apply_db()
    try:
        ensure_tempreturn_tables()
        ensure_goodsreturnno_varchar_columns()
        ensure_returnhdr_extension_columns()
        warm_purchase_return_schema_cache()
    except Exception:
        pass
    try:
        page = max(1, int(request.args.get('page') or 1))
    except (TypeError, ValueError):
        page = 1
    try:
        per_page = max(20, min(int(request.args.get('per_page') or 50), 200))
    except (TypeError, ValueError):
        per_page = 50
    tab = (request.args.get('tab') or 'draft').strip().lower()
    if tab not in ('all', 'draft', 'posted', 'pending'):
        tab = 'draft'
    search = (request.args.get('search') or '').strip() or None
    date_from = (request.args.get('date_from') or '').strip()[:10] or None
    date_to = (request.args.get('date_to') or '').strip()[:10] or None
    t_api = time.perf_counter()
    try:
        rows, total_count = _get_purchase_return_list_page(
            page=page, per_page=per_page, search=search, date_from=date_from, date_to=date_to,
            list_tab=tab,
        )
    except Exception as e:
        print(f'[api_purchase_return_list] {e}')
        return jsonify({'success': False, 'error': str(e)}, 500)
    total_pages = (total_count + per_page - 1) // per_page if total_count > 0 else 1
    elapsed_api = time.perf_counter() - t_api
    if elapsed_api >= 0.5:
        print(f'[api_purchase_return_list] {elapsed_api:.2f}s tab={tab} page={page} rows={len(rows or [])} total={total_count}')
    return jsonify({
        'success': True,
        'tab': tab,
        'rows': rows,
        'total_count': total_count,
        'page': page,
        'items_per_page': per_page,
        'total_pages': total_pages,
    })

