def _load_return_order_error(header: Optional[Dict[str, Any]], goods_return_no: int) -> Optional[str]:
    """Return an error message if a return request cannot be loaded into a posting form."""
    if not header:
        return f'Return order {goods_return_no} not found'
    status = str(header.get('approval_status') or '').upper()
    if status == 'CANCELLED':
        return f'Return request {goods_return_no} is cancelled'
    rtype = str(header.get('returntype') or 'P').strip().upper()[:1] or 'P'
    if rtype == 'D':
        return _debit_note_request_load_error(header, goods_return_no)
    if status != 'APPROVED':
        return f'Return request {goods_return_no} is not approved'
    return None


def _validate_debit_note_source_request(source_return_order_no: Optional[int]) -> Optional[str]:
    """Ensure linked debit-note request exists and is still postable."""
    src = int(source_return_order_no or 0)
    if src <= 0:
        return None
    hdr = _get_debit_note_request_header(src)
    if not hdr:
        return f'Debit note request {src} not found'
    return _debit_note_request_load_error(hdr, src)


@bp.route('/purchase/return/api/load-from-order/<path:goods_return_no>')
def api_purchase_return_load_from_order(goods_return_no):
    if not session.get('user'):
        return jsonify({'error': 'Not authenticated'}, 401)
    _apply_db()
    ensure_goodsreturnno_varchar_columns()
    goods_return_no = parse_goodsreturnno_from_request(goods_return_no)
    dn_header = _get_debit_note_request_header(goods_return_no)
    if dn_header:
        block_err = _debit_note_request_load_error(dn_header, goods_return_no)
        if block_err:
            code = 404 if 'not found' in block_err.lower() else 400
            return jsonify({'success': False, 'error': block_err}, code)
        return jsonify({'success': True, 'header': dn_header, 'lines': _get_debit_note_request_details(goods_return_no)})
    header = _get_purchase_return_header(goods_return_no)
    details = _get_purchase_return_details(goods_return_no)
    block_err = _load_return_order_error(header, goods_return_no)
    if block_err:
        code = 404 if 'not found' in block_err.lower() else 400
        return jsonify({'success': False, 'error': block_err}, code)
    return jsonify({'success': True, 'header': header, 'lines': details})


def _grn_to_purchase_return_payload(receipt_no: Any) -> Tuple[Optional[Dict[str, Any]], Optional[str]]:
    """Map a posted GRN (RECEIPTHDR/RECEIPTDTL) into Purchase Return header + lines."""
    rno = coerce_receiptno(receipt_no)
    if not receiptno_is_valid(rno):
        return None, 'Receipt number is required.'
    hdr = _get_receipt_header_for_posting(rno)
    if not hdr:
        return None, f'GRN / Receipt {rno} not found.'
    try:
        supplier_code = int(float(hdr.get('suppliercode') or 0))
    except (TypeError, ValueError):
        supplier_code = 0
    if supplier_code <= 0:
        return None, f'GRN {rno} has no supplier.'
    if not _grn_is_inventory_posted(rno):
        return None, f'GRN {rno} is not posted to stock. Post inventory before creating a purchase return.'
    details = _get_receipt_details(rno)
    if not details:
        return None, f'GRN {rno} has no lines.'
    clean_lines: List[Dict[str, Any]] = []
    for ln in details:
        if not isinstance(ln, dict):
            continue
        try:
            item_code = int(float(ln.get('itemcode') or 0))
        except (TypeError, ValueError):
            item_code = 0
        if item_code <= 0:
            continue
        try:
            qty_rcv = abs(float(ln.get('receivedqty') if ln.get('receivedqty') is not None else 0))
        except (TypeError, ValueError):
            qty_rcv = 0.0
        try:
            qty_ord = abs(float(ln.get('quantity') or 0))
        except (TypeError, ValueError):
            qty_ord = 0.0
        qty = qty_rcv if qty_rcv > 1e-9 else qty_ord
        if qty <= 1e-9:
            continue
        try:
            rate = abs(float(ln.get('rate') or 0))
        except (TypeError, ValueError):
            rate = 0.0
        try:
            discount = abs(float(ln.get('discount') or 0))
        except (TypeError, ValueError):
            discount = 0.0
        try:
            amount = abs(float(ln.get('amount') or 0))
        except (TypeError, ValueError):
            amount = 0.0
        if amount <= 1e-9:
            amount = round(max(0.0, qty * rate - discount), 2)
        try:
            conv = float(ln.get('uomfactor') if ln.get('uomfactor') is not None else ln.get('conversionfactor') or 1)
        except (TypeError, ValueError):
            conv = 1.0
        if conv <= 0:
            conv = 1.0
        wh_code = str(ln.get('warehouse_code') or ln.get('location') or '').strip()
        try:
            wh_id = int(float(ln.get('warehouse_id') or 0)) or None
        except (TypeError, ValueError):
            wh_id = None
        try:
            storage_id = int(float(ln.get('storage_id') or 0)) or None
        except (TypeError, ValueError):
            storage_id = None
        try:
            avg_cost = float(ln.get('averagecost') or ln.get('landingcost') or rate or 0)
        except (TypeError, ValueError):
            avg_cost = rate
        row: Dict[str, Any] = {
            'itemcode': item_code,
            'itemname': str(ln.get('itemname') or '').strip(),
            'barcode': str(ln.get('barcode') or '').strip(),
            'uom': str(ln.get('uom') or 'NOS').strip() or 'NOS',
            'conversionfactor': round(conv, 6),
            'uomfactor': round(conv, 6),
            'quantity': round(qty, 3),
            'rate': round(rate, 3),
            'discount': round(discount, 2),
            'amount': round(amount, 2),
            'store': wh_code,
            'location': wh_code,
            'warehouse_code': wh_code,
            'warehouse_id': wh_id,
            'storage_id': storage_id,
            'averagecost': round(avg_cost, 4),
            'batch_no': str(ln.get('batch_no') or '').strip() or None,
        }
        clean_lines.append(row)
    if not clean_lines:
        return None, f'GRN {rno} has no returnable quantities.'
    try:
        hdr_wh = int(float(hdr.get('warehouse_id') or 0)) or None
    except (TypeError, ValueError):
        hdr_wh = None
    if not hdr_wh:
        line_whs = {int(x['warehouse_id']) for x in clean_lines if x.get('warehouse_id')}
        if len(line_whs) == 1:
            hdr_wh = next(iter(line_whs))
    si_note = f'From GRN #{rno}'
    existing_remarks = str(hdr.get('remarks') or '').strip()
    remarks = '; '.join(p for p in (existing_remarks, si_note) if p).strip('; ')
    if si_note.lower() in existing_remarks.lower():
        remarks = existing_remarks
    header_out: Dict[str, Any] = {
        'suppliercode': supplier_code,
        'receiptno': rno,
        'warehouse_id': hdr_wh,
        'warehouse_code': str(hdr.get('warehouse_code') or '').strip() or None,
        'warehouse_name': str(hdr.get('warehouse_name') or '').strip() or None,
        'remarks': remarks,
        'sectioninc': remarks,
        'source_receipt_no': rno,
    }
    return {'header': header_out, 'lines': clean_lines, 'source_receipt_no': rno}, None


@bp.route('/purchase/return/api/load-from-grn/<path:receipt_no>')
def api_purchase_return_load_from_grn(receipt_no: int):
    """Load a posted GRN into the Purchase Return form (supplier + lines)."""
    if not session.get('user'):
        return jsonify({'error': 'Not authenticated'}, 401)
    _apply_db()
    payload, err = _grn_to_purchase_return_payload(receipt_no)
    if err or not payload:
        code = 404 if err and 'not found' in err.lower() else 400
        return jsonify({'success': False, 'error': err or 'Load failed'}, code)
    return jsonify({'success': True, **payload})


@bp.route('/purchase/return/api/grn-picker', methods=['GET'])
def api_purchase_return_grn_picker():
    """Posted GRN list for F1 picker on Purchase Return / Return Order."""
    if not session.get('user'):
        return jsonify({'success': False, 'error': 'Not authenticated'}, 401)
    _apply_db()
    try:
        page = max(1, int(request.args.get('page') or 1))
    except (TypeError, ValueError):
        page = 1
    try:
        per_page = max(20, min(int(request.args.get('per_page') or 50), 100))
    except (TypeError, ValueError):
        per_page = 50
    search = (request.args.get('search') or '').strip() or None
    try:
        rows, total_count = _get_receipt_list_page(
            page=page,
            per_page=per_page,
            search=search,
            inventory_tab='posted',
        )
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}, 500)
    out: List[Dict[str, Any]] = []
    for r in rows or []:
        rno = coerce_receiptno(r.get('receiptno'))
        if not receiptno_is_valid(rno):
            continue
        dt = r.get('receiptdate')
        if dt and hasattr(dt, 'strftime'):
            dt = dt.strftime('%Y-%m-%d')
        elif dt:
            dt = str(dt)[:10]
        else:
            dt = ''
        try:
            amt = float(r.get('amount') or 0)
        except (TypeError, ValueError):
            amt = 0.0
        out.append({
            'receiptno': rno,
            'receiptdate': dt,
            'suppliercode': r.get('suppliercode'),
            'suppliername': str(r.get('suppliername') or '').strip(),
            'invoiceno': str(r.get('invoiceno') or '').strip(),
            'amount': round(amt, 2),
        })
    total_pages = (total_count + per_page - 1) // per_page if total_count > 0 else 1
    return jsonify({
        'success': True,
        'rows': out,
        'total_count': total_count,
        'page': page,
        'items_per_page': per_page,
        'total_pages': total_pages,
    })


@bp.route('/purchase/return/api/save', methods=['POST'])
def api_purchase_return_save():
    if not session.get('user'):
        return jsonify({'error': 'Not authenticated'}, 401)
    _apply_db()
    if not _try_acquire_session_lock(_PR_SAVE_SESSION_LOCK_UNTIL):
        return json_response_rotate_global({'success': False, 'error': 'A purchase return save is already in progress for this session. Please wait until it completes.', 'save_session_locked': True}, 423)
    try:
        if not verify_consume_save_nonce(GLOBAL_SAVE_NONCE_SESSION_KEY, extract_submitted_save_nonce(request)):
            return replay_blocked_response_global()
        data = request.get_json(silent=True) or {}
        goods_return_no = parse_goodsreturnno_from_request(data.get('goodsreturnno'))
        return_date = (data.get('returndate') or '')[:10]
        open_date, txn_err = _enforce_purchase_open_date(return_date, 'purchase_return')
        if txn_err:
            return json_response_rotate_global(
                {'success': False, 'error': txn_err, 'transaction_date_blocked': True},
                400,
            )
        return_date = open_date or return_date
        posting_date = (data.get('postingdate') or data.get('posting_date') or return_date or '')[:10]
        if posting_date:
            open_pd, pd_err = _enforce_purchase_open_date(posting_date, 'purchase_return')
            if pd_err:
                return json_response_rotate_global(
                    {'success': False, 'error': pd_err, 'transaction_date_blocked': True},
                    400,
                )
            posting_date = open_pd or posting_date
        else:
            posting_date = return_date
        supplier_code = int(data.get('suppliercode') or 0)
        receipt_raw = data.get('receiptno')
        if receipt_raw not in (None, '', 0, '0'):
            receipt_no = parse_receiptno_from_request(receipt_raw)
            if not receiptno_is_valid(receipt_no):
                receipt_no = None
        else:
            receipt_no = None
        return_type = (data.get('returntype') or 'P')[:1]
        remarks = (data.get('remarks') or '').strip()
        return_amount = float(data.get('returnamount') or 0)
        source_return_order_no_raw = data.get('return_order_no')
        try:
            source_return_order_no = int(source_return_order_no_raw) if source_return_order_no_raw not in (None, '', 0, '0') else None
        except (TypeError, ValueError):
            source_return_order_no = None
        lines = data.get('lines') or []
        if not goodsreturnno_is_valid(goods_return_no) or not return_date or (not supplier_code):
            return json_response_rotate_global({'success': False, 'error': 'Return No, Date and Supplier are required'}, 400)
        if not lines:
            return json_response_rotate_global({'success': False, 'error': 'Add at least one return line'}, 400)
        pr_line_err = _validate_purchase_doc_save_lines(lines, doc_label='purchase return')
        if pr_line_err:
            return json_response_rotate_global({'success': False, 'error': pr_line_err}, 400)
        header_wh_raw = data.get('warehouse_id')
        header_warehouse_id: Optional[int] = None
        if header_wh_raw not in (None, ''):
            try:
                header_warehouse_id = int(header_wh_raw)
                if header_warehouse_id <= 0:
                    header_warehouse_id = None
            except (TypeError, ValueError):
                header_warehouse_id = None
        wh_err = _validate_purchase_return_warehouse_lines(
            lines, header_warehouse_id=header_warehouse_id, doc_label='purchase return',
        )
        if wh_err:
            return json_response_rotate_global({'success': False, 'error': wh_err}, 400)
        header_discount = float(data.get('discount') or 0)
        lines = _apply_pr_header_discount_to_lines(list(lines), header_discount)
        if source_return_order_no and _get_return_request_approval_status(source_return_order_no) != 'APPROVED':
            return json_response_rotate_global({'success': False, 'error': 'Only approved return requests can be posted to Purchase Return'}, 400)
        save_mode = (data.get('save_mode') or 'pr_posting').strip().lower()
        if save_mode in ('draft', 'pr_draft', 'grn_draft'):
            save_mode = 'pr_draft'
        elif save_mode in ('inventory_only', 'pr_only', 'grn_only', 'approved', 'pr_post'):
            save_mode = 'pr_only'
        elif save_mode in ('inventory_accounts', 'pr_posting', 'grn_invoice_posting', 'accounts'):
            save_mode = 'pr_posting'
        else:
            save_mode = 'pr_posting'
        post_inventory_raw = data.get('post_inventory')
        if post_inventory_raw is not None:
            if isinstance(post_inventory_raw, str):
                post_inventory = post_inventory_raw.strip().lower() not in ('0', 'false', 'no', '')
            else:
                post_inventory = bool(post_inventory_raw)
        elif save_mode == 'pr_draft':
            post_inventory = False
        else:
            post_inventory = True
        post_accounts = save_mode == 'pr_posting'
        requested_no = goods_return_no
        goods_return_no, pr_reassigned = _resolve_purchase_return_no_for_save(requested_no)
        has_requested = returnhdr_goodsreturnno_is_valid_match(requested_no)
        pr_existed = not pr_reassigned and has_requested and _get_posted_purchase_return_header(requested_no, return_type='P,R') is not None
        if not pr_reassigned and has_requested and _pr_is_inventory_posted(requested_no):
            return json_response_rotate_global({
                'success': False,
                'error': 'This purchase return is posted to stock. Only draft returns can be edited.',
                'inventory_posted': True,
            }, 400)
        if not pr_reassigned and has_requested and _purchase_return_is_posted(requested_no):
            return json_response_rotate_global({
                'success': False,
                'error': 'This purchase return is posted to accounts. It cannot be changed.',
                'accounts_posted': True,
            }, 400)
        before_snap = None
        if pr_existed:
            before_snap = _audit_pr_snapshot(
                _get_posted_purchase_return_header(requested_no, return_type='P,R'),
                _get_posted_purchase_return_details(requested_no),
            )
        err: Optional[str] = None
        for _dup_try in range(8):
            err = _save_purchase_return(
                goods_return_no=goods_return_no,
                return_date=return_date,
                supplier_code=supplier_code,
                receipt_no=receipt_no,
                return_amount=return_amount,
                return_type=return_type,
                remarks=remarks,
                lines=lines,
                source_return_order_no=source_return_order_no,
                post_inventory=post_inventory,
                posting_date=posting_date,
                warehouse_id=header_warehouse_id,
                discount=header_discount,
            )
            if not err:
                break
            if not _is_duplicate_doc_key_error(err):
                break
            retry_no = _allocate_next_free_purchase_return_no(goods_return_no)
            if retry_no <= goods_return_no:
                retry_no = goods_return_no + 1
                while _returnhdr_doc_exists(retry_no) and retry_no < goods_return_no + 100:
                    retry_no += 1
            if retry_no == goods_return_no:
                break
            goods_return_no = retry_no
            pr_reassigned = True
        if err:
            body = {'success': False, 'error': err}
            if _is_duplicate_doc_key_error(err):
                body['duplicate_doc_key'] = True
                body['suggested_goodsreturnno'] = _allocate_next_free_purchase_return_no(goods_return_no)
            return json_response_rotate_global(body, 400)
        if pr_existed:
            after_snap = _audit_pr_snapshot_from_payload(data)
            _log_purchase_change(
                'PR', goods_return_no, 'EDIT',
                remarks or 'Purchase return updated',
                before=before_snap,
                after=after_snap,
            )
        accounts_posted = False
        if post_inventory and post_accounts:
            acct_err = _post_saved_purchase_return(
                goods_return_no, source_return_order_no=source_return_order_no,
            )
            if acct_err:
                return json_response_rotate_global({
                    'success': False,
                    'error': (
                        f'Purchase return {goods_return_no} saved and stock posted, '
                        f'but accounts posting failed: {acct_err}'
                    ),
                    'goodsreturnno': goods_return_no,
                    'inventory_posted': True,
                    'accounts_posted': False,
                }, 400)
            accounts_posted = True
        try:
            with _get_connection() as conn:
                with conn.cursor() as cur:
                    from addons.document_numbering.document_numbering_db import advance_document_series_after_save_cur
                    advance_document_series_after_save_cur(
                        cur, DOC_TYPE_PURCHASE_RETURN, goods_return_no,
                        location_code=_resolve_location_code(),
                        reset_no=RESET_NO,
                        user=str(session.get('user') or 'web'),
                    )
                conn.commit()
        except Exception:
            pass
        if post_inventory:
            if post_accounts and accounts_posted:
                msg = 'Purchase return saved and posted (stock + GL / supplier reversal).'
            else:
                msg = 'Purchase return saved. Stock and item journal updated. Use Accounts Posting for GL when needed.'
        else:
            msg = 'Purchase return saved as draft. Stock is not posted yet — open the return and choose Approve & post Inventory Only or POST inventory and Accounts when ready.'
        if pr_reassigned:
            if post_inventory and post_accounts and accounts_posted:
                msg = f'Return number {requested_no} was already in use. Saved as return {goods_return_no} and posted (stock + GL).'
            elif post_inventory:
                msg = f'Return number {requested_no} was already in use. Saved as return {goods_return_no}. Stock and item journal updated.'
            else:
                msg = f'Return number {requested_no} was already in use. Saved as return {goods_return_no} (draft).'
        return json_response_rotate_global({
            'success': True,
            'goodsreturnno': goods_return_no,
            'requested_goodsreturnno': requested_no,
            'goodsreturnno_reassigned': pr_reassigned,
            'next_goodsreturnno': _purchase_return_next_no(),
            'list_url': url_for('purchase.purchase_return_list') if pr_existed else None,
            'message': msg,
            'save_mode': save_mode,
            'inventory_posted': bool(post_inventory),
            'accounts_posted': accounts_posted,
            'pdf_url': url_for('purchase.api_purchase_return_pdf', goods_return_no=goods_return_no),
        })
    finally:
        _release_session_lock(_PR_SAVE_SESSION_LOCK_UNTIL)

@bp.route('/purchase/return/api/delete', methods=['POST'])
def api_purchase_return_delete():
    if not session.get('user'):
        return jsonify({'error': 'Not authenticated'}, 401)
    _apply_db()
    if not _try_acquire_session_lock(_PR_SAVE_SESSION_LOCK_UNTIL):
        return json_response_keep_global_nonce({
            'success': False,
            'error': 'A purchase return operation is already in progress for this session. Please wait.',
            'save_session_locked': True,
        }, 423)
    try:
        submitted_nonce = extract_submitted_save_nonce(request)
        if not reject_invalid_form_save_nonce(submitted_nonce, session_key=GLOBAL_SAVE_NONCE_SESSION_KEY):
            return replay_blocked_response_global()
        data = request.get_json(silent=True) or {}
        goods_return_no = parse_goodsreturnno_from_request(data.get('goodsreturnno'))
        if not returnhdr_goodsreturnno_is_valid_match(goods_return_no):
            return json_response_keep_global_nonce({'success': False, 'error': 'Return No is required'}, 400)
        pwd_err = _verify_grn_delete_user_password(data.get('password'))
        if pwd_err:
            return json_response_keep_global_nonce({'success': False, 'error': pwd_err}, 403)
        before_snap = _audit_pr_snapshot(
            _get_posted_purchase_return_header(goods_return_no, return_type='P,R'),
            _get_posted_purchase_return_details(goods_return_no),
        )
        err = _delete_purchase_return(goods_return_no)
        if err:
            return json_response_keep_global_nonce({'success': False, 'error': err}, 400)
        if not commit_form_save_nonce(submitted_nonce, session_key=GLOBAL_SAVE_NONCE_SESSION_KEY):
            return replay_blocked_response_global()
        _log_purchase_change(
            'PR', goods_return_no, 'DELETE',
            'Draft purchase return deleted.',
            before=before_snap,
        )
        return json_response_rotate_global({
            'success': True,
            'goodsreturnno': goods_return_no,
            'message': f'Purchase return {goods_return_no} deleted.',
            'list_url': url_for('purchase.purchase_return_list'),
        })
    finally:
        _release_session_lock(_PR_SAVE_SESSION_LOCK_UNTIL)

@bp.route('/purchase/return/api/post', methods=['POST'])
def api_purchase_return_post():
    if not session.get('user'):
        return jsonify({'error': 'Not authenticated'}, 401)
    _apply_db()
    if not verify_consume_save_nonce(GLOBAL_SAVE_NONCE_SESSION_KEY, extract_submitted_save_nonce(request)):
        return replay_blocked_response_global()
    data = request.get_json(silent=True) or {}
    goods_return_no = parse_goodsreturnno_from_request(data.get('goodsreturnno'))
    source_return_order_no_raw = data.get('return_order_no')
    try:
        source_return_order_no = int(source_return_order_no_raw) if source_return_order_no_raw not in (None, '', 0, '0') else None
    except (TypeError, ValueError):
        source_return_order_no = None
