@bp.route('/purchase/return/api/post-selected', methods=['POST'])
def api_pr_post_selected():
    """Bulk post saved purchase returns (same pattern as purchase invoice posting; no per-request save nonce)."""
    if not session.get('user'):
        return jsonify({'error': 'Not authenticated'}, 401)
    try:
        _apply_db()
        data = request.get_json(silent=True) or {}
        raw_nos = data.get('goods_return_nos') or []
        seen: set = set()
        goods_nos: List[Any] = []
        for x in raw_nos:
            gno = parse_goodsreturnno_from_request(x)
            if not returnhdr_goodsreturnno_is_valid_match(gno):
                continue
            key = str(gno)
            if key in seen:
                continue
            seen.add(key)
            goods_nos.append(gno)
        if not goods_nos:
            return jsonify({'success': False, 'error': 'Select at least one return'}, 400)
        posted: List[Any] = []
        failed: List[Dict[str, Any]] = []
        for gno in goods_nos:
            try:
                err = _post_saved_purchase_return(gno, source_return_order_no=None)
            except Exception as ex:
                print(f'[ERROR api_pr_post_selected] goods_return_no={gno}: {ex}')
                traceback.print_exc()
                failed.append({'goods_return_no': gno, 'error': str(ex) or repr(ex)})
                continue
            if err:
                failed.append({'goods_return_no': gno, 'error': err})
            else:
                posted.append(gno)
        ok = len(failed) == 0
        msg = f'Posted {len(posted)} return(s).' if ok else f'Posted {len(posted)} return(s), failed {len(failed)}.'
        return jsonify({'success': ok, 'message': msg, 'posted_count': len(posted), 'posted_goods_returns': posted, 'failed_count': len(failed), 'failed': failed})
    except Exception as ex:
        print(f'[ERROR api_pr_post_selected] {ex}')
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(ex) or 'Server error', 'posted_count': 0}, 500)

