def _debit_note_request_can_edit(header: Optional[Dict[str, Any]]) -> bool:
    if not header:
        return False
    if str(header.get('approval_status') or '').strip().upper() == 'CANCELLED':
        return False
    if _debit_note_request_effective_posted_dr_no(header) > 0:
        return False
    return True

