@bp.route('/purchase/invoice/api/save', methods=['POST'])
def api_pi_save():
    if not session.get('user'):
        return jsonify({'error': 'Not authenticated'}, 401)
    _apply_db()
    data = request.get_json(silent=True) or {}
    pi_no = int(data.get('purchaseinvoiceno') or 0)
    invoice_date = (data.get('invoicedate') or '')[:10]
    supplier_code = int(data.get('suppliercode') or 0)
    supplier_inv_no = (data.get('supplierinvoiceno') or '').strip()
    supplier_inv_date = (data.get('supplierinvoicedate') or '')[:10]
    subtotal = float(data.get('subtotal') or 0)
    discount = float(data.get('discount') or 0)
    vat_amount = float(data.get('vatamount') or 0)
    total_amount = float(data.get('totalamount') or 0)
    remarks = (data.get('remarks') or '').strip()
    lines = data.get('lines') or []
    if not pi_no or not invoice_date or (not supplier_code):
        return jsonify({'success': False, 'error': 'Invoice No, Date and Supplier are required'}, 400)
    err = _save_purchase_invoice(pi_no, invoice_date, supplier_code, supplier_inv_no, supplier_inv_date, subtotal, discount, vat_amount, total_amount, remarks, lines)
    if err:
        return jsonify({'success': False, 'error': err}, 400)
    return jsonify({'success': True, 'next_purchaseinvoiceno': _pi_next_no()})

